import net.runelite.client.util.Text;

/** Reserve header space for the picker without covering the native title. */
final class BankHeaderTitle
{
    private Widget widget;
    private int x,width,xMode,widthMode,appliedWidth;
    private String originalText,appliedText;
    private static final int LEFT=52;

    void update(Widget current,int right) {
        if(current!=widget) { clear();widget=current; }
        if(widget==null) return;
        if(appliedText==null || widget.getOriginalX()!=LEFT) x=widget.getOriginalX();
        if(appliedText==null || widget.getXPositionMode()!=WidgetPositionMode.ABSOLUTE_LEFT) xMode=widget.getXPositionMode();
        if(appliedText==null || widget.getOriginalWidth()!=appliedWidth) width=widget.getOriginalWidth();
        if(appliedText==null || widget.getWidthMode()!=WidgetSizeMode.ABSOLUTE) widthMode=widget.getWidthMode();
        if(!Objects.equals(widget.getText(),appliedText)) originalText=widget.getText();
        if(originalText==null) originalText="";
        appliedWidth=Math.max(1,right-LEFT);
        appliedText=originalText;
        if(widget.getFont()!=null && widget.getFont().getTextWidth(originalText)>appliedWidth) {
            String plain=Text.removeTags(originalText);
            int end=plain.length();
            while(end>0 && widget.getFont().getTextWidth(plain.substring(0,end)+"...")>appliedWidth) end--;
            appliedText=plain.substring(0,end)+"...";
        }
        widget.setOriginalX(LEFT);widget.setXPositionMode(WidgetPositionMode.ABSOLUTE_LEFT);
        widget.setOriginalWidth(appliedWidth);widget.setWidthMode(WidgetSizeMode.ABSOLUTE);
        widget.setText(appliedText);widget.revalidate();
    }

    void clear() {
        if(widget!=null && appliedText!=null) {
            if(widget.getOriginalX()==LEFT) widget.setOriginalX(x);
            if(widget.getXPositionMode()==WidgetPositionMode.ABSOLUTE_LEFT) widget.setXPositionMode(xMode);
            if(widget.getOriginalWidth()==appliedWidth) widget.setOriginalWidth(width);
            if(widget.getWidthMode()==WidgetSizeMode.ABSOLUTE) widget.setWidthMode(widthMode);
            if(Objects.equals(widget.getText(),appliedText)) widget.setText(originalText);
            widget.revalidate();
        }
        widget=null;originalText=null;appliedText=null;
    }
}

package com.windowmarkers;

import java.awt.Rectangle;
import net.runelite.api.widgets.Widget;

/** Geometry for direct children of the bank item container, including new preview copies. */
final class BankItemBounds
{
    private BankItemBounds() {}

    static Rectangle of(Widget container,Widget item)
    {
        // Widget.getBounds() uses a cached canvas position. A newly created copy
        // has not been drawn yet during BeforeRender, and moved cells still have
        // the previous layout's position. Relative coordinates are ready after revalidate().
        Rectangle viewport=container.getBounds();
        return new Rectangle(viewport.x+item.getRelativeX()-container.getScrollX(),
            viewport.y+item.getRelativeY()-container.getScrollY(),item.getWidth(),item.getHeight());
    }
}

package com.windowmarkers;

import java.awt.image.BufferedImage;
import java.util.*;
import java.util.function.*;
import javax.inject.Inject;
import javax.swing.*;
import net.runelite.api.Client;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;

/** Incremental client-thread reads; fuzzy ranking runs off the client thread. */
final class BankItemSearch
{
    static final class Choice
    {
        final int id;
        final String name, search;
        BufferedImage image;
        Choice(int id,String name) { this.id=id; this.name=name; search=SearchText.normalize(name); }
        @Override public String toString() { return name+" (#"+id+")"; }
    }
    @Inject Client client;
    @Inject ClientThread thread;
    @Inject ItemManager items;
    private final List<Choice> catalogue=new ArrayList<>();
    private int cursor,size;
    void search(String query,Set<Integer> allowed,BooleanSupplier wanted,Consumer<List<Choice>> done)
    {
        thread.invokeLater(() -> {
            if(!wanted.getAsBoolean()) return true;
            int count=Math.min(client.getItemCount(),100000);
            if(count!=size) { catalogue.clear(); cursor=0; size=count; }
            int end=Math.min(cursor+256,size);
            while(cursor<end)
            {
                int id=cursor++; var item=items.getItemComposition(id);
                if(item==null) continue;
                String name=item.getName();
                if(name!=null && !name.isBlank() && !name.equalsIgnoreCase("null") && item.getNote()==-1 && item.getPlaceholderTemplateId()==-1)
                    catalogue.add(new Choice(id,name));
            }
            if(cursor<size) return false;
            List<Choice> snapshot=new ArrayList<>(catalogue);
            new SwingWorker<List<Choice>,Void>() {
                protected List<Choice> doInBackground() { return rank(snapshot,query,allowed); }
                protected void done() {
                    if(!wanted.getAsBoolean()) return;
                    try {
                        List<Choice> matches=get();
                        thread.invokeLater(() -> {
                            if(!wanted.getAsBoolean()) return;
                            for(Choice choice:matches) choice.image=items.getImage(choice.id);
                            SwingUtilities.invokeLater(() -> { if(wanted.getAsBoolean()) done.accept(matches); });
                        });
                    } catch(Exception ex) { done.accept(Collections.emptyList()); }
                }
            }.execute();
            return true;
        });
    }
    static List<Choice> rank(List<Choice> choices,String query,Set<Integer> allowed)
    {
        String needle=SearchText.normalize(query);
        Map<Choice,Integer> scores=new IdentityHashMap<>();
        for(Choice c:choices) if(allowed==null || allowed.contains(c.id))
        { int score=SearchText.normalizedScore(c.search,needle); if(score!=Integer.MAX_VALUE) scores.put(c,score); }
        List<Choice> result=new ArrayList<>(scores.keySet());
        result.sort(Comparator.comparingInt((Choice c)->scores.get(c)).thenComparing(c->c.name).thenComparingInt(c->c.id));
        return new ArrayList<>(result.subList(0,Math.min(80,result.size())));
    }
}

package com.windowmarkers;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import net.runelite.client.ui.overlay.components.TooltipComponent;
import net.runelite.client.util.Text;

/** Compact bank hover summaries; full source notes stay in the guide data. */
final class BankItemTooltip extends TooltipComponent
{
    static final int MAX_LINES=6;
    private final String summary;
    private final int width;

    BankItemTooltip(String summary,int width,Color background)
    {
        this.summary=summary;this.width=Math.max(40,Math.min(300,width));setBackgroundColor(background);
    }

    @Override public Dimension render(Graphics2D graphics)
    {
        // Use the tooltip renderer's actual font, including user font/size choices.
        setText(String.join("<br>",wrap(summary,graphics.getFontMetrics(),width)));
        return super.render(graphics);
    }

    static String summary(ItemCatalogueIndex.Rank rank,String note)
    {
        Set<String> lines=new LinkedHashSet<>(),context=new LinkedHashSet<>();
        List<String> details=new ArrayList<>();boolean sourceNotes=false;
        if(rank!=null) {
            String[] raw=rank.explanation.split("\\R");
            String ordinal=TierPresentation.ordinal(rank.tier);
            lines.add(ordinal.isEmpty()?shortNote(raw[0]):"Guide: "+ordinal+" choice for this setup"+(rank.role.isEmpty()?"":" ("+rank.role+")")+".");
            for(int i=1;i<raw.length;i++) {
                String line=raw[i].trim();int split=line.indexOf(": Wiki column ");
                if(split<0)split=line.indexOf(": reduced function;");
                if(split<0)split=line.indexOf(": provisional or ordered choices;");
                if(split>=0) {
                    String source=line.substring(0,split).replace(" — Equipment alternatives","").replace(" - Equipment alternatives","");
                    if(context.size()<2)context.add(source.replace(" / "," · "));sourceNotes=true;
                } else if(!line.isEmpty()) details.add(line);
            }
        }
        // Item-state warnings precede optional context and long guide commentary.
        if(note!=null) {
            int state=note.indexOf("Item state");
            if(state>=0)lines.add(shortNote(note.substring(state)));
        }
        for(String detail:details)if(detail.startsWith("Item state"))lines.add(shortNote(detail));
        for(String detail:details)if(!detail.startsWith("Item state"))lines.add(shortNote(detail));
        if(note!=null&&!note.isBlank())lines.add(shortNote(note));
        lines.addAll(context);
        if(sourceNotes)lines.add("Full notes: Guide choices.");
        lines.remove("");return String.join("\n",lines);
    }

    private static String shortNote(String text)
    {
        String value=text.replaceAll("\\s+"," ").trim()
            .replace("Showing an owned alternative; live prices are not compared.","Owned alternative.");
        if(value.length()<=180)return value;
        int end=value.lastIndexOf(' ',177);return value.substring(0,end>100?end:177)+"...";
    }

    static List<String> wrap(String text,FontMetrics metrics,int width)
    {
        List<String> lines=new ArrayList<>();boolean truncated=false;
        for(String paragraph:text.split("\\R")) {
            String remaining=paragraph.trim().replaceAll("\\s+"," ");
            while(!remaining.isEmpty()) {
                if(lines.size()==MAX_LINES){truncated=true;break;}
                int end=0;
                while(end<remaining.length()) {
                    int next=remaining.offsetByCodePoints(end,1);
                    if(metrics.stringWidth(Text.escapeJagex(remaining.substring(0,next)))>width)break;
                    end=next;
                }
                if(end==0)end=remaining.offsetByCodePoints(0,1);
                if(end<remaining.length()) {int space=remaining.lastIndexOf(' ',end);if(space>0)end=space;}
                lines.add(Text.escapeJagex(remaining.substring(0,end).trim()));remaining=remaining.substring(end).trim();
            }
            if(truncated)break;
        }
        if(truncated&&!lines.isEmpty()) {
            String last=lines.get(lines.size()-1);
            // The escaped line may contain literal tag escapes: shorten the raw
            // last line instead of ever leaving a partial Jagex control tag.
            last=Text.removeTags(last.replace("<lt>","‹").replace("<gt>","›"));
            while(!last.isEmpty()&&metrics.stringWidth(last+"...")>width)last=last.substring(0,last.offsetByCodePoints(last.length(),-1));
            lines.set(lines.size()-1,Text.escapeJagex(last)+"...");
        }
        return lines;
    }
}

