	void startUp()
	{
        inventoryWidgets.setClient(client);
		active = true;controlDrag.resetInput();
        if(mouseManager!=null)mouseManager.registerMouseListener(0,controlDrag);
        if(overlayManager!=null)overlayManager.add(controlDrag.overlay);
		eventBus.register(this);
		// The frame has to be in place before the bank tags plugin sizes its tab column on this event,
		// the item grid can only be reflowed after it has laid out its tag tabs.
		frameSubscriber = eventBus.register(ScriptPreFired.class, this::layoutFrame, 10);
		clientThread.invokeLater(this::rebuildBank);
	}

	void shutDown()
	{
		active = false;
        controlDrag.resetInput();
        if(mouseManager!=null)mouseManager.unregisterMouseListener(controlDrag);
        if(overlayManager!=null)overlayManager.remove(controlDrag.overlay);
		eventBus.unregister(this);
		eventBus.unregister(frameSubscriber);
		clientThread.invokeLater(() ->
		{
			restore();
			rebuildBank();
		});
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if ("windowmarkers".equals(event.getGroup()) && Arrays.asList("bankLayoutEnabled","customWidth","width","customHeight","height","columns","depositButtons","alignDepositRight","tabAlignment","tabGap","setupSearchLayout","customBankControls","bankControlLayout","bankButtonDragging").contains(event.getKey()))
		{
            controlDrag.clear();
			clientThread.invokeLater(() -> { restoreTabs(); restore(); rebuildBank(); });
		}
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		if (event.getGroupId() == InterfaceID.BANKMAIN)
		{
            controlDrag.clear();controls.clear();
            inventoryWidgets.clear();
            hiddenSeparators.clear();
            viewGeometry.clear(); searchHeadings.clear(); inventoryNotes.clear();
            // Restore surviving widgets as well as the modal. An unfinished Alt-drag
            // must not leave changed quantity children behind on a soft close.
            restore();
		}
	}

    @Subscribe public void onProfileChanged(net.runelite.client.events.ProfileChanged event)
    { controlDrag.clear();clientThread.invokeLater(() -> { restore(); rebuildBank(); }); }

	private void layoutFrame(ScriptPreFired event)
	{
		if(event.getScriptId()==ScriptID.BANKMAIN_BUILD) {
            viewGeometry.clear(); searchHeadings.clear(); inventoryNotes.clear();
            inventoryWidgets.clear();
            // Restore before the native builder establishes visibility for this build.
            restoreSeparators();
        }
		if (active && config.bankLayoutEnabled() && event.getScriptId() == ScriptID.BANKMAIN_FINISHBUILDING)
		{
			applyFrame();
		}
	}

	private void applyFrame()
	{
		if (!config.bankLayoutEnabled()) { return; }
		Widget universe = client.getWidget(InterfaceID.Bankmain.UNIVERSE);
		Widget container = client.getWidget(InterfaceID.Bankmain.ITEMS_CONTAINER);
		Widget items = client.getWidget(InterfaceID.Bankmain.ITEMS);
		if (universe == null || universe.isHidden() || container == null || items == null || items.isHidden() && !settingsVisible())
		{
			return;
		}

		applyUniverse(universe);
        layoutSettings();
        if(items.isHidden()) {
            revalidateTree(universe);
            appliedSignature=signature(universe);
            return;
        }
		fillWidth(client.getWidget(InterfaceID.Bankmain.TABS));
		fillWidth(client.getWidget(InterfaceID.Bankmain.TABS_LINE0));
		universe.revalidate();
		container.revalidate();
        controls.previewWidth=container.getWidth();controls.previewHeight=container.getHeight();

		// the build script resets the item grid to its vanilla width every time
		int[] s = baseSize(items);
		int gap=Math.max(0,Math.min(40,config.tabGap()));
        BankControlLayout.Plan controlPlan=customControls()?controls.plan(container):null;
        int inset=controlPlan==null?0:controlPlan.inset;
        int[] itemPosition=basePos(items);
        setPos(items,itemPosition[0]+inset,itemPosition[1]+gap,itemPosition[2],itemPosition[3]);
        setSize(items, ITEMS_WIDTH_MARGIN+inset, s[3]==WidgetSizeMode.MINUS ? s[1]+gap : Math.max(1,s[1]-gap), WidgetSizeMode.MINUS, s[3]);
        Widget scrollbar=client.getWidget(InterfaceID.Bankmain.SCROLLBAR);
        if(scrollbar!=null)
        {
            int[] scrollPosition=basePos(scrollbar),scrollSize=baseSize(scrollbar);
            setPos(scrollbar,scrollPosition[0],scrollPosition[1]+gap,scrollPosition[2],scrollPosition[3]);
            setSize(scrollbar,scrollSize[0],scrollSize[3]==WidgetSizeMode.MINUS ? scrollSize[1]+gap : Math.max(1,scrollSize[1]-gap),scrollSize[2],scrollSize[3]);
        }

        if(controlPlan==null) layoutBottom(container);
        else controls.apply(container,controlPlan);
		revalidateTree(universe);
		appliedSignature = signature(universe);
        if(controlPlan!=null)controls.capture();
	}

	@Subscribe(priority = -10)
	public void onScriptPreFired(ScriptPreFired event)
	{
		if (!active || event.getScriptId() != ScriptID.BANKMAIN_FINISHBUILDING)
		{
			return;
		}

		Widget items = client.getWidget(InterfaceID.Bankmain.ITEMS);
		if (items == null)
		{
			return;
		}

        boolean grouped=groupedSearch();
        inventoryWidgets.clear();
        if(!config.bankLayoutEnabled() && !grouped && !ownsPreset()) return;
		if(grouped) hideSeparators(items);
		int[] ends = grouped ? layoutSearch(items) : reflowItems(items);
        if(ownsPreset() && ends!=null) {
            String identity=presetIdentity(),account=configs==null?null:configs.getRSProfileKey();
            String key=presetPositions==null?null:presetPositions.key(identity,items.getWidth());
            BankPresetPositions.Layout saved=presetPositions==null?new BankPresetPositions.Layout():presetPositions.read(account,key);
            ends[1]=viewGeometry.capture(items,saved,() -> {
                if(presetPositions!=null && java.util.Objects.equals(identity,presetIdentity())
                    && java.util.Objects.equals(key,presetPositions.key(presetIdentity(),items.getWidth())))
                    presetPositions.save(account,key,saved);
            },inventoryNotes,ends[1]);
            inventoryWidgets.allowPresetDragging();
        }
		reflowedWidth = items.getWidth();
		if (ends == null)
		{
			return;
		}

		int[] stack = client.getIntStack();
		int idx = client.getIntStackSize() - FINISHBUILDING_HEIGHT_ARG;
		// The temporary view owns the whole displayed layout. A tag-layout
        // subscriber may already have replaced the native height argument.
        if (idx>=0 && (searchView!=null && searchView.isActive() || grouped && ends[0]==0))
        {
            stack[idx]=Math.max(1,ends[1]+8);
            return;
        }
		// only touch the argument if it looks like the height of the layout we just replaced
		if (idx >= 0 && stack[idx] > 0 && Math.abs(stack[idx] - ends[0]) <= 2 * ROW_HEIGHT)
		{
			stack[idx] = Math.max(1, stack[idx] + ends[1] - ends[0]);
		}
	}

	@Subscribe(priority=-20)
	public void onScriptPostFired(ScriptPostFired event)
	{
		if (active && config.bankLayoutEnabled() && event.getScriptId() == ScriptID.BANKMAIN_SIZE_CHECK)
		{
			reapplyFrame();
		}
        if(active && config.bankLayoutEnabled() && event.getScriptId()==ScriptID.BANKMAIN_BUILD) alignTabs();
        // Bank Tag Layouts can auto-layout a temporary tag after finishbuilding.
        // Restore our current view's visible cells and positions, including
        // repeated supplies/phase gear; never touch another tag's layout.
        if(active && event.getScriptId()==ScriptID.BANKMAIN_BUILD && ownsPreset())
            viewGeometry.restore(client.getWidget(InterfaceID.Bankmain.ITEMS));
	}

    // Search refresh rebuilds the native tabs after ClientTick. Apply their final
    // positions after scripts, before any frame can display the intermediate layout.
    @Subscribe public void onFocusChanged(net.runelite.api.events.FocusChanged event) {if(!event.isFocused()){controlDrag.cancel();viewGeometry.cancelDrag();}}
    @Subscribe public void onGameStateChanged(net.runelite.api.events.GameStateChanged event) {
        if(event.getGameState()!=net.runelite.api.GameState.LOGGED_IN){controlDrag.cancel();viewGeometry.cancelDrag();}
    }
    @Subscribe(priority=-20)
    public void onBeforeRender(BeforeRender event)
    {
        if(active && config.bankLayoutEnabled()) {
            int update=controlDrag.update();if(update==2)restore();if(update>0)applyFrame();
            reapplyFrame();alignTabs();controlDrag.capture();
        }
        else controlDrag.clear();
        if(active && ownsPreset()) viewGeometry.restore(client.getWidget(InterfaceID.Bankmain.ITEMS));
    }

    // Run before Bank Tags snapshots the native drop target. Only display
    // positions in our current preset change; real bank order stays untouched.
    @Subscribe(priority=30)
    public void onWidgetDrag(net.runelite.api.events.WidgetDrag event)
    {
        if(!active || !ownsPreset()) return;
        Widget items=client.getWidget(InterfaceID.Bankmain.ITEMS);
        if(items==null || items.isHidden()) return;
        Widget dragged=client.getDraggedWidget();
        if(dragged!=null && dragged.getId()==InterfaceID.Bankmain.ITEMS) client.setDraggedOnWidget(null);
        String identity=presetIdentity();
        viewGeometry.drag(client,items,() -> active && ownsPreset()
            && java.util.Objects.equals(identity,presetIdentity()) && client.getWidget(InterfaceID.Bankmain.ITEMS)==items && !items.isHidden());
    }

    private boolean ownsPreset() { return searchView!=null && searchView.isActive() || groupedSearch(); }
    private String presetIdentity() {
        return searchView!=null && searchView.isActive()?searchView.layoutIdentity()+":"+searchView.bySlot():
            nativeSearch==null?null:nativeSearch.layoutIdentity()+":true";
    }

    void resetPresetPositions()
    {
        if(!active || !ownsPreset() || presetPositions==null || configs==null) return;
        Widget items=client.getWidget(InterfaceID.Bankmain.ITEMS);if(items==null || items.isHidden())return;
        presetPositions.save(configs.getRSProfileKey(),presetPositions.key(presetIdentity(),items.getWidth()),new BankPresetPositions.Layout());
        viewGeometry.clear();rebuildBank();
    }

	@Subscribe
	public void onClientTick(ClientTick event)
	{
		if (!active || !config.bankLayoutEnabled()) { return; }
		if (rebuildCooldown > 0)
		{
			rebuildCooldown--;
		}

		reapplyFrame();

		// Only width changes affect item wrapping. Finishbuilding may adjust the
		// viewport height after our hook; using that height here causes a rebuild loop.
		Widget items = client.getWidget(InterfaceID.Bankmain.ITEMS);
		if (appliedSignature != null && items != null && !items.isHidden() && rebuildCooldown == 0
			&& items.getWidth() != reflowedWidth)
		{
			rebuildCooldown = REBUILD_COOLDOWN_TICKS;
			clientThread.invokeLater(this::rebuildBank);
		}
	}

    @Subscribe(priority=-20)
    public void onScriptCallbackEvent(net.runelite.api.events.ScriptCallbackEvent event)
    {
        if(active && searchView!=null) searchView.filter(event);
        // Single-tab mode explicitly closes a native search input in BankMainBuild.
        // Use it only for saved views outside chatbox search, never while typing.
        if(active && "bankBuildTab".equals(event.getEventName())
            && client.getWidget(InterfaceID.Bankmain.ITEMS)!=null
            && client.getVarcIntValue(VarClientID.MESLAYERMODE)!=InputType.SEARCH.getType()
            && searchView!=null && searchView.isActive()) {
            int size=client.getIntStackSize();
            if(size>0) client.getIntStack()[size-1]=1;
        }
    }

	/**
	 * The game puts the bank and the modal back to their own sizes whenever the size of either changes,
	 * which includes us resizing them. Putting ours back right away, before a frame is drawn, keeps that
	 * from showing.
	 */
	private void reapplyFrame()
	{
		Widget universe = client.getWidget(InterfaceID.Bankmain.UNIVERSE);
		if (universe != null && (appliedSignature != null && !Arrays.equals(signature(universe), appliedSignature)
            || appliedSignature == null && settingsVisible()
            || customControls() && !settingsVisible() && controls.changed()))
		{
			applyFrame();
		}
	}

	private void rebuildBank()
	{
		Widget items = client.getWidget(InterfaceID.Bankmain.ITEMS);
		if (items == null || items.isHidden())
		{
			return;
		}

		Object[] build = items.getOnInvTransmitListener();
		if (build != null)
		{
			client.runScript(build);
		}
	}

	private int[] signature(Widget universe)
	{
		Widget modal = modal();
		Widget area = modal == null ? null : modal.getParent();
		return new int[]{
			universe.getOriginalX(), universe.getOriginalY(), universe.getXPositionMode(), universe.getYPositionMode(),
			universe.getOriginalWidth(), universe.getOriginalHeight(), universe.getWidthMode(), universe.getHeightMode(),
			modal == null ? 0 : modal.getOriginalWidth(), modal == null ? 0 : modal.getOriginalHeight(),
			area == null ? 0 : area.getWidth(), area == null ? 0 : area.getHeight(),settingsVisible()?1:0
		};
	}

	/**
	 * The top level interface's container the bank is opened in. It is 512px wide and clips the bank.
	 */
	private Widget modal()
	{
		Widget infinite = client.getWidget(InterfaceID.Bankmain.INFINITE);
		return infinite == null ? null : infinite.getParent();
	}

	private void applyModal(Widget modal)
	{
		Widget area = modal.getParent();
		int[] s = baseSize(modal);
		int width = s[0];
		int height = s[1];
		// in resizable mode the game already stretches the modal over the area's full height for the bank
		if (area != null && s[2] == WidgetSizeMode.ABSOLUTE && config.customWidth())
		{
			width = Math.max(width, Math.min(config.width(), area.getWidth()));
		}
		if (area != null && s[3] == WidgetSizeMode.ABSOLUTE && config.customHeight())
		{
			height = Math.max(height, Math.min(config.height() + MODAL_HEIGHT_MARGIN, area.getHeight()));
		}

		setSize(modal, width, height, s[2], s[3]);
		// The bank's root is sized from the modal by the engine. It has no parent component of its own,
		// so revalidating it directly would size it to the whole canvas.
		modal.revalidateScroll();
	}

	private void applyUniverse(Widget universe)
	{
		Widget parent = client.getWidget(InterfaceID.Bankmain.INFINITE);
		Widget modal = modal();
		if (modal != null)
		{
			applyModal(modal);
		}

		int[] p = basePos(universe);
		int[] s = baseSize(universe);
		int width = s[0];
		int height = s[1];
		if (config.customWidth() && s[2] == WidgetSizeMode.ABSOLUTE)
		{
			int max = parent == null ? s[0] : parent.getWidth();
			width = Math.max(s[0], Math.min(config.width(), max));
		}
		if (config.customHeight() && s[3] == WidgetSizeMode.ABSOLUTE)
		{
			int max = parent == null ? s[1] : parent.getHeight() - MODAL_HEIGHT_MARGIN;
			height = Math.max(Math.min(s[1], MIN_BANK_HEIGHT), Math.min(config.height(), Math.max(s[1], max)));
		}

        // The native settings form needs its full height even when the item view is short.
        if(settingsVisible() && s[3]==WidgetSizeMode.ABSOLUTE) height=Math.max(height,SETTINGS_TOP+SETTINGS_HEIGHT+5);
		setSize(universe, width, height, s[2], s[3]);
		if (height != s[1])
		{
			setPos(universe, p[0], 0, p[2], WidgetPositionMode.ABSOLUTE_CENTER);
		}
		else
		{
			setPos(universe, p[0], p[1], p[2], p[3]);
		}
	}

    private boolean settingsVisible() {
        Widget settings=client.getWidget(InterfaceID.Bankmain.MENU_CONTAINER);
        return settings!=null && !settings.isHidden();
    }

    private void layoutSettings() {
        Widget settings=client.getWidget(InterfaceID.Bankmain.MENU_CONTAINER);
        if(settings==null) return;
        // Native checkbox scripts anchor the two columns 251px from opposite
        // edges. Stretching their parent makes them overlap. Keep the whole
        // native form centred at its designed size, including its click targets.
        setSize(settings,SETTINGS_WIDTH,SETTINGS_HEIGHT,WidgetSizeMode.ABSOLUTE,WidgetSizeMode.ABSOLUTE);
        setPos(settings,0,SETTINGS_TOP,WidgetPositionMode.ABSOLUTE_CENTER,WidgetPositionMode.ABSOLUTE_TOP);
        for(int i=0;i<SETTINGS_ROWS.length;i++) {
            Widget row=client.getWidget(SETTINGS_ROWS[i]);if(row==null) continue;
            int[] p=basePos(row);
            // The first three rows start centred, then native init freezes their
            // Y in pixels. Normalize that Y too when opening a tall bank.
            setPos(row,p[0],23+(i/2)*28,p[2],WidgetPositionMode.ABSOLUTE_TOP);
        }
    }

	private void fillWidth(Widget widget)
	{
		if (widget != null)
		{
			int[] s = baseSize(widget);
			setSize(widget, 0, s[1], WidgetSizeMode.MINUS, s[3]);
		}
	}

	/**
	 * Lays out the bottom bar. The deposit buttons either stay in it, following the right edge of a widened
	 * bank, or are stacked at the bottom of the strip left of the items, pushing that strip's own buttons up.
	 */
	private void layoutBottom(Widget container)
	{
		Widget bottom = client.getWidget(InterfaceID.Bankmain.BOTTOM);
		if (bottom == null)
		{
			return;
		}

		int[] bp = basePos(bottom);
		int[] bs = baseSize(bottom);

		List<Widget[]> deposits = new ArrayList<>();
		if (config.depositButtons() == DepositButtons.LEFT && bp[3] == WidgetPositionMode.ABSOLUTE_BOTTOM && bs[3] == WidgetSizeMode.ABSOLUTE)
		{
			for (int[] ids : DEPOSIT_BUTTONS)
			{
				Widget button = client.getWidget(ids[0]);
				Widget icon = client.getWidget(ids[1]);
				if (button != null && icon != null && !button.isSelfHidden())
				{
					deposits.add(new Widget[]{button, icon});
				}
			}
		}
		boolean left = !deposits.isEmpty();

		// The deposit buttons can't leave the bar's layer, so the layer grows upwards over the strip
		// instead and everything else in it moves down by the same amount. Kept even so that vertically
		// centred children stay where they were.
		int grow = left ? LEFT_STRIP_GAP + deposits.size() * BUTTON_PITCH : 0;
		grow += grow & 1;
		setPos(bottom, bp[0], bp[1], bp[2], bp[3]);
		setSize(bottom, bs[0], bs[1] + grow, bs[2], bs[3]);

		int alignRight = !left && config.alignDepositRight()
			? Math.max(0, container.getWidth() - VANILLA_CONTAINER_WIDTH) : 0;
		for (Widget child : bottom.getStaticChildren())
		{
			if (left && isDepositButton(child.getId()))
			{
				continue;
			}

			int[] p = basePos(child);
			int[] s = baseSize(child);
			int x = p[0];
			int y = p[1];
			if (p[2] == WidgetPositionMode.ABSOLUTE_LEFT && x >= DEPOSIT_GROUP_X)
			{
				x += alignRight;
			}
			if (left && child.getId() == InterfaceID.Bankmain.DEPOSIT_LINE)
			{
				// nothing left to divide; park it out of view
				x = -1000;
			}
			if (p[3] == WidgetPositionMode.ABSOLUTE_TOP)
			{
				y += grow;
			}
			else if (p[3] == WidgetPositionMode.ABSOLUTE_CENTER)
			{
				y += grow / 2;
			}

			setPos(child, x, y, p[2], p[3]);
			setSize(child, s[0], s[3] == WidgetSizeMode.MINUS ? s[1] + grow : s[1], s[2], s[3]);
		}

		for (int i = 0; i < deposits.size(); i++)
		{
			Widget button = deposits.get(i)[0];
			Widget icon = deposits.get(i)[1];
			int[] p = basePos(button);
			int[] ip = basePos(icon);
			int y = i * BUTTON_PITCH;
			setPos(button, LEFT_STRIP_X, y, WidgetPositionMode.ABSOLUTE_LEFT, WidgetPositionMode.ABSOLUTE_TOP);
			setPos(icon, LEFT_STRIP_X + ip[0] - p[0], y + ip[1] - p[1], WidgetPositionMode.ABSOLUTE_LEFT, WidgetPositionMode.ABSOLUTE_TOP);
		}

		int lift = deposits.size() * BUTTON_PITCH;
		for (int id : LEFT_STRIP)
		{
			Widget widget = client.getWidget(id);
			if (widget != null)
			{
				int[] p = basePos(widget);
				setPos(widget, p[0], p[3] == WidgetPositionMode.ABSOLUTE_BOTTOM ? p[1] + lift : p[1], p[2], p[3]);
			}
		}
	}

	private static boolean isDepositButton(int id)
	{
		for (int[] ids : DEPOSIT_BUTTONS)
		{
			if (id == ids[0] || id == ids[1])
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Re-wraps the item grid the build script just laid out in 8 columns to the columns that fit now.
	 *
	 * @return {old content end, new content end}, or null if nothing was reflowed
	 */
	private int[] reflowItems(Widget items)
	{
		Widget[] children = items.getDynamicChildren();
		if (children == null)
		{
			return null;
		}

		int usable = items.getWidth() - LEFT_INSET - RIGHT_INSET;
		List<Widget> cells = new ArrayList<>();
		List<Widget> separators = new ArrayList<>();
        Map<Widget,Integer> tabDropAreas=new java.util.IdentityHashMap<>();
		for (Widget child : children)
		{
			if (child == null)
			{
				continue;
			}

            // A native tab's unused trailing slot is also 36x32 when the last
            // row contains seven items. It is a transparent RECTANGLE, not an
            // item; counting it creates an entire blank row after rewrapping.
			boolean cell = child.getType()==WidgetType.GRAPHIC && child.getItemId()>=0
                && child.getOriginalWidth() == CELL_WIDTH && child.getOriginalHeight() == CELL_HEIGHT;
            boolean tabDropArea=child.getType()==WidgetType.RECTANGLE && child.getOriginalHeight()==CELL_HEIGHT
                && child.getOpacity()==255 && child.isFilled() && child.getItemId()<0;
			if (!cell && !tabDropArea && child.getOriginalWidth() >= SEPARATOR_MIN_WIDTH && child.getOriginalWidth() != usable)
			{
				// tab separator lines and labels are created once, at the vanilla width
				child.setOriginalWidth(usable);
				child.revalidate();
			}

			if (!child.isSelfHidden())
			{
                if(tabDropArea) tabDropAreas.put(child,child.getOriginalY());
                else (cell ? cells : separators).add(child);
			}
		}

		// tag layouts are designed around the 8 column grid
		if (cells.isEmpty())
		{
			return null;
		}
        if (bankTagsService != null && bankTagsService.getActiveLayout() != null && !(searchView!=null && searchView.isActive()))
        {
            int end=0;
            for(Widget cell:cells) { end=Math.max(end,cell.getOriginalY()+ROW_HEIGHT); cell.setOriginalY(cell.getOriginalY()+4); cell.revalidate(); }
            for(Widget separator:separators) { separator.setOriginalY(separator.getOriginalY()+4); separator.revalidate(); }
            for(Widget area:tabDropAreas.keySet()) { area.setOriginalY(area.getOriginalY()+4);area.revalidate(); }
            return new int[]{end,end+4};
        }

		int columns = columns(usable);
		int pitch = columns > 1 ? CELL_WIDTH + (usable - columns * CELL_WIDTH) / (columns - 1) : CELL_WIDTH;

		cells.sort(Comparator.comparingInt(Widget::getOriginalY).thenComparingInt(Widget::getOriginalX));
		int count = cells.size();
		int[] oldY = new int[count];
		for (int i = 0; i < count; i++)
		{
			oldY[i] = cells.get(i).getOriginalY();
		}

		// {old start y, shift} of each section; in the "all items" view each tab is its own section
		List<int[]> shifts = new ArrayList<>();
		int oldEnd = 0;
		int newEnd = 4;
		int start = 0;
		while (start < count)
		{
			// a section is a run of full rows, directly below each other, closed by its last row
			int end = start + 1;
			int rowStart = start;
			while (end < count)
			{
				if (oldY[end] != oldY[end - 1])
				{
					if (oldY[end] - oldY[end - 1] != ROW_HEIGHT || end - rowStart != VANILLA_COLUMNS)
					{
						break;
					}
					rowStart = end;
				}
				end++;
			}

			// Native tab gaps can include a spare eight-column row. It is no longer
            // needed after wrapping to a wider bank; retain room for the tab heading.
            int gap=Math.max(0,oldY[start]-oldEnd);
			int newStart = newEnd + (start==0?gap:Math.min(24,gap));
			shifts.add(new int[]{oldY[start], newStart - oldY[start]});
			for (int i = start; i < end; i++)
			{
				Widget cell = cells.get(i);
				cell.setOriginalX(LEFT_INSET + ((i - start) % columns) * pitch);
				cell.setOriginalY(newStart + ((i - start) / columns) * ROW_HEIGHT);
				cell.revalidate();
			}

			newEnd = newStart + ((end - start + columns - 1) / columns) * ROW_HEIGHT;
            for(Map.Entry<Widget,Integer> entry:tabDropAreas.entrySet()) {
                if(entry.getValue()!=oldY[end-1]+ROW_HEIGHT-CELL_HEIGHT) continue;
                // Keep the native drag target on this tab's unused row tail,
                // never over real items or on a new row of its own.
                int used=(end-start)%columns,free=used==0?0:columns-used;
                Widget area=entry.getKey();
                area.setOriginalX(LEFT_INSET+used*pitch);
                area.setOriginalY(newEnd-CELL_HEIGHT);
                area.setOriginalWidth(free==0?0:free*CELL_WIDTH+(free-1)*(pitch-CELL_WIDTH));
                area.revalidate();
            }
			oldEnd = oldY[end - 1] + ROW_HEIGHT;
			start = end;
		}

		for (Widget separator : separators)
		{
			// a separator belongs to the section it sits above
			int y = separator.getOriginalY();
			int shift = newEnd - oldEnd;
			for (int[] section : shifts)
			{
				if (section[0] >= y)
				{
					shift = section[1];
					break;
				}
			}

			if (shift != 0)
			{
				separator.setOriginalY(y + shift);
				separator.revalidate();
			}
		}

		return new int[]{oldEnd, newEnd};
	}

	private int columns(int usable)
	{
		int columns = config.columns() > 0 ? config.columns() : (usable + VANILLA_GAP) / (CELL_WIDTH + VANILLA_GAP);
		return Math.max(1, Math.min(columns, (usable + MIN_GAP) / (CELL_WIDTH + MIN_GAP)));
	}

    private boolean groupedSearch()
    {
        if(!config.setupSearchLayout()) return false;
        if(searchView!=null && searchView.isActive()) return searchView.bySlot();
        if(bankTagsService!=null && bankTagsService.getActiveLayout()!=null) return false;
        return (bankTagsService==null || bankTagsService.getActiveBankTag()==null)
            && nativeSearch!=null && nativeSearch.groupBySlot();
    }

    private final java.util.List<SetupItemLayout.Heading> searchHeadings=new java.util.ArrayList<>();
    private final java.util.List<SetupItemLayout.InventoryNote> inventoryNotes=new java.util.ArrayList<>();
    java.util.List<SetupItemLayout.InventoryNote> inventoryNotes() { return groupedSearch()?viewGeometry.visibleNotes(inventoryNotes):java.util.Collections.emptyList(); }
    boolean inventoryPreview(Widget widget) { return inventoryWidgets.preview(widget); }
    @Subscribe(priority=20) public void onMenuEntryAdded(net.runelite.api.events.MenuEntryAdded event) { inventoryWidgets.menuAdded(event.getMenuEntry()); }
    @Subscribe(priority=20) public void onMenuOptionClicked(net.runelite.api.events.MenuOptionClicked event) { inventoryWidgets.clicked(event,client); }
    java.util.List<SetupItemLayout.Heading> searchHeadings() { return groupedSearch()?searchHeadings.stream()
        .filter(h -> !h.emptySlot || !viewGeometry.occupied(h.x,h.y)).collect(java.util.stream.Collectors.toList()):java.util.Collections.emptyList(); }
    private int[] layoutSearch(Widget items)
    {
        int usable=items.getWidth()-LEFT_INSET-RIGHT_INSET;
        int count=Math.max(3,Math.min(8,(usable+VANILLA_GAP)/(CELL_WIDTH+VANILLA_GAP)));
        int pitch=CELL_WIDTH+VANILLA_GAP;
        boolean view=searchView!=null && searchView.isActive();
        return SetupItemLayout.apply(items,itemManager,count,pitch,4,view?searchView.loadout():nativeSearch.loadout(),
            view?searchView.ranks():nativeSearch.ranks(),searchHeadings,inventoryWidgets,inventoryNotes);
    }

    private final java.util.Set<Widget> hiddenSeparators=java.util.Collections.newSetFromMap(new java.util.IdentityHashMap<>());

    private void hideSeparators(Widget items)
    {
        Widget[] children=items.getDynamicChildren();
        if(children==null) return;
        for(Widget child:children) {
            if(child==null || child.isSelfHidden() || child.getItemId()>=0) continue;
            int type=child.getType();
            boolean heading=type==WidgetType.TEXT && child.getText()!=null
                && net.runelite.client.util.Text.removeTags(child.getText()).matches("Tab (?:[1-9]|[IVX]+)");
            boolean line=(type==WidgetType.LINE || type==WidgetType.RECTANGLE)
                && child.getOriginalWidth()>=SEPARATOR_MIN_WIDTH && child.getOriginalHeight()<=2;
            boolean spriteLine=type==WidgetType.GRAPHIC && child.getSpriteId()==BANK_TAB_SEPARATOR_SPRITE
                && child.getOriginalWidth()>0 && child.getOriginalHeight()==2;
            if(heading || line || spriteLine) { hiddenSeparators.add(child);child.setHidden(true); }
        }
    }

    private void restoreSeparators()
    {
        for(Widget separator:hiddenSeparators) separator.setHidden(false);
        hiddenSeparators.clear();
    }

	private void restore()
	{
        viewGeometry.clear(); searchHeadings.clear(); inventoryNotes.clear();
        inventoryWidgets.clear();
        restoreSeparators();
		restoreTabs();
        controls.clear();
		Widget modal = modal();
		restore(positions, true, true);
		restore(sizes, false, true);
		positions.clear();
		sizes.clear();
		appliedSignature = null;

		Widget universe = client.getWidget(InterfaceID.Bankmain.UNIVERSE);
		Widget items = client.getWidget(InterfaceID.Bankmain.ITEMS);
		if (modal == null || universe == null || items == null)
		{
			return;
		}

		modal.revalidateScroll();
		revalidateTree(universe);
		Widget[] children = items.getDynamicChildren();
		if (children == null)
		{
			return;
		}

		int usable = items.getWidth() - LEFT_INSET - RIGHT_INSET;
		for (Widget child : children)
		{
			if (child != null && child.getType()!=WidgetType.RECTANGLE && child.getOriginalWidth() >= SEPARATOR_MIN_WIDTH)
			{
				child.setOriginalWidth(usable);
				child.revalidate();
			}
		}
	}

	private void restore(Map<Integer, Track> tracks, boolean position, boolean bank)
	{
		for (Map.Entry<Integer, Track> entry : tracks.entrySet())
		{
			if (!bank && WidgetUtil.componentToInterface(entry.getKey()) == InterfaceID.BANKMAIN)
			{
				continue;
			}

			Widget widget = client.getWidget(entry.getKey());
			if (widget == null || entry.getValue().applied == null)
			{
				continue;
			}

			if (position)
			{
				int[] p = basePos(widget);
				widget.setPos(p[0], p[1], p[2], p[3]);
			}
			else
			{
				int[] s = baseSize(widget);
				widget.setSize(s[0], s[1], s[2], s[3]);
			}

			if (!bank)
			{
				widget.revalidateScroll();
			}
		}
	}

	private void revalidateTree(Widget widget)
	{
		widget.revalidate();
		for (Widget child : widget.getStaticChildren())
		{
			revalidateTree(child);
		}

		Widget[] children = widget.getDynamicChildren();
		if (children != null)
		{
			for (Widget child : children)
			{
				if (child != null)
				{
					child.revalidate();
				}
			}
		}
	}

	private int[] basePos(Widget widget)
	{
		return base(positions, widget.getId(), new int[]{
			widget.getOriginalX(), widget.getOriginalY(), widget.getXPositionMode(), widget.getYPositionMode()
		});
	}

	private int[] baseSize(Widget widget)
	{
		return base(sizes, widget.getId(), new int[]{
			widget.getOriginalWidth(), widget.getOriginalHeight(), widget.getWidthMode(), widget.getHeightMode()
		});
	}

	/**
	 * The geometry the game gave a widget. Scripts reposition some widgets on every bank build, sometimes
	 * only on one axis, so any field that no longer holds what we last wrote is taken as the game's again.
	 */
	private static int[] base(Map<Integer, Track> tracks, int id, int[] current)
	{
		Track track = tracks.get(id);
		if (track == null)
		{
			track = new Track(current);
			tracks.put(id, track);
		}
		else
		{
			for (int i = 0; i < current.length; i++)
			{
				if (track.applied == null || current[i] != track.applied[i])
				{
					track.base[i] = current[i];
				}
			}
		}
		return track.base.clone();
	}

	void setPos(Widget widget, int x, int y, int xMode, int yMode)
	{
		basePos(widget);
		widget.setPos(x, y, xMode, yMode);
		positions.get(widget.getId()).applied = new int[]{x, y, xMode, yMode};
	}

	void setSize(Widget widget, int width, int height, int widthMode, int heightMode)
	{
		baseSize(widget);
		widget.setSize(width, height, widthMode, heightMode);
		sizes.get(widget.getId()).applied = new int[]{width, height, widthMode, heightMode};
	}

    private final Map<Widget,int[]> tabPositions=new java.util.IdentityHashMap<>();
    private void restoreTabs()
    {
        for(Map.Entry<Widget,int[]> e:tabPositions.entrySet())
        {
            Widget tab=e.getKey(); int[] track=e.getValue();
            if(tab.getOriginalX()==track[1]) { tab.setOriginalX(track[0]); tab.revalidate(); }
        }
        tabPositions.clear();
    }
    private void alignTabs()
    {
        Widget tabs=client.getWidget(InterfaceID.Bankmain.TABS);
        if(tabs==null || tabs.isHidden()) { tabPositions.clear(); return; }
        List<Widget> children=new ArrayList<>();
        if(tabs.getDynamicChildren()!=null) { children.addAll(Arrays.asList(tabs.getDynamicChildren())); }
        if(tabs.getStaticChildren()!=null) { children.addAll(Arrays.asList(tabs.getStaticChildren())); }
        children.removeIf(w -> w==null || w.isSelfHidden() || w.getWidth()>80 || w.getHeight()>60 || w.getWidth()<=0);
        tabPositions.keySet().retainAll(children);
        if(children.isEmpty()) { return; }
        int left=Integer.MAX_VALUE,right=0;
        for(Widget tab:children)
        {
            int[] track=tabPositions.computeIfAbsent(tab,w -> new int[]{w.getOriginalX(),w.getOriginalX()});
            if(tab.getOriginalX()!=track[1]) { track[0]=tab.getOriginalX(); }
            left=Math.min(left,track[0]); right=Math.max(right,track[0]+tab.getWidth());
        }
        int offset=LEFT_INSET+tabOffset(Math.max(0,tabs.getWidth()-LEFT_INSET-RIGHT_INSET),right-left,config.tabAlignment())-left;
        for(Widget tab:children)
        {
            int[] track=tabPositions.get(tab); int x=track[0]+offset;
            if(tab.getOriginalX()!=x) { tab.setOriginalX(x); tab.revalidate(); }
            track[1]=x;
        }
    }
    static int tabOffset(int available,int span,WindowMarkersConfig.TabAlignment alignment)
    {
        int spare=Math.max(0,available-span);
        return alignment==WindowMarkersConfig.TabAlignment.RIGHT ? spare : alignment==WindowMarkersConfig.TabAlignment.CENTER ? spare/2 : 0;
    }
}

package com.windowmarkers;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import java.nio.charset.StandardCharsets;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.UUID;
import javax.inject.Inject;
import net.runelite.client.config.ConfigManager;

/** Display coordinates in our own account/profile storage, never Bank Tags settings. */
final class BankPresetPositions
{
    @Inject ConfigManager configs;
    @Inject Gson gson;

    static final class Layout
    {
        Map<String, int[]> cells = new LinkedHashMap<>();
    }

    String key(String view, int width)
    {
        if (configs == null || configs.getProfile() == null || view == null) return null;
        return "presetPositions_" + configs.getProfile().getId() + "_"
            + UUID.nameUUIDFromBytes((view + "/" + width).getBytes(StandardCharsets.UTF_8));
    }

    Layout read(String account, String key)
    {
        Layout result = null;
        if (account != null && key != null)
        {
            String raw = configs.getConfiguration("windowmarkers", account, key);
            try { result = raw == null ? null : gson.fromJson(raw, Layout.class); }
            catch (JsonParseException ignored) { /* Fall back to the generated setup. */ }
        }
        if (result == null) result = new Layout();
        if (result.cells == null || result.cells.size() > 4000) result.cells = new LinkedHashMap<>();
        result.cells.entrySet().removeIf(e -> e.getKey() == null || e.getValue() == null
            || e.getValue().length != 2 || e.getValue()[0] < 0 || e.getValue()[0] > 4000
            || e.getValue()[1] < 0 || e.getValue()[1] > 50000);
        return result;
    }

    void save(String account, String key, Layout layout)
    {
        if (account != null && key != null && configs.getProfile() != null
            && key.startsWith("presetPositions_" + configs.getProfile().getId() + "_")
            && account.equals(configs.getRSProfileKey()))
            configs.setConfiguration("windowmarkers", account, key, gson.toJson(layout));
    }
}

package com.windowmarkers;

import java.awt.Rectangle;
import java.util.Arrays;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.widgets.JavaScriptCallback;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetType;
import net.runelite.api.gameval.InterfaceID;

/** Owns only its added screenshot widget; never moves or alters the native close control. */
final class BankScreenshotButton
{
    @Inject Client client;
    private Widget button, parent;

    void update(boolean enabled,Runnable capture)
    {
        Widget frame=client.getWidget(InterfaceID.Bankmain.FRAME);
        Widget close=findClose(frame);
        if(!enabled || frame==null || frame.isHidden() || close==null)
        { if(button!=null) { button.setHidden(true); } return; }
        Widget[] children=frame.getChildren();
        if(parent!=frame || button==null || children==null || !Arrays.asList(children).contains(button))
        {
            clear(); parent=frame;
            button=frame.createChild(-1,WidgetType.GRAPHIC);
            button.setOriginalWidth(20); button.setOriginalHeight(20);
            button.setSpriteId(573);
            button.setAction(0,"Save bank screenshot");
            button.setOnOpListener((JavaScriptCallback)e -> capture.run());
            button.setHasListener(true);
        }
        Rectangle position=position(frame.getBounds(),close.getBounds());
        if(position==null) { button.setHidden(true); return; }
        button.setOriginalX(position.x); button.setOriginalY(position.y);
        button.setHidden(false); button.revalidate();
    }

    static Rectangle position(Rectangle frame,Rectangle close)
    {
        Rectangle result=new Rectangle(close.x-frame.x-24,close.y-frame.y+(close.height-20)/2,20,20);
        return new Rectangle(0,0,frame.width,frame.height).contains(result) ? result : null;
    }

    private static Widget findClose(Widget frame)
    {
        if(frame==null || frame.getChildren()==null) { return null; }
        for(Widget child:frame.getChildren())
        {
            if(child==null || child.isHidden() || child.getActions()==null) { continue; }
            for(String action:child.getActions())
            { if("Close".equalsIgnoreCase(action)) { return child; } }
        }
        return null;
    }

    void clear()
    {
        if(button!=null)
        {
            button.setHidden(true); button.clearActions();
            button.setOnOpListener((Object[])null); button.setHasListener(false);
        }
        button=null; parent=null;
    }
}

package com.windowmarkers;

import java.util.*;

/** Immutable bank-only search documents, built off the client thread. */
final class BankSearchIndex
{
    private final Map<String,Set<Integer>> documents=new LinkedHashMap<>();
    private final Map<String,Set<Integer>> customDocuments=new LinkedHashMap<>();
    private final ItemCatalogueIndex catalogue;
    private final int hitpoints;
    private final BankCleanup cleanup;
    private final Map<String,Map<Integer,ItemCatalogueIndex.Rank>> markerRanks=new HashMap<>();
    private List<String> lastKeys=Collections.emptyList();
    private List<int[]> lastMembers=Collections.emptyList();
    private Map<Integer,ItemCatalogueIndex.Rank> lastRanks=Collections.emptyMap();
    private final Set<String> activities=new HashSet<>(),ordinaryNames=new HashSet<>();
    BankSearchIndex(List<AutoCategories.Item> owned,List<Marker> markers,CustomPresets presets)
    { this(owned,markers,presets,99); }
    BankSearchIndex(List<AutoCategories.Item> owned,List<Marker> markers,CustomPresets presets,int hitpoints)
    { this(owned,markers,presets,hitpoints,Collections.emptySet(),BankCleanup.Progress.unknown()); }
    BankSearchIndex(List<AutoCategories.Item> owned,List<Marker> markers,CustomPresets presets,int hitpoints,Set<Integer> tradeable,BankCleanup.Progress progress)
    {
        this.hitpoints=Math.max(1,Math.min(99,hitpoints));
        cleanup=new BankCleanup(owned,tradeable,progress);
        List<ItemCatalogueIndex.Item> facts=new ArrayList<>();
        for(AutoCategories.Item item:owned) facts.add(new ItemCatalogueIndex.Item(item,item.name,
            item.slot==-2?ItemCatalogueIndex.fallbackSlot(item.id,item.name):item.slot));
        catalogue=new ItemCatalogueIndex(facts,false);
        Set<Integer> ids=new HashSet<>();
        for(AutoCategories.Item item:owned) {
            ids.add(item.id); add(item.name,item.id); ordinaryNames.add(SearchText.normalize(item.name));
            if(!ItemVariantState.identityNeedsReview(item)) for(WikiCatalogue.Entry entry:WikiCatalogue.entries(item))
                add(ItemVariantState.annotate(entry.group,item),item.id);
        }
        for(AutoCategories.Preset preset:AutoCategories.Preset.values()) {
            if(SetupItemLayout.activityPreset(preset)) activity(preset.toString());
            for(int id:catalogue.presetIds(preset)) add(preset.toString(),id);
        }
        catalogue.categoryDocuments().forEach((name,items)-> { for(int id:items) add(name,id); });
        for(ActivitySetups.Setup setup:ActivitySetups.all()) {
            activity(setup.activity); activity(setup.activity+" — "+setup.label);
            for(int id:setup.itemIds) if(ids.contains(id)) add(setup.activity+" — "+setup.label,id);
        }
        for(Marker marker:markers) if(marker.linked()) for(int id:marker.linkedItemIds)
            if(ids.contains(id)) addCustom(marker.labelText(),id);
        for(CustomPresets.Preset preset:presets.presets) for(Marker marker:preset.groups)
            if(marker.linked()) for(int id:marker.linkedItemIds) if(ids.contains(id)) { addCustom(preset.name,id); addCustom(marker.labelText(),id); }
        for(CustomPresets.Preset preset:presets.presets) if(preset.groupBySlot) activity(preset.name);
        ordinaryNames.addAll(Arrays.asList("food","potions","weapons","armour","armor","equipment","resources","tools","capes","head","farming","fishing","mining","woodcutting"));
        for(net.runelite.api.Skill skill:net.runelite.api.Skill.values()) ordinaryNames.add(SearchText.normalize(skill.getName()));
        for(Marker marker:markers) indexRank(marker);
        for(CustomPresets.Preset preset:presets.presets) for(Marker marker:preset.groups) indexRank(marker);
    }
    private void addCustom(String text,int id) {
        add(text,id); customDocuments.computeIfAbsent(SearchText.normalize(text),k->new HashSet<>()).add(id);
    }
    private void indexRank(Marker marker) {
        if(marker.guideQuery!=null && !marker.guideQuery.isEmpty()) markerRanks.computeIfAbsent(marker.rankKey(),
            key->BankCleanup.isQuery(marker.guideQuery)?cleanup.search(marker.guideQuery).ranks:catalogue.guideRanks(marker.guideQuery,marker.guideContext==null?"":marker.guideContext,hitpoints));
    }
    Map<Integer,ItemCatalogueIndex.Rank> ranks(List<Marker> groups) {
        boolean same=groups.size()==lastKeys.size();
        for(int i=0;same && i<groups.size();i++) same=groups.get(i).rankKey().equals(lastKeys.get(i)) && groups.get(i).linkedItemIds==lastMembers.get(i);
        if(same) return lastRanks;
        Map<Integer,ItemCatalogueIndex.Rank> result=new HashMap<>();
        for(Marker marker:groups) if(marker.linked()) {
            // Cleanup maps are already built from this snapshot; new preview groups need their reasons too.
            if(BankCleanup.isQuery(marker.guideQuery)) indexRank(marker);
            Map<Integer,ItemCatalogueIndex.Rank> ranks=markerRanks.getOrDefault(marker.rankKey(),Collections.emptyMap());
            for(int id:marker.linkedItemIds) if(ranks.containsKey(id)) result.merge(id,ranks.get(id),TierPresentation::merge);
        }
        lastKeys=new ArrayList<>();lastMembers=new ArrayList<>();
        for(Marker group:groups) { lastKeys.add(group.rankKey());lastMembers.add(group.linkedItemIds); }
        lastRanks=Collections.unmodifiableMap(result);
        return lastRanks;
    }
    static final class Match {
        final Set<Integer> ids; final Map<Integer,ItemCatalogueIndex.Rank> ranks; final boolean slots;
        final SetupLoadout loadout;
        Match(Set<Integer> ids,Map<Integer,ItemCatalogueIndex.Rank> ranks,boolean slots) { this(ids,ranks,slots,null); }
        Match(Set<Integer> ids,Map<Integer,ItemCatalogueIndex.Rank> ranks,boolean slots,SetupLoadout loadout) { this.ids=ids;this.ranks=ranks;this.slots=slots;this.loadout=loadout; }
    }
    private void activity(String name) {
        activities.add(SearchText.normalize(name));
        String alias=BankCatalogue.aliases(name); if(!alias.isEmpty()) activities.add(alias);
    }
    boolean groupBySlot(String query) {
        String normalized=SearchText.normalize(query);
        if(normalized.length()<3 || ordinaryNames.contains(normalized) || !plainQuery(query)) return false;
        // A general category or individual item must not inherit layout merely
        // because it also occurs in a boss setup's long document.
        return activities.stream().anyMatch(name -> name.equals(normalized) || name.startsWith(normalized+" "));
    }
    private void add(String text,int id)
    {
        String key=SearchText.normalize(text+" "+BankCatalogue.aliases(text));
        if(!key.isEmpty()) documents.computeIfAbsent(key,k -> new HashSet<>()).add(id);
    }
    static boolean plainQuery(String query)
    { return query!=null && !query.trim().isEmpty() && !query.matches(".*[:<>=!|&].*"); }
    Set<Integer> find(String query)
    { return search(query,"").ids; }
    Match search(String query,String context)
    { return search(query,context,""); }
    Match search(String query,String context,String inventoryContext)
    { return search(query,context,inventoryContext,hitpoints); }
    Match search(String query,String context,String inventoryContext,int hitpoints)
    {
        Set<Integer> result=new HashSet<>();
        if(!plainQuery(query)) return new Match(result,Collections.emptyMap(),false);
        Match review=cleanup.search(query);if(review!=null) return review;
        String normalized=SearchText.normalize(query);
        ItemCatalogueIndex.Result common=catalogue.find(query,context,inventoryContext,hitpoints);
        if(common!=null) for(ItemCatalogueIndex.Item item:common.items) result.add(item.id);
        // Purpose/threshold queries have exact membership. Saved groups with a
        // matching name must not reintroduce raw food or incompatible ammo.
        if(common!=null && SupplySearch.parse(query)!=null) return new Match(result,common.ranks,false);
        Map<String,Set<Integer>> extra=common==null?documents:customDocuments;
        boolean exact=extra.keySet().stream().anyMatch(t->t.contains(normalized));
        for(Map.Entry<String,Set<Integer>> entry:extra.entrySet())
            if(entry.getKey().contains(normalized) || (!exact && normalized.length()>=3 && SearchText.normalizedScore(entry.getKey(),normalized)!=Integer.MAX_VALUE))
                result.addAll(entry.getValue());
        SearchQuery qualifiers=SearchQuery.parse(query);
        if(common!=null && !qualifiers.tiers.isEmpty()) result.removeIf(id->!qualifiers.accepts(common.ranks.get(id)));
        return new Match(result,common==null?Collections.emptyMap():common.ranks,common!=null && common.activity || groupBySlot(query),common==null?null:common.loadout);
    }
}

package com.windowmarkers;

import java.util.*;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.banktags.BankTag;
import net.runelite.client.plugins.banktags.BankTagsService;
import net.runelite.client.plugins.banktags.TagManager;

/** Session-only custom tag; does not create saved tag tabs or layouts. */
@Singleton
final class BankSearchView
{
    @Inject net.runelite.api.Client client;
    @Inject BankTagsService bankTags;
    @Inject TagManager tags;
    @Inject ItemManager items;
    @Inject net.runelite.client.callback.ClientThread clientThread;
    private final String tagName="improved banking "+UUID.randomUUID();
    private BankTag tag;
    private String name;
    private String layoutIdentity;
    String layoutIdentity() { return isActive() ? layoutIdentity : null; }
    private boolean slots;
    private boolean reopen, reopenQueued;
    private SetupLoadout loadout;
    private Marker highlight;
    Marker highlight() { return isActive()?highlight:null; }
    private Map<Integer,ItemCatalogueIndex.Rank> ranks=Collections.emptyMap();
    SetupLoadout loadout() { return isActive()?loadout:null; }
    Map<Integer,ItemCatalogueIndex.Rank> ranks() { return isActive()?ranks:Collections.emptyMap(); }
    private List<Marker> groups=Collections.emptyList();

    void show(String name,List<Marker> groups,boolean slots) { show(name,groups,slots,null,Collections.emptyMap()); }
    void show(String name,List<Marker> groups,boolean slots,SetupLoadout loadout,Map<Integer,ItemCatalogueIndex.Rank> ranks)
    { show(name,groups,slots,loadout,ranks,"saved:"+name); }
    void show(String name,List<Marker> groups,boolean slots,SetupLoadout loadout,Map<Integer,ItemCatalogueIndex.Rank> ranks,String layoutIdentity)
    {
        clear();
        this.loadout=loadout; this.ranks=ranks;
        this.name=name; this.groups=new ArrayList<>(groups); this.slots=slots;
        this.layoutIdentity=layoutIdentity;
        Set<Integer> ids=new HashSet<>();
        for(Marker group:groups) if(group.linked()) for(int id:group.linkedItemIds) ids.add(id);
        if(ids.isEmpty() && (loadout==null || !loadout.hasBudgetExamples())) { this.groups=Collections.emptyList(); return; }
        if(loadout!=null && !ids.isEmpty()) {
            highlight=new Marker(0,0,48,36);highlight.scrollWithItems=true;
            highlight.linkedItemIds=ids.stream().mapToInt(Integer::intValue).toArray();
        }
        // The palette saves exact IDs. Canonicalize both sides so a selected
        // worn/ornament variant is not silently lost; do not expand charge families.
        Set<Integer> canonical=new HashSet<>();for(int id:ids) canonical.add(items.canonicalize(id));
        tag=id -> ids.contains(id) || canonical.contains(items.canonicalize(id));
        tags.registerTag(tagName,tag);
        bankTags.openBankTag(tagName,BankTagsService.OPTION_NO_LAYOUT|BankTagsService.OPTION_HIDE_TAG_NAME);
    }
    boolean isActive() { return tag!=null && tagName.equals(bankTags.getActiveTag()); }
    void filter(net.runelite.api.events.ScriptCallbackEvent event)
    {
        if(!"bankSearchFilter".equals(event.getEventName()) || !isActive()
            || client.getWidget(net.runelite.api.gameval.InterfaceID.Bankmain.ITEMS)==null
            || client.getVarcIntValue(net.runelite.api.gameval.VarClientID.MESLAYERMODE)==net.runelite.api.vars.InputType.SEARCH.getType()) return;
        int size=client.getIntStackSize();
        if(size<2) return;
        int[] stack=client.getIntStack();
        if(stack[size-1]<0) return;
        // A temporary view is an exact selection, even if an earlier search
        // subscriber accepted a different item. Normal tabs/search keep their filters.
        stack[size-2]=tag.contains(stack[size-1])?1:0;
    }
    boolean bySlot() { return slots; }
    String name() { return name; }
    List<Marker> groups() { return isActive()?new ArrayList<>(groups):Collections.emptyList(); }
    /** Capture on the client thread before starting a background view calculation. */
    java.util.function.BooleanSupplier unchangedContext()
    {
        var bank=client.getWidget(net.runelite.api.gameval.InterfaceID.Bankmain.UNIVERSE);
        if(client.getGameState()!=net.runelite.api.GameState.LOGGED_IN || bank==null || bank.isHidden()) return () -> false;
        String activeName=bankTags.getActiveTag();BankTag activeTag=bankTags.getActiveBankTag();
        int nativeTab=client.getVarbitValue(net.runelite.api.gameval.VarbitID.BANK_CURRENTTAB);
        int inputMode=client.getVarcIntValue(net.runelite.api.gameval.VarClientID.MESLAYERMODE);
        String input=client.getVarcStrValue(net.runelite.api.gameval.VarClientID.MESLAYERINPUT);
        return () -> client.getGameState()==net.runelite.api.GameState.LOGGED_IN && bank!=null && !bank.isHidden()
            && client.getWidget(net.runelite.api.gameval.InterfaceID.Bankmain.UNIVERSE)==bank
            && nativeTab==client.getVarbitValue(net.runelite.api.gameval.VarbitID.BANK_CURRENTTAB)
            && Objects.equals(activeName,bankTags.getActiveTag()) && activeTag==bankTags.getActiveBankTag()
            && inputMode==client.getVarcIntValue(net.runelite.api.gameval.VarClientID.MESLAYERMODE)
            && Objects.equals(input,client.getVarcStrValue(net.runelite.api.gameval.VarClientID.MESLAYERINPUT));
    }
    // Bank Tags clears its active tag on unload but remembers its name. Keep the
    // registered contents until the bank reopens or the user explicitly changes views.
    void bankClosed() {
        if(isActive()) reopen=true;
        else if(!reopen) forget();
    }
    private boolean bankOpen() {
        var bank=client.getWidget(net.runelite.api.gameval.InterfaceID.Bankmain.UNIVERSE);
        return bank!=null && !bank.isHidden();
    }
    private boolean canReopen() {
        String active=bankTags.getActiveTag();
        return (active==null || tagName.equals(active))
            && client.getVarbitValue(net.runelite.api.gameval.VarbitID.BANK_CURRENTTAB)==0
            && client.getVarcIntValue(net.runelite.api.gameval.VarClientID.MESLAYERMODE)!=net.runelite.api.vars.InputType.SEARCH.getType();
    }
    void update() {
        if(tag==null || !bankOpen()) return;
        if(reopen) {
            if(!canReopen()) { forget(); return; }
            if(!reopenQueued) {
                reopenQueued=true;
                BankTag expected=tag;
                var unchanged=unchangedContext();
                // Opening a tag rebuilds the bank: defer it out of BeforeRender.
                clientThread.invokeLater(() -> {
                    if(tag!=expected) return;
                    reopenQueued=false;
                    if(!bankOpen()) return;
                    if(!unchanged.getAsBoolean() || !canReopen()) { forget(); return; }
                    reopen=false;
                    bankTags.openBankTag(tagName,BankTagsService.OPTION_NO_LAYOUT|BankTagsService.OPTION_HIDE_TAG_NAME);
                });
            }
            return;
        }
        if(tag!=null && !isActive()) forget();
        if(isActive()) {
            var title=client.getWidget(net.runelite.api.gameval.InterfaceID.Bankmain.TITLE);
            if(title!=null) title.setText("Bank view: "+name.replace('<',' ').replace('>',' ').substring(0,Math.min(48,name.length()))+(loadout!=null && loadout.notEnoughGear()?" - not enough gear in bank":""));
        }
    }
    void clear() {
        if(isActive() || tag!=null && reopen && bankTags.getActiveTag()==null) {
            bankTags.closeBankTag();
        }
        forget();
    }
    private void forget() { if(tag!=null) tags.unregisterTag(tagName); tag=null; name=null; slots=false;reopen=false;reopenQueued=false;loadout=null;highlight=null;ranks=Collections.emptyMap(); groups=Collections.emptyList(); }
}

package com.windowmarkers;

import java.util.ArrayList;
import java.util.List;
import java.util.Comparator;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.widgets.JavaScriptCallback;
import net.runelite.api.widgets.Widget;

/** Visible cells owned by one temporary view, retained only until the next native rebuild. */
final class BankViewGeometry
{
    private Widget parent;
    private final List<Position> positions = new ArrayList<>();
    private BankPresetPositions.Layout layout;
    private Runnable save;
    private List<SetupItemLayout.InventoryNote> notes;
    private int height;
    private long dragRevision;
    void cancelDrag() { dragRevision++; }

    void clear() { cancelDrag(); parent = null; positions.clear(); layout = null; save = null; notes = null; height = 0; }

    void capture(Widget container)
    {
        clear(); parent = container;
        Widget[] children = container.getDynamicChildren();
        if (children == null) return;
        for (Widget child : children)
            if (child != null && !child.isSelfHidden() && child.getItemId() >= 0)
                positions.add(new Position(child));
    }

    int capture(Widget container, BankPresetPositions.Layout layout, Runnable save,
        List<SetupItemLayout.InventoryNote> notes, int height)
    {
        capture(container);
        this.layout = layout; this.save = save; this.notes = notes; this.height = height;
        // A repeated supply has a distinct position. Native bank indexes can change,
        // so identify occurrences in the generated setup, not by bank stack index.
        positions.sort(Comparator.comparingInt((Position p) -> p.y).thenComparingInt(p -> p.x));
        Map<Integer, Integer> occurrences = new HashMap<>();
        for (Position p : positions)
        {
            p.key = p.itemId + ":" + occurrences.merge(p.itemId, 1, Integer::sum);
            for (int i = 0; i < notes.size(); i++)
                if (notes.get(i).x == p.x && notes.get(i).y == p.y) { p.note = i; break; }
        }
        for (Position p : positions)
        {
            int[] saved = layout.cells.get(p.key);
            if (saved != null && saved[0] + 36 <= container.getWidth()) move(p, saved[0], saved[1]);
        }
        // Newly added items must remain visible even if their generated cell is
        // already occupied by a saved move. Keep the saved placement authoritative.
        List<Position> occupied = new ArrayList<>();
        List<Position> ordered = new ArrayList<>(positions);
        ordered.sort(Comparator.comparing(p -> !layout.cells.containsKey(p.key)));
        for (Position p : ordered)
        {
            while (overlaps(p, occupied)) move(p, 51, contentHeight() + 4);
            occupied.add(p);
        }
        restore(container);
        return contentHeight();
    }

    private boolean overlaps(Position p, List<Position> others)
    {
        for (Position q : others) if (p.x < q.x + 36 && p.x + 36 > q.x && p.y < q.y + 32 && p.y + 32 > q.y) return true;
        return false;
    }

    /** Only called for an actual user drag in the currently owned view. */
    boolean drag(Client client, Widget container, java.util.function.BooleanSupplier current)
    {
        Widget dragged = client.getDraggedWidget();
        Position source = find(dragged);
        if (container != parent || source == null || !valid(source, container)) return false;
        // Stop native bank-order mutations and replace the tag-layout callback,
        // which otherwise directly repacks the preset without a bank build event.
        client.setDraggedOnWidget(null);
        long revision = dragRevision;
        dragged.setOnDragCompleteListener((JavaScriptCallback) event -> {
            if (revision != dragRevision || !current.getAsBoolean() || container != parent || find(dragged) != source
                || !valid(source, container)) return;
            drop(source, client.getMouseCanvasPosition());
        });
        return true;
    }

    private void drop(Position source, Point mouse)
    {
        Point origin = parent.getCanvasLocation();
        if (origin == null || mouse == null) return;
        int x = mouse.getX() - origin.getX(), visibleY = mouse.getY() - origin.getY();
        if (x < 0 || x >= parent.getWidth() || visibleY < 0 || visibleY >= parent.getHeight()) return;
        int y = visibleY + parent.getScrollY();
        Position target = null;
        for (Position p : positions)
            if (p != source && valid(p, parent) && x >= p.x && x < p.x + 36 && y >= p.y && y < p.y + 32)
            { target = p; break; }
        int nextX, nextY;
        if (target != null)
        {
            nextX = target.x; nextY = target.y;
            move(target, source.x, source.y); remember(target);
        }
        else
        {
            nextX = Math.max(0, Math.min(parent.getWidth() - 36, 51 + Math.round((x - 69) / 48f) * 48));
            nextY = Math.max(0, Math.min(50000, source.y + Math.round((y - source.y - 16) / 36f) * 36));
            // Do not overlap another cell when dropping in the gap beside it.
            for (Position p : positions) if (p != source && nextX < p.x + 36 && nextX + 36 > p.x
                && nextY < p.y + 32 && nextY + 32 > p.y) return;
        }
        move(source, nextX, nextY); remember(source);
        restore(parent);
        parent.setScrollHeight(Math.max(parent.getHeight(), contentHeight() + 8));
        parent.revalidateScroll();
        if (save != null) save.run();
    }

    private void remember(Position p)
    {
        if (layout != null && p.key != null && (layout.cells.containsKey(p.key) || layout.cells.size() < 4000))
            layout.cells.put(p.key, new int[]{p.x, p.y});
    }

    private void move(Position p, int x, int y)
    {
        p.x = x; p.y = y;
        if (notes != null && p.note >= 0)
            notes.set(p.note, new SetupItemLayout.InventoryNote(notes.get(p.note).text, x, y));
    }

    private int contentHeight()
    {
        int result = height;
        for (Position p : positions) result = Math.max(result, p.y + 36);
        return result;
    }

    private Position find(Widget widget)
    {
        for (Position p : positions) if (p.widget == widget) return p;
        return null;
    }

    boolean occupied(int x, int y)
    {
        for (Position p : positions) if (p.x == x && p.y == y) return true;
        return false;
    }

    List<SetupItemLayout.InventoryNote> visibleNotes(List<SetupItemLayout.InventoryNote> original)
    {
        if (notes != original) return original;
        List<SetupItemLayout.InventoryNote> result = new ArrayList<>();
        for (int i = 0; i < notes.size(); i++)
        {
            SetupItemLayout.InventoryNote note = notes.get(i);
            boolean covered = false;
            for (Position p : positions) if (p.x == note.x && p.y == note.y && p.note != i) { covered = true; break; }
            if (!covered) result.add(note);
        }
        return result;
    }

    private boolean valid(Position p, Widget container)
    {
        if (container == null) return false;
        Widget[] children = container.getDynamicChildren();
        int index = p.widget.getIndex();
        return children != null && index >= 0 && index < children.length && children[index] == p.widget
            && p.widget.getItemId() == p.itemId;
    }

    void restore(Widget container)
    {
        if (parent != container || container == null) return;
        Widget[] children = container.getDynamicChildren();
        if (children == null) return;
        for (Position p : positions)
        {
            int index = p.widget.getIndex();
            if (index < 0 || index >= children.length || children[index] != p.widget
                || p.widget.getItemId() != p.itemId) continue;
            // Another layout can deduplicate repeated supplies and phase gear.
            // Restore only cells that this view showed after native filtering,
            // never previously filtered items or widgets replaced since capture.
            if (p.widget.isSelfHidden() || p.widget.getOriginalX() != p.x || p.widget.getOriginalY() != p.y)
            {
                p.widget.setHidden(false);
                p.widget.setOriginalX(p.x); p.widget.setOriginalY(p.y); p.widget.revalidate();
            }
        }
    }

    private static final class Position
    {
        final Widget widget;
        final int itemId;
        int x, y, note = -1;
        String key;
        Position(Widget widget)
        {
            this.widget=widget; itemId=widget.getItemId(); x=widget.getOriginalX(); y=widget.getOriginalY();
        }
    }
}

package com.windowmarkers;

import java.awt.*;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.SpritePixels;
import net.runelite.client.game.SpriteManager;

final class BorderRenderer
{
    // Vanilla equipment-button frame: four corners, left/top/right/bottom edges.
    static final int[] IDS = {913, 914, 915, 916, 917, 918, 919, 920};
    @Inject Client client;
    @Inject SpriteManager sprites;
    private final SpritePixels[] previous = new SpritePixels[8];
    private final BufferedImage[] themed = new BufferedImage[8];
    private static final int MAX_TINTS = 2048;
    private static final long MAX_TINT_PIXELS = 2L * 1024 * 1024; // 8 MiB of ARGB pixels.
    private final java.util.Map<TintKey, BufferedImage> tinted = new java.util.LinkedHashMap<>(64, 0.75f, true);
    private long tintPixels;
    final JoinedItemBorders joined=new JoinedItemBorders();

    BufferedImage image(int index, boolean theme)
    {
        SpritePixels override = theme ? client.getSpriteOverrides().get(IDS[index]) : null;
        if (override == null) { return sprites.getSprite(IDS[index], 0); }
        if (previous[index] != override)
        {
            previous[index] = override;
            themed[index] = override.toBufferedImage();
        }
        return themed[index];
    }

    void clear()
    {
        java.util.Arrays.fill(previous, null);
        java.util.Arrays.fill(themed, null);
        tinted.clear(); tintPixels = 0; joined.clear();
    }

    void drawRegions(Graphics2D g,java.util.List<Rectangle> regions,WindowMarkersConfig.BorderStyle style,Color colour,boolean tint)
    {
        if(style==WindowMarkersConfig.BorderStyle.PLAIN) joined.draw(g,regions,colour);
        else for(Rectangle region:regions) if(region!=null) draw(g,region,style,colour,tint);
    }

    void draw(Graphics2D g, Rectangle r, WindowMarkersConfig.BorderStyle style, Color color, boolean tint)
    {
        if (style != WindowMarkersConfig.BorderStyle.PLAIN)
        {
            BufferedImage[] parts = new BufferedImage[8];
            for (int i=0; i<8; i++)
            {
                parts[i] = image(i, style == WindowMarkersConfig.BorderStyle.ACTIVE_THEME);
                if (parts[i] == null) { plain(g, r, color); return; }
                if (tint) { parts[i] = tint(parts[i], color); }
            }
            drawFrame(g, r, parts);
        }
        else { plain(g, r, color); }
    }

    BufferedImage tint(BufferedImage source, Color color)
    {
        TintKey key = new TintKey(source, color.getRGB());
        BufferedImage result = tinted.get(key);
        if (result != null) { return result; }
        result = new BufferedImage(source.getWidth(), source.getHeight(), BufferedImage.TYPE_INT_ARGB);
        for (int y=0;y<source.getHeight();y++) for (int x=0;x<source.getWidth();x++)
        {
            int pixel=source.getRGB(x,y);
            int light=Math.max((pixel >> 16)&255, Math.max((pixel >> 8)&255, pixel&255));
            int alpha=(pixel >>> 24)*color.getAlpha()/255;
            result.setRGB(x,y,(alpha<<24) | ((color.getRed()*light/255)<<16) | ((color.getGreen()*light/255)<<8) | (color.getBlue()*light/255));
        }
        long pixels = (long) result.getWidth() * result.getHeight();
        if (pixels <= MAX_TINT_PIXELS)
        {
            // Do not drop every colour at capacity: that makes the next render pass
            // recolour the same borders again. Evict only the least recently used.
            java.util.Iterator<BufferedImage> oldest = tinted.values().iterator();
            while (tinted.size() >= MAX_TINTS || tintPixels + pixels > MAX_TINT_PIXELS)
            {
                BufferedImage removed = oldest.next();
                tintPixels -= (long) removed.getWidth() * removed.getHeight();
                oldest.remove();
            }
            tinted.put(key, result); tintPixels += pixels;
        }
        return result;
    }

    private static final class TintKey
    {
        final BufferedImage source;
        final int colour;
        TintKey(BufferedImage source, int colour) { this.source = source; this.colour = colour; }
        @Override public int hashCode() { return 31 * System.identityHashCode(source) + colour; }
        @Override public boolean equals(Object other)
        { return other instanceof TintKey && source == ((TintKey) other).source && colour == ((TintKey) other).colour; }
    }

    static void plain(Graphics2D g, Rectangle r, Color color)
    {
        g.setColor(color);
        g.drawRect(r.x, r.y, r.width - 1, r.height - 1);
    }

    static void drawFrame(Graphics2D graphics, Rectangle r, BufferedImage[] p)
    {
        Graphics2D g = (Graphics2D) graphics.create();
        try
        {
            g.clip(r);
            int left = Math.min(r.width / 2, Math.max(p[0].getWidth(), p[2].getWidth()));
            int right = Math.min(r.width / 2, Math.max(p[1].getWidth(), p[3].getWidth()));
            int top = Math.min(r.height / 2, Math.max(p[0].getHeight(), p[1].getHeight()));
            int bottom = Math.min(r.height / 2, Math.max(p[2].getHeight(), p[3].getHeight()));
            tile(g, p[4], new Rectangle(r.x, r.y+top, Math.min(left,p[4].getWidth()), r.height-top-bottom));
            tile(g, p[5], new Rectangle(r.x+left, r.y, r.width-left-right, Math.min(top,p[5].getHeight())));
            tile(g, p[6], new Rectangle(r.x+r.width-Math.min(right,p[6].getWidth()), r.y+top, Math.min(right,p[6].getWidth()), r.height-top-bottom));
            tile(g, p[7], new Rectangle(r.x+left, r.y+r.height-Math.min(bottom,p[7].getHeight()), r.width-left-right, Math.min(bottom,p[7].getHeight())));
            g.drawImage(p[0], r.x, r.y, left, top, null);
            g.drawImage(p[1], r.x+r.width-right, r.y, right, top, null);
            g.drawImage(p[2], r.x, r.y+r.height-bottom, left, bottom, null);
            g.drawImage(p[3], r.x+r.width-right, r.y+r.height-bottom, right, bottom, null);
        }
        finally { g.dispose(); }
    }

    private static void tile(Graphics2D g, BufferedImage image, Rectangle bounds)
    {
        if (bounds.isEmpty()) { return; }
        g.setPaint(new TexturePaint(image, new Rectangle(bounds.x, bounds.y, image.getWidth(), image.getHeight())));
        g.fill(bounds);
    }
}

