/** Public GE search hook; changes result labels only, never offers or input. */
@Singleton
final class GeCatalogueSearch extends Overlay
{
    private static final org.slf4j.Logger log=org.slf4j.LoggerFactory.getLogger(GeCatalogueSearch.class);
    @Inject Client client;
    @Inject ClientThread thread;
    @Inject ItemManager itemManager;
    @Inject WindowMarkersConfig config;
    @Inject EventBus eventBus;
    @Inject OverlayManager overlays;
    @Inject TooltipManager tooltips;
    @Inject GePlayerItems playerItems;
    private volatile boolean active;
    private long generation;
    private boolean preparing;
    private ItemCatalogueIndex index;
    private String query="";
    private ItemCatalogueIndex.Result result;
    private Widget resultContainer;
    private final List<Decoration> decorations=new ArrayList<>();
    private String failure="";
    private boolean geSearchOpen;
    private boolean detailsDirty;
    private String notice="";
    private WindowMarkersConfig.ActivityItems activityMode=WindowMarkersConfig.ActivityItems.ALL;
    private Map<Integer,String> upgrades=Collections.emptyMap();
    private GeCategorySearch shopping;
    private List<String> suggestions=Collections.emptyList();
    private Widget tips,tipsParent;
    private Boolean ancientRings;

    GeCatalogueSearch() { setPosition(OverlayPosition.DYNAMIC); setLayer(OverlayLayer.ABOVE_WIDGETS); }
    void start()
    {
        active=true; eventBus.register(this); overlays.add(this);
        thread.invokeLater(() -> { if(active) { playerItems.clear();ancientRings=null;if(config.geCatalogueSearch()) playerItems.observeOpenBank();prepare(); } });
    }
    void stop()
    {
        active=false; eventBus.unregister(this); overlays.remove(this);
        thread.invokeLater(() -> { generation++; preparing=false; playerItems.clear();ancientRings=null;clear(); geSearchOpen=false; if(active) prepare(); });
    }
    @Subscribe public void onConfigChanged(ConfigChanged event)
    {
        if(!event.getGroup().equals("windowmarkers") || !event.getKey().startsWith("ge")) return;
        thread.invokeLater(() -> { clear(); failure="";if(!config.geCatalogueSearch()) playerItems.clear();prepare(); });
    }
    @Subscribe public void onProfileChanged(ProfileChanged event)
    { thread.invokeLater(() -> { playerItems.clear();ancientRings=null;clear(); prepare(); }); }
    @Subscribe public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
    { thread.invokeLater(() -> { playerItems.clear();ancientRings=null;clear(); }); }
    @Subscribe public void onItemContainerChanged(ItemContainerChanged event)
    {
        if(!active || !config.geCatalogueSearch()) return;
        if(event.getContainerId()==InventoryID.BANK) playerItems.bankChanged(event.getItemContainer());
        if(event.getContainerId()==InventoryID.BANK || event.getContainerId()==InventoryID.INV || event.getContainerId()==InventoryID.WORN) detailsDirty=true;
    }
    @Subscribe public void onGrandExchangeOfferChanged(GrandExchangeOfferChanged event)
    { if(active && config.geCatalogueSearch()) { playerItems.offersChanged();detailsDirty=true; } }
    @Subscribe public void onStatChanged(StatChanged event) { detailsDirty=true; }
    @Subscribe public void onVarbitChanged(VarbitChanged event) { ancientRings=null; }
    @Subscribe public void onGameTick(GameTick event)
    {
        if(!active || !config.geCatalogueSearch()) return;
        // Quest.getState uses QUEST_STATUS_GET internally. It must never be called
        // from the GE search/script callbacks while the native script is running.
        if(config.geCatalogueSearch() && config.geMarkLocked() && ancientRings==null && client.getGameState()==GameState.LOGGED_IN) {
            ancientRings=Quest.DESERT_TREASURE_II__THE_FALLEN_EMPIRE.getState(client)==QuestState.FINISHED;detailsDirty=true;
        }
        playerItems.observeOpenBank();
        if(detailsDirty && valid()) decorate();
        detailsDirty=false;
    }
    @Subscribe public void onGameStateChanged(GameStateChanged event)
    {
        if(event.getGameState()==GameState.LOGIN_SCREEN || event.getGameState()==GameState.HOPPING || event.getGameState()==GameState.CONNECTION_LOST) {
            if(playerItems!=null) playerItems.clear();
            ancientRings=null;
            generation++; preparing=false; index=null; failure=""; clear(); geSearchOpen=false;
        }
        if(event.getGameState()==GameState.LOGGED_IN) prepare();
    }

    private void prepare()
    {
        if(!active || !config.geCatalogueSearch() || client.getGameState()!=GameState.LOGGED_IN
            || index!=null || preparing || !failure.isEmpty()) return;
        preparing=true; final long request=++generation;
        // Resource parsing and immutable index construction stay off client.
        new SwingWorker<Void,Void>() {
            protected Void doInBackground() { ItemCatalogueIndex.fallbackSlot(-1,""); GeActivityFilter.prepare();GeRequirements.prepare();return null; }
            protected void done() {
                try { get(); thread.invokeLater(() -> collect(request)); }
                catch(Exception ex) { thread.invokeLater(() -> failed(request,ex)); }
            }
        }.execute();
    }
    private boolean current(long request) { return active && request==generation; }
    private void failed(long request,Exception ex)
    { if(current(request)) { preparing=false; failure="Catalogue unavailable; ordinary GE search remains active."; log.warn("Could not prepare Improved Banking GE catalogue",ex); } }
    private void collect(long request)
    {
        if(!current(request)) return;
        List<ItemCatalogueIndex.Item> catalogue=new ArrayList<>();
        final int[] cursor={0};
        thread.invokeLater(() -> {
            if(!current(request)) return true;
            if(!config.geCatalogueSearch()) { preparing=false; return true; }
            if(client.getGameState()!=GameState.LOGGED_IN) return false;
            // Cache definitions are not available before the login screen.
            int count=Math.min(65536,client.getItemCount());
            if(count<=0) return false;
            int end=Math.min(cursor[0]+256,count);
            try {
                while(cursor[0]<end) {
                    int id=cursor[0]++;
                    ItemComposition item=itemManager.getItemComposition(id);
                    if(item==null || !item.isGeTradeable() || item.getNote()!=-1 || item.getPlaceholderTemplateId()!=-1) continue;
                    String name=item.getName();
                    if(name==null || name.isBlank() || name.equalsIgnoreCase("null")) continue;
                    var stats=itemManager.getItemStats(id);
                    var eq=stats==null?null:stats.getEquipment();
                    int slot=eq!=null ? eq.getSlot() : ItemCatalogueIndex.fallbackSlot(id,name);
                    AutoCategories.Item fact=new AutoCategories.Item(id,name,stats!=null && stats.isEquipable(),item.getInventoryActions(),
                        eq==null?0:Math.max(eq.getAstab(),Math.max(eq.getAslash(),eq.getAcrush()))+eq.getStr(),
                        eq==null?0:eq.getArange()+eq.getRstr(),eq==null?0:eq.getAmagic()+(int)eq.getMdmg(),slot);
                    catalogue.add(new ItemCatalogueIndex.Item(fact,name,slot));
                }
            } catch(RuntimeException ex) { failed(request,ex); return true; }
            if(cursor[0]<count) return false;
            new SwingWorker<ItemCatalogueIndex,Void>() {
                private GeCategorySearch categories;
                protected ItemCatalogueIndex doInBackground() { categories=new GeCategorySearch(catalogue);return new ItemCatalogueIndex(catalogue); }
                protected void done() {
                    try {
                        ItemCatalogueIndex built=get();
                        thread.invokeLater(() -> { if(current(request)) { index=built;shopping=categories; preparing=false; } });
                    } catch(Exception ex) { thread.invokeLater(() -> failed(request,ex)); }
                }
            }.execute();
            return true;
        });
    }
    @Subscribe(priority=-50) public void onGrandExchangeSearched(GrandExchangeSearched event)
    {
        clear(); geSearchOpen=true;
        if(!active || !config.geCatalogueSearch() || event.isConsumed()) return;
        prepare();
        if(index==null) return;
        String input=client.getVarcStrValue(VarClientID.MESLAYERINPUT);
        if(input==null || input.length()>100 || !BankSearchIndex.plainQuery(input)) return;
        GeActivityFilter.Query options=GeActivityFilter.Query.parse(input,config.geActivityFilter());
        ItemCatalogueIndex.Result next=shopping==null || !options.text.equals(input)?null:shopping.find(options.text);
        if(next==null) next=index.find(options.text,config.geGuideContext(),"",client.getRealSkillLevel(Skill.HITPOINTS));
        // Ownership words are GE activity qualifiers, not a general item-name rewrite.
        if(!options.text.equals(input) && (next==null || !next.activity)) next=index.find(input,config.geGuideContext(),"",client.getRealSkillLevel(Skill.HITPOINTS));
        if(next==null) return;
        if(shopping!=null) suggestions=shopping.suggestions(options.text,next.activity);
        activityMode=next.activity?options.mode:WindowMarkersConfig.ActivityItems.ALL;
        if(next.activity && (activityMode!=WindowMarkersConfig.ActivityItems.ALL || config.geHideWorseOwned())) {
            GeActivityFilter.Outcome filtered=GeActivityFilter.apply(next,playerItems.snapshot(),GeRequirements.capture(client,ancientRings),activityMode,config.geHideWorseOwned());
            next=filtered.result;upgrades=filtered.upgrades;notice=filtered.notice;
        }
        query=input; result=next;
        event.consume(); client.setGeSearchResultIndex(0);
        boolean overflow=next.items.size()>ItemCatalogueIndex.LIMIT;
        client.setGeSearchResultCount(overflow ? -1 : next.items.size());
        client.setGeSearchResultIds(overflow ? null : next.ids());
    }
    @Subscribe(priority=-200) public void onScriptPostFired(ScriptPostFired event)
    {
        if(event.getScriptId()!=ScriptID.GE_ITEM_SEARCH) return;
        decorate();
    }
    private void decorate()
    {
        restore();
        if(!valid()) return;
        Widget container=client.getWidget(InterfaceID.Chatbox.MES_LAYER_SCROLLCONTENTS);
        if(container==null || container.isHidden()) return;
        Widget[] children=container.getDynamicChildren();
        if(children==null || children.length%3!=0) return;
        resultContainer=container;
        Map<Integer,ItemCatalogueIndex.Item> byId=new HashMap<>();for(ItemCatalogueIndex.Item item:result.items) byId.put(item.id,item);
        boolean ownership=result.activity && (config.geMarkOwned() || activityMode!=WindowMarkersConfig.ActivityItems.ALL);
        GePlayerItems.Snapshot owned=(ownership || config.geShowPrices())?playerItems.snapshot():GePlayerItems.Snapshot.unknown();
        GeRequirements requirements=config.geMarkLocked()?GeRequirements.capture(client,ancientRings):null;
        // This is the same public result triplet used by RuneLite's GE search
        // highlighter. Verify item identity before touching an associated label.
        for(int i=0;i+2<children.length;i+=3) {
            Widget label=children[i+1];
            if(label==null) continue;
            Widget icon=children[i]!=null && byId.containsKey(children[i].getItemId()) ? children[i] : children[i+2];
            if(icon==null) continue;
            int id=icon.getItemId();
            ItemCatalogueIndex.Item item=byId.get(id);if(item==null) continue;
            ItemCatalogueIndex.Rank rank=result.ranks.getOrDefault(id,new ItemCatalogueIndex.Rank(0,"No ranked recommendation for this result."));
            String text=label.getText();
            if(text==null || text.isBlank()) continue;
            Decoration decoration=new Decoration(label,text,label.getTextColor(),rank);
            String badges="";
            if(config.geTierColours() && rank.tier>=1 && rank.tier<=3) {
                Color colour=TierPresentation.colour(config,rank.tier);
                badges="["+rank.tier+"]";
                decoration.appliedColour=colour.getRGB() & 0xffffff;
            }
            String detail=rank.explanation;
            if(!badges.isEmpty()) detail="["+rank.tier+"] = "+TierPresentation.ordinal(rank.tier)+" guide tier for this setup and role.\n"+detail;
            if(ownership) {
                ItemCatalogueIndex.Item held=owned.owned(item);
                if(held!=null) {
                    badges="[O]"+badges;
                    detail+="\n[O] = Owned"+(held.id==id?"": " equivalent")+": "+held.name+" (last observed bank, inventory or equipment this login).";
                }
                if(!owned.complete) detail+="\nOpen your bank once this login before relying on ownership filters.";
            }
            if(upgrades.containsKey(id)) { badges="[N]"+badges;detail+="\n[N] = Next guide upgrade. "+upgrades.get(id); }
            if(requirements!=null) {
                String locked=requirements.locked(item);
                if(!locked.isEmpty()) { badges="<col=ff7777>[!]</col>"+badges;detail="[!] = Requires: "+locked+".\n"+detail; }
                detail+="\nRequirement checks cover reviewed skills/unlocks only; other quests, charges and set conditions may apply.";
            }
            if(config.geShowPrices()) {
                long price=itemManager.getItemPrice(id);
                String colour=config.gePriceAffordability()?priceColour(price,owned):"c0c0c0";
                badges+=(badges.isEmpty()?"":" ")+"<col="+colour+">"+(price>0?"~"+compactPrice(price):"~?")+"</col>";
                detail="Guide price: "+(price>0?String.format(Locale.ROOT,"%,d gp each",price):"unavailable")+". Cached RuneLite price; not a guaranteed offer.\n"+detail;
                if(config.gePriceAffordability()) detail="Funds: "+String.format(Locale.ROOT,"%,d gp",owned.funds)+
                    (owned.fundsComplete?" observed in inventory/bank coins and platinum.":" confirmed in inventory; bank balance unverified. Open the bank to refresh.")+
                    " One item at guide price; buy limits and account restrictions still apply.\n"+detail;
            }
            if(!notice.isEmpty()) detail=notice+"\n"+detail;
            decoration.appliedText=GeResultLabel.format(label,text,badges);
            decoration.explanation=item.name+"\n"+detail;
            if(!text.equals(decoration.appliedText)) label.setText(decoration.appliedText);
            if(label.getTextColor()!=decoration.appliedColour) label.setTextColor(decoration.appliedColour);
            decorations.add(decoration);
        }
    }
    private boolean valid()
    { return active && config.geCatalogueSearch() && result!=null && client.getGameState()==GameState.LOGGED_IN
        && query.equals(client.getVarcStrValue(VarClientID.MESLAYERINPUT)); }
    @Subscribe public void onBeforeRender(BeforeRender event)
    {
        if(!active) return;
        prepare();
        if(!valid() || (resultContainer!=null && (resultContainer.isHidden()
            || client.getWidget(InterfaceID.Chatbox.MES_LAYER_SCROLLCONTENTS)!=resultContainer))) clear();
        if(client.getGameState()!=GameState.LOGGED_IN) geSearchOpen=false;
        updateTips();
    }
    @Subscribe public void onWidgetClosed(WidgetClosed event)
    {
        if(event.getGroupId()==InterfaceID.GE_OFFERS || event.getGroupId()==InterfaceID.CHATBOX)
        { clear(); geSearchOpen=false; }
    }
    void clear() { restore(); result=null; query=""; resultContainer=null;notice="";upgrades=Collections.emptyMap();activityMode=WindowMarkersConfig.ActivityItems.ALL;suggestions=Collections.emptyList();if(tips!=null) tips.setHidden(true); }
    private void clearTips()
    {
        if(tips!=null) { tips.setHidden(true);tips.clearActions(); }
        tips=null;tipsParent=null;
    }
    private void updateTips()
    {
        if(!valid() || !config.geSearchTips() || suggestions.isEmpty() && notice.isEmpty()) { if(tips!=null) tips.setHidden(true);return; }
        Widget parent=client.getWidget(InterfaceID.Chatbox.MES_LAYER);
        if(parent==null || parent.isHidden() || parent.getWidth()<300 || parent.getHeight()<85) { if(tips!=null) tips.setHidden(true);return; }
        if(parent!=tipsParent || tips==null || parent.getChildren()==null || !Arrays.asList(parent.getChildren()).contains(tips)) {
            clearTips();tipsParent=parent;tips=parent.createChild(-1,WidgetType.TEXT);
            tips.setFontId(494);tips.setOriginalWidth(110);tips.setOriginalHeight(17);
        }
        // Keep the hint in the header, outside the scrolling item results.
        tips.setOriginalX(8);tips.setOriginalY(2);
        Widget prompt=client.getWidget(InterfaceID.Chatbox.MES_TEXT);
        tips.setTextColor(prompt==null?0:prompt.getTextColor());tips.setTextShadowed(prompt!=null && prompt.getTextShadowed());
        tips.setText(notice.isEmpty()?"Search tips [?]":"Search notice [?]");tips.setHidden(false);tips.revalidate();
    }
    private void restore()
    {
        for(Decoration d:decorations) {
            if(d.appliedText.equals(d.widget.getText())) d.widget.setText(d.text);
            if(d.appliedColour==d.widget.getTextColor()) d.widget.setTextColor(d.colour);
        }
        decorations.clear();
    }
    @Override public Dimension render(Graphics2D graphics)
    {
        if(!active || !config.geCatalogueSearch()) return null;
        net.runelite.api.Point mouse=client.getMouseCanvasPosition();
        if(valid() && tips!=null && !tips.isHidden() && tips.getBounds().contains(mouse.getX(),mouse.getY())) {
            String text=notice;
            if(!suggestions.isEmpty()) text+=(text.isEmpty()?"":"\n")+"Narrow your search. Type one of:\n"+String.join("\n",suggestions);
            tooltips.add(new Tooltip(escape(text)));return null;
        }
        if(valid()) for(Decoration d:decorations) {
            Rectangle bounds=d.widget.getBounds();
            if(bounds!=null && resultContainer!=null) bounds=bounds.intersection(resultContainer.getBounds());
            if(!d.widget.isHidden() && bounds!=null && bounds.contains(mouse.getX(),mouse.getY())) {
                tooltips.add(new Tooltip(escape(d.explanation))); break;
            }
        }
        if(valid() && !notice.isEmpty() && result.items.isEmpty()) {
            Widget area=client.getWidget(InterfaceID.Chatbox.MES_LAYER_SCROLLCONTENTS);
            if(area!=null && !area.isHidden() && area.getBounds().contains(mouse.getX(),mouse.getY())) tooltips.add(new Tooltip(escape(notice)));
        }
        if(geSearchOpen && index==null) {
            Widget area=client.getWidget(InterfaceID.Chatbox.MES_LAYER_SCROLLCONTENTS);
            if(area!=null && !area.isHidden() && area.getBounds().contains(mouse.getX(),mouse.getY()))
                tooltips.add(new Tooltip(failure.isEmpty()?"Improved Banking catalogue is loading. Search again in a moment.":failure));
        }
        return null;
    }
    static String priceColour(long price,GePlayerItems.Snapshot owned)
    { return price<=0?"c0c0c0":price<=owned.funds?"55dd88":owned.fundsComplete?"ff7777":"c0c0c0"; }
    static String compactPrice(long price)
    {
        if(price<1000) return Long.toString(price);
        long unit=price>=1_000_000_000_000L?1_000_000_000_000L:price>=1_000_000_000L?1_000_000_000L:price>=1_000_000L?1_000_000L:1000L;
        return String.format(Locale.ROOT,"%.1f",(double)price/unit).replaceFirst("\\.0$","")+(unit==1000?"k":unit==1_000_000?"m":unit==1_000_000_000?"b":"t");
    }
    private static String escape(String text)
    {
        String s=text.length()>850 ? text.substring(0,847)+"..." : text;
        return s.replace("<","(").replace(">",")").replace("\n","<br>");
    }
    private static final class Decoration
    {
        final Widget widget;
        final String text;
        final int colour;
        final ItemCatalogueIndex.Rank rank;
        String appliedText;
        int appliedColour;
        String explanation;
        Decoration(Widget widget,String text,int colour,ItemCatalogueIndex.Rank rank)
        { this.widget=widget; this.text=text; this.colour=colour; this.rank=rank; appliedText=text; appliedColour=colour;explanation=rank.explanation; }
    }
}

package com.windowmarkers;

import java.util.*;

/** Shopping categories deliberately exclude the rest of an activity's example inventory. */
final class GeCategorySearch
{
    private final Map<String,List<ItemCatalogueIndex.Item>> categories=new LinkedHashMap<>();
    private static final List<String> SKILLS=Arrays.asList("farming","mining","woodcutting","fishing","hunter","crafting","smithing","fletching","construction","herblore","cooking","firemaking","runecraft","agility","thieving");
    GeCategorySearch(Collection<ItemCatalogueIndex.Item> items)
    {
        Set<String> trees=new HashSet<>();
        for(ItemCatalogueIndex.Item item:items) if(group(item,"Farming — saplings")) trees.add(treeName(item.name));
        for(ItemCatalogueIndex.Item item:items) {
            if(ItemVariantState.identityNeedsReview(item.fact)) continue;
            List<WikiCatalogue.Entry> entries=WikiCatalogue.entries(item.fact);
            if(entries.isEmpty()) continue;
            boolean tools=tool(item,entries);
            if(tools) add("tools",item);
            for(String skill:SKILLS) {
                boolean belongs=entries.stream().anyMatch(e->e.group.toLowerCase(Locale.ROOT).startsWith(skill+" — ") && !e.group.endsWith("recipe inputs"));
                if(belongs && tools) add(skill+" tools",item);
                if(!belongs) continue;
                if(entries.stream().anyMatch(e->e.group.toLowerCase(Locale.ROOT).startsWith(skill+" — ") && e.group.endsWith("boosts"))) add(skill+" boosts",item);
                if(entries.stream().anyMatch(e->e.group.toLowerCase(Locale.ROOT).startsWith(skill+" — ") && e.group.endsWith("materials"))) add(skill+" materials",item);
                // The generic skill means direct skill supplies/equipment, not its guide's teleports, food or energy potions.
                if(entries.stream().anyMatch(e->e.group.toLowerCase(Locale.ROOT).startsWith(skill+" — ")
                    && !e.group.endsWith("recipe inputs") && (e.facet.equals("skilling") || e.facet.equals("outfit")))) add(skill,item);
            }
            if(group(item,"Farming — seeds and planting materials") && (item.search.matches(".* seeds?") || item.search.equals("acorn"))) add("farming seeds",item);
            if(group(item,"Farming — saplings")) add("farming saplings",item);
            if(group(item,"Farming — saplings") || group(item,"Farming — seeds and planting materials")
                && (item.search.equals("acorn") || item.search.matches(".* seeds?") && trees.contains(treeName(item.name)))) add("farming trees",item);
            if(entries.stream().anyMatch(e->e.group.startsWith("Farming — ")) && item.search.contains("compost")) add("farming compost",item);
        }
        for(String key:new ArrayList<>(categories.keySet())) categories.get(key).sort(Comparator.comparing(i->i.name,String.CASE_INSENSITIVE_ORDER));
    }
    private static boolean group(ItemCatalogueIndex.Item item,String name)
    { return !ItemVariantState.identityNeedsReview(item.fact) && WikiCatalogue.entries(item.fact).stream().anyMatch(e->e.group.equals(name)); }
    private static String treeName(String name)
    { return SearchText.normalize(name).replaceFirst(" (sapling|seeds?)$","").replaceFirst(" tree$",""); }
    private static boolean tool(ItemCatalogueIndex.Item item,List<WikiCatalogue.Entry> entries)
    {
        if(item.fact.action("Drink") || entries.stream().anyMatch(e->e.group.startsWith("Potions"))) return false;
        if("Tools".equals(ItemTaxonomy.weaponRole(ItemVariantState.familyName(item.fact)))) return true;
        return entries.stream().anyMatch(e->e.facet.equals("skilling") && (e.group.endsWith(" — tools") || e.group.endsWith(" — axes") || e.group.endsWith(" — pickaxes")));
    }
    private void add(String key,ItemCatalogueIndex.Item item)
    { categories.computeIfAbsent(key,k->new ArrayList<>()).add(item); }
    ItemCatalogueIndex.Result find(String input)
    {
        if(input==null || input.length()>100 || !BankSearchIndex.plainQuery(input)) return null;
        String key=SearchText.normalize(input).replaceFirst(" tool$"," tools").replaceFirst(" seed$"," seeds").replaceFirst(" tree$"," trees").replaceFirst(" sapling$"," saplings");
        if(!categories.containsKey(key) && !key.equals("tools") && !key.startsWith("farming ") && !SKILLS.contains(key)) return null;
        if(!categories.containsKey(key) && !Arrays.asList("farming tools","farming seeds","farming saplings","farming trees","farming compost").contains(key) && !SKILLS.contains(key) && !key.equals("tools")) return null;
        List<ItemCatalogueIndex.Item> selected=categories.getOrDefault(key,Collections.emptyList());
        Map<Integer,ItemCatalogueIndex.Rank> notes=new HashMap<>();
        for(ItemCatalogueIndex.Item item:selected) notes.put(item.id,new ItemCatalogueIndex.Rank(0,"Direct "+key+" classification. This is not a complete activity loadout."));
        return new ItemCatalogueIndex.Result(new ArrayList<>(selected),notes,false);
    }
    List<String> suggestions(String input,boolean activity)
    {
        String key=SearchText.normalize(input);
        if(key.equals("farming")) return available("farming seeds","farming trees","farming tools","farming compost");
        if(key.equals("tools")) return available("farming tools","mining tools","woodcutting tools","fishing tools");
        if(SKILLS.contains(key)) return available(key+" tools",key+" materials",key+" boosts");
        if(key.equals("food")) return Arrays.asList("food 20","fast foods","combo food","raw food");
        if(key.equals("potions")) return Arrays.asList("prayer potions","stamina potions","antifire potions","healing potions");
        if(activity) {
            if(Arrays.stream(key.split(" +")).anyMatch(word->ItemCatalogueIndex.slot(word)>=0)) return Arrays.asList(key+" owned",key+" unowned",key+" next upgrade");
            return Arrays.asList(key+" head",key+" top",key+" owned",key+" next upgrade");
        }
        return Collections.emptyList();
    }
    private List<String> available(String... candidates)
    {
        List<String> result=new ArrayList<>();
        for(String candidate:candidates) if(categories.containsKey(candidate)) result.add(candidate);
        return result;
    }
}

package com.windowmarkers;

import java.util.*;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.*;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;

/** Client-thread snapshots only. Nothing is persisted or shared between logins. */
@Singleton
final class GePlayerItems
{
    @Inject Client client;
    @Inject ItemManager itemManager;
    private long account=-1;
    private Map<Integer,Integer> bank=new LinkedHashMap<>();
    private boolean bankSeen, bankFundsKnown;

    void clear() { account=-1;bank.clear();bankSeen=false;bankFundsKnown=false; }
    private boolean context()
    {
        if(client.getGameState()!=GameState.LOGGED_IN) return false;
        long current=client.getAccountHash();
        if(current!=account) { clear();account=current; }
        return current!=-1 && current!=0;
    }
    void bankChanged(ItemContainer container)
    {
        if(!context() || container==null) return;
        bank=read(container);bankSeen=true;bankFundsKnown=true;
    }
    void offersChanged() { bankFundsKnown=false; }
    void observeOpenBank()
    {
        if(!context() || bankSeen && bankFundsKnown) return;
        Widget window=client.getWidget(InterfaceID.Bankmain.UNIVERSE);
        if(window!=null && !window.isHidden()) bankChanged(client.getItemContainer(InventoryID.BANK));
    }
    private Map<Integer,Integer> read(ItemContainer container)
    {
        Map<Integer,Integer> result=new LinkedHashMap<>();
        if(container!=null) for(Item item:container.getItems()) {
            if(item.getId()<0 || item.getQuantity()<=0 || item.getId()==6512) continue;
            ItemComposition definition=itemManager.getItemComposition(item.getId());
            if(definition==null || definition.getPlaceholderTemplateId()!=-1) continue;
            // Only unwrap banknotes here. Variation families can include depleted states;
            // canonicalize also unwraps placeholders and worn variants, not usability.
            int id=definition.getNote()!=-1?definition.getLinkedNoteId():item.getId();
            if(id>=0) result.merge(id,item.getQuantity(),(a,b)->(int)Math.min(Integer.MAX_VALUE,(long)a+b));
        }
        return result;
    }
    static long funds(Map<Integer,Integer> items)
    { return (long)items.getOrDefault(995,0)+1000L*items.getOrDefault(13204,0); }
    Snapshot snapshot()
    {
        if(!context()) return Snapshot.unknown();
        observeOpenBank();
        ItemContainer inventory=client.getItemContainer(InventoryID.INV);
        ItemContainer wornContainer=client.getItemContainer(InventoryID.WORN);
        Map<Integer,Integer> carried=read(inventory),worn=read(wornContainer);
        Set<Integer> ids=new LinkedHashSet<>(bank.keySet());ids.addAll(carried.keySet());ids.addAll(worn.keySet());
        List<ItemCatalogueIndex.Item> facts=new ArrayList<>();
        for(int id:ids) {
            ItemComposition definition=itemManager.getItemComposition(id);
            if(definition==null || definition.getName()==null) continue;
            var stats=itemManager.getItemStats(id);var equipment=stats==null?null:stats.getEquipment();
            int slot=equipment==null?ItemCatalogueIndex.fallbackSlot(id,definition.getName()):equipment.getSlot();
            facts.add(new ItemCatalogueIndex.Item(id,definition.getName(),slot,definition.getInventoryActions()));
        }
        return new Snapshot(bankSeen && inventory!=null && wornContainer!=null,facts,funds(carried)+(bankFundsKnown?funds(bank):0),bankFundsKnown && inventory!=null);
    }
    static final class Snapshot
    {
        final boolean complete, fundsComplete;
        final List<ItemCatalogueIndex.Item> items;
        final long funds;
        Snapshot(boolean complete,List<ItemCatalogueIndex.Item> items,long funds,boolean fundsComplete)
        { this.complete=complete;this.items=Collections.unmodifiableList(new ArrayList<>(items));this.funds=funds;this.fundsComplete=fundsComplete; }
        static Snapshot unknown() { return new Snapshot(false,Collections.emptyList(),0,false); }
        ItemCatalogueIndex.Item owned(ItemCatalogueIndex.Item candidate)
        {
            for(ItemCatalogueIndex.Item item:items) if(item.id==candidate.id) return item;
            // Equivalent equipment only: readiness and retained benefits are directional.
            if(candidate.slot>=0) for(ItemCatalogueIndex.Item item:items)
                if(item.slot==candidate.slot && ItemVariantState.canRepresentOwnedEquivalent(item.fact,candidate.fact)
                    && ItemTaxonomy.baseName(CombatEquivalence.familyName(item.fact)).equals(ItemTaxonomy.baseName(CombatEquivalence.familyName(candidate.fact)))) return item;
            return null;
        }
    }
}

package com.windowmarkers;

import java.util.*;
import net.runelite.api.*;

/** Proven restrictions only. A blank reason is not proof that every quest/unlock is satisfied. */
final class GeRequirements
{
    private static final List<String[]> REQUIREMENTS=ItemTaxonomy.readRows("raid-wear-requirements.tsv",8);
    private static final Skill[] SKILLS={Skill.ATTACK,Skill.STRENGTH,Skill.DEFENCE,Skill.RANGED,Skill.MAGIC,Skill.PRAYER,Skill.HITPOINTS};
    private final int[] levels;
    private final boolean allMaxed;
    private final Boolean ancientRings;
    static void prepare() { /* initialize bundled data on the catalogue worker */ }
    GeRequirements(int[] levels,boolean allMaxed,Boolean ancientRings)
    { this.levels=levels.clone();this.allMaxed=allMaxed;this.ancientRings=ancientRings; }
    static GeRequirements capture(Client client,Boolean ancientRings)
    {
        int[] levels=new int[SKILLS.length];for(int i=0;i<levels.length;i++) levels[i]=client.getRealSkillLevel(SKILLS[i]);
        boolean maxed=Arrays.stream(Skill.values()).filter(s->s!=Skill.OVERALL).allMatch(s->client.getRealSkillLevel(s)>=99);
        return new GeRequirements(levels,maxed,ancientRings);
    }
    boolean reviewed(ItemCatalogueIndex.Item item)
    { return REQUIREMENTS.stream().anyMatch(row->CombatEquivalence.matches(item.fact,row[0])); }
    String locked(ItemCatalogueIndex.Item item)
    {
        List<String> missing=new ArrayList<>();
        if(CombatEquivalence.requiresMaxedSkills(item.fact) && !allMaxed) missing.add("99 in every skill");
        if(CombatEquivalence.matchesAny(item.fact,"ultor ring","magus ring","venator ring","bellator ring") && Boolean.FALSE.equals(ancientRings))
            missing.add("Desert Treasure II completion");
        for(String[] row:REQUIREMENTS) if(CombatEquivalence.matches(item.fact,row[0])) {
            for(int i=0;i<SKILLS.length;i++) if(levels[i]<Integer.parseInt(row[i+1])) missing.add(row[i+1]+" "+SKILLS[i].getName());
            break;
        }
        return String.join(", ",missing);
    }
}

package com.windowmarkers;

import net.runelite.api.FontTypeFace;
import net.runelite.api.widgets.Widget;

/** Fits annotations inside the native GE result row without moving its click target. */
final class GeResultLabel
{
    static String format(Widget label, String name, String details)
    {
        if (details.isEmpty()) return name;
        FontTypeFace font = label.getFont();
        int width = label.getWidth();
        if (font == null || width <= 0) return name;
        int lineHeight = label.getLineHeight() > 0 ? label.getLineHeight() : font.getBaseline();
        // Unusual layouts may only have room for the name. Details remain in the tooltip.
        if (lineHeight <= 0 || label.getHeight() < lineHeight * 2) return fit(name, font, width);
        return fit(name, font, width) + "<br>" + fit(details, font, width);
    }

    static String fit(String text, FontTypeFace font, int width)
    {
        text = text.replace("<br>", " ");
        if (font.getTextWidth(text) <= width) return text;
        String ending = "...</col></u></str>";
        if (font.getTextWidth(ending) > width) return "";
        StringBuilder prefix = new StringBuilder();
        // Preserve the native search highlighting; never cut through a markup tag.
        for (int i = 0; i < text.length();) {
            int end = text.charAt(i) == '<' ? text.indexOf('>', i) + 1 : i + 1;
            if (end <= i) end = i + 1;
            String token = text.substring(i, end);
            if (font.getTextWidth(prefix.toString() + token + ending) > width) break;
            prefix.append(token);
            i = end;
        }
        return prefix + ending;
    }
}

package com.windowmarkers;

import java.util.*;

/** Identity-based edits keep filtered-out groups and saved item variants intact. */
final class GroupEdits
{
    static int[] union(Collection<Marker> groups)
    { return groups.stream().filter(Marker::linked).flatMapToInt(m -> Arrays.stream(m.linkedItemIds)).distinct().toArray(); }

    static boolean reorder(List<Marker> all,List<Marker> visible,List<Marker> moving,int dropIndex)
    {
        if(visible.isEmpty() || moving.isEmpty() || dropIndex<0 || dropIndex>visible.size()
            || !all.containsAll(visible) || !visible.containsAll(moving)
            || new HashSet<>(visible).size()!=visible.size()) return false;
        List<Marker> actual=new ArrayList<>();
        for(Marker marker:all) if(visible.contains(marker)) actual.add(marker);
        if(!actual.equals(visible)) return false;
        List<Marker> ordered=new ArrayList<>(visible);
        List<Marker> picked=new ArrayList<>(); int before=0;
        for(int i=0;i<visible.size();i++) if(moving.contains(visible.get(i)))
        { picked.add(visible.get(i)); if(i<dropIndex) before++; }
        ordered.removeAll(picked); ordered.addAll(dropIndex-before,picked);
        if(ordered.equals(visible)) return false;
        int index=0;
        for(int i=0;i<all.size();i++) if(visible.contains(all.get(i))) all.set(i,ordered.get(index++));
        return true;
    }
}

package com.windowmarkers;

import java.util.*;

/** Owned combat switches, separate from teleport/charge requirements and guide ranks. */
final class InventoryGearAlternatives
{
    private static final Map<Integer,AutoCategories.Item> IDENTITIES=new HashMap<>();
    private static final Map<String,List<Integer>> FAMILIES=new HashMap<>();
    static {
        for(String[] row:ItemTaxonomy.readRows("ge-item-slots.tsv",3)) {
            int id=Integer.parseInt(row[0]),slot=Integer.parseInt(row[1]);
            IDENTITIES.put(id,new AutoCategories.Item(id,row[2],true,null,0,0,0,slot));
        }
        for(AutoCategories.Item item:IDENTITIES.values())
            FAMILIES.computeIfAbsent(family(item),key->new ArrayList<>()).add(item.id);
        FAMILIES.values().forEach(Collections::sort);
    }
    private InventoryGearAlternatives() { }

    static String family(AutoCategories.Item item) {
        return ItemTaxonomy.baseName(CombatEquivalence.familyName(item));
    }
    static boolean sameCombatItem(int expected,AutoCategories.Item held) {
        AutoCategories.Item example=IDENTITIES.get(expected),identity=IDENTITIES.get(held.id);
        if(example==null || identity==null || !identity.name.equals(held.name) || example.slot!=identity.slot) return false;
        // Rings, weapons and ammo can represent teleports, specific specials,
        // gathering effects or ammunition requirements rather than a gear swap.
        if(!Arrays.asList(0,1,2,4,5,7,9,10).contains(example.slot)) return false;
        return family(example).equals(family(held)) && ItemVariantState.canRepresentOwnedEquivalent(held,example);
    }
    static List<Integer> equivalents(List<Integer> exact,Map<Integer,ItemCatalogueIndex.Item> owned) {
        List<Integer> result=new ArrayList<>(exact);
        for(int expected:exact) {
            AutoCategories.Item example=IDENTITIES.get(expected);
            if(example==null) continue;
            for(int id:FAMILIES.getOrDefault(family(example),Collections.emptyList())) {
                ItemCatalogueIndex.Item item=owned.get(id);
                if(item!=null && !result.contains(id) && sameCombatItem(expected,item.fact)) result.add(id);
            }
        }
        return result;
    }
    static boolean rangedAccessory(int id) {
        AutoCategories.Item item=IDENTITIES.get(id);
        if(item==null) return false;
        return Arrays.asList("dizana's quiver","ava's assembler","ava's accumulator",
            "necklace of anguish","necklace of rupture","twisted buckler","dragonfire ward",
            "odium ward","aquanite hopper","book of law","antler guard").contains(family(item));
    }
    static boolean sameCombatItem(int expected,int candidate) {
        AutoCategories.Item item=IDENTITIES.get(candidate);
        return item!=null && (expected==candidate || sameCombatItem(expected,item));
    }
}

package com.windowmarkers;

import java.util.*;

/** Same potion, different remaining doses; never substitute a different effect. */
final class InventoryPotionDoses
{
    private static final Map<Integer,String[]> DOSES=new HashMap<>();
    private static final Map<String,List<Integer>> FAMILIES=new HashMap<>();
    static {
        for(String[] row:ItemTaxonomy.readRows("inventory-potion-doses.tsv",4)) {
            int id=Integer.parseInt(row[0]);DOSES.put(id,row);
            FAMILIES.computeIfAbsent(row[2],k->new ArrayList<>()).add(id);
        }
        FAMILIES.values().forEach(ids->ids.sort(Comparator.comparingInt(id->-Integer.parseInt(DOSES.get(id)[3]))));
    }
    private InventoryPotionDoses() { }
    static boolean listed(Collection<Integer> exact,AutoCategories.Item item) {
        String[] row=DOSES.get(item.id);
        return row!=null && row[1].equalsIgnoreCase(item.name)
            && exact.stream().anyMatch(id->DOSES.containsKey(id) && DOSES.get(id)[2].equals(row[2]));
    }
    static List<Integer> alternatives(List<Integer> exact) {
        List<Integer> result=new ArrayList<>(exact);
        for(int id:exact) if(DOSES.containsKey(id)) for(int other:FAMILIES.get(DOSES.get(id)[2]))
            if(!result.contains(other)) result.add(other);
        return result;
    }
    static boolean known(int id) { return DOSES.containsKey(id); }
    static String note(int id) {
        return "Owned "+DOSES.get(id)[3]+"-dose alternative of the same potion. The guide's total doses are not guaranteed; repeated slots share your bank stack.";
    }
}

package com.windowmarkers;

import java.awt.Rectangle;
import java.util.*;

/** Pure geometry for matching visible items without changing game widgets. */
final class ItemAnchors
{
    static final class Cell
    {
        final int id;
        final Rectangle icon, grid;
        Cell(int id, Rectangle icon)
        {
            this.id=id; this.icon=new Rectangle(icon);
            grid=new Rectangle(icon);
            // The native bank slot has 12px horizontal and 4px vertical spacing.
            if (grid.width <= 36) { grid.x-=6; grid.width+=12; }
            if (grid.height <= 32) { grid.y-=2; grid.height+=4; }
        }
    }

    static int[] enclosed(Rectangle selection, List<Cell> cells, Rectangle viewport)
    {
        return cells.stream().filter(c -> viewport.contains(c.icon.getCenterX(),c.icon.getCenterY())
            && selection.contains(c.icon.getCenterX(),c.icon.getCenterY())).mapToInt(c -> c.id).distinct().toArray();
    }

    static void fitGrid(List<Cell> cells)
    {
        Map<Integer,List<Cell>> rows=new TreeMap<>();
        for(Cell cell:cells) rows.computeIfAbsent(cell.icon.y,y -> new ArrayList<>()).add(cell);
        for(List<Cell> row:rows.values()) {
            row.sort(Comparator.comparingInt(c -> c.icon.x));
            for(int i=0;i<row.size();i++) {
                Cell cell=row.get(i);
                int left=i>0?cell.icon.x-row.get(i-1).icon.x-row.get(i-1).icon.width:-1;
                int right=i+1<row.size()?row.get(i+1).icon.x-cell.icon.x-cell.icon.width:-1;
                // Larger gaps are equipment-diagram spaces, not slot padding.
                if(left<0 || left>24) left=right>=0 && right<=24?right:12;
                if(right<0 || right>24) right=left;
                int before=left-left/2,after=right/2;
                cell.grid.x=cell.icon.x-before;cell.grid.width=cell.icon.width+before+after;
            }
        }
    }

    static Rectangle snap(Rectangle selection, List<Cell> cells)
    {
        if (cells.isEmpty()) { return selection; }
        // Tab separators and setup sections do not share the first row's origin.
        // Snap to the actual cells touched by the drag, not an invented global grid.
        Rectangle snapped=null;
        for(Cell cell:cells) if(selection.intersects(cell.icon))
            snapped=snapped==null?new Rectangle(cell.grid):snapped.union(cell.grid);
        return snapped==null?new Rectangle(selection):snapped;
    }

    static List<Rectangle> regions(int[] ids, List<Cell> cells)
    {
        Set<Integer> wanted=new HashSet<>(); for (int id : ids) { wanted.add(id); }
        List<Rectangle> result=new ArrayList<>();
        for (Cell cell : cells)
        {
            if (wanted.contains(cell.id) && !result.contains(cell.grid)) { result.add(new Rectangle(cell.grid)); }
        }
        result.sort(Comparator.comparingInt((Rectangle r)->r.y).thenComparingInt(r->r.x));
        // Merge only full shared edges: unrelated slots and holes stay unmarked.
        boolean changed;
        do
        {
            changed=false;
            outer: for (int i=0;i<result.size();i++) for (int j=i+1;j<result.size();j++)
            {
                Rectangle a=result.get(i), b=result.get(j);
                boolean horizontal=a.y==b.y && a.height==b.height && (a.x+a.width==b.x || b.x+b.width==a.x);
                boolean vertical=a.x==b.x && a.width==b.width && (a.y+a.height==b.y || b.y+b.height==a.y);
                if (horizontal || vertical)
                { result.set(i,a.union(b)); result.remove(j); changed=true; break outer; }
            }
        } while (changed);
        return result;
    }
}

package com.windowmarkers;

import java.util.*;
import java.util.stream.Collectors;

/** Shared immutable categories and guide rankings. Callers supply GE-tradeable or owned identities. */
final class ItemCatalogueIndex
{
    static final int LIMIT=250;
    static final class Item
    {
        final int id, slot;
        final String name, search;
        final AutoCategories.Item fact;
        Item(int id,String name,int slot,String[] actions)
        { this(new AutoCategories.Item(id,name,slot>=0,actions,0,0,0,slot),name,slot); }
        Item(AutoCategories.Item fact,String name,int slot)
        { id=fact.id; this.name=name; search=SearchText.normalize(name); this.slot=slot; this.fact=fact; }
    }
    static final class Rank
    {
        final int tier;
        final String explanation,role;
        Rank(int tier,String explanation) { this(tier,explanation,""); }
        Rank(int tier,String explanation,String role) { this.tier=tier; this.explanation=explanation; this.role=role; }
    }
    static final class Result
    {
        final List<Item> items;
        final Map<Integer,Rank> ranks;
        final boolean activity;
        final SetupLoadout loadout;
        final List<ActivitySetups.Setup> setups;
        Result(List<Item> items,Map<Integer,Rank> ranks,boolean activity) { this(items,ranks,activity,null); }
        Result(List<Item> items,Map<Integer,Rank> ranks,boolean activity,SetupLoadout loadout) { this(items,ranks,activity,loadout,Collections.emptyList()); }
        Result(List<Item> items,Map<Integer,Rank> ranks,boolean activity,SetupLoadout loadout,List<ActivitySetups.Setup> setups)
        { this.items=items; this.ranks=ranks; this.activity=activity; this.loadout=loadout; this.setups=Collections.unmodifiableList(new ArrayList<>(setups)); }
        short[] ids() { short[] ids=new short[items.size()]; for(int i=0;i<ids.length;i++) ids[i]=(short)items.get(i).id; return ids; }
    }
    private static final class Field
    {
        final String slot, note;
        final int tier;
        Field(String[] row) { slot=row[2]; tier=Integer.parseInt(row[3]); note=row[4]; }
    }
    private static final Map<String,Map<Integer,List<Field>>> RANKS=new HashMap<>();
    private static final Map<Integer,String[]> SLOTS=new HashMap<>();
    private static final List<String[]> PURCHASE_VARIANTS=ItemTaxonomy.readRows("ge-purchase-variants.tsv",5);
    private static final Map<Integer,String[]> FUNCTIONAL_SLOTS=new HashMap<>();
    private static final Map<Integer,String[]> VARIANT_NOTES=new HashMap<>();
    static
    {
        for(String[] row:ItemTaxonomy.readRows("activity-setup-ranks.tsv",5))
            RANKS.computeIfAbsent(row[0],k->new HashMap<>()).computeIfAbsent(Integer.parseInt(row[1]),k->new ArrayList<>()).add(new Field(row));
        for(String[] row:ItemTaxonomy.readRows("ge-item-slots.tsv",3)) SLOTS.put(Integer.parseInt(row[0]),row);
        for(String[] row:ItemTaxonomy.readRows("ge-functional-slots.tsv",5)) FUNCTIONAL_SLOTS.put(Integer.parseInt(row[0]),row);
        for(String[] row:ItemTaxonomy.readRows("catalogue-variant-notes.tsv",4)) VARIANT_NOTES.put(Integer.parseInt(row[0]),row);
    }
    static int fallbackSlot(int id,String name)
    { String[] row=SLOTS.get(id); return row!=null && row[2].equalsIgnoreCase(name) ? Integer.parseInt(row[1]) : -1; }

    private final Map<Integer,Item> items=new HashMap<>();
    private final Map<String,Set<Integer>> categories=new LinkedHashMap<>();
    private final Map<AutoCategories.Preset,Set<Integer>> presets=new EnumMap<>(AutoCategories.Preset.class);
    private final Map<String,Map<String,Set<Integer>>> activityCategories=new LinkedHashMap<>();
    private final List<ActivitySetups.Setup> setups=ActivitySetups.all();
    private final Map<String,String> setupText=new HashMap<>();
    private final Map<String,Set<Integer>> setupItems=new HashMap<>();
    private final Map<String,Map<Integer,String>> purchaseNotes=new HashMap<>();
    private final Set<String> exactNames=new HashSet<>();
    private final Set<String> vocabulary=new HashSet<>();
    private final boolean ge;

    ItemCatalogueIndex(List<Item> catalogue)
    { this(catalogue,true); }
    ItemCatalogueIndex(List<Item> catalogue,boolean ge)
    {
        this.ge=ge;
        Map<Integer,List<String>> itemGroups=new HashMap<>();
        for(Item item:catalogue)
        {
            if(item.id<0 || item.id>65535) continue;
            items.put(item.id,item); exactNames.add(normalize(item.name));
            if(!ItemVariantState.identityNeedsReview(item.fact))
                for(WikiCatalogue.Entry entry:WikiCatalogue.entries(item.fact)) {
                    add(entry.group,item.id);
                    itemGroups.computeIfAbsent(item.id,k->new ArrayList<>()).add(normalize(entry.group));
                    // Index the factual facet, not a mixed preset title. A
                    // food query must not include tools merely because they
                    // boost a skill and a preset also includes boost items.
                    add(entry.facet,item.id);
                    if(entry.facet.equals("outfit")) { add("skilling outfits",item.id); }
                    if(entry.facet.equals("combat")) add("general combat",item.id);
                    if(entry.facet.equals("skilling") && entry.group.contains(" — ")
                        && "Tools".equals(ItemTaxonomy.weaponRole(ItemVariantState.familyName(item.fact))))
                        add(entry.group.substring(0,entry.group.indexOf(" — "))+" tools",item.id);
                }
        }
        // Preset subcategories are the same labels exposed in the bank legend.
        // Index each factual group, not mixed preset titles that would turn a
        // food query into every potion or resource in a broad preset.
        List<AutoCategories.Item> facts=new ArrayList<>();
        items.values().forEach(item->facts.add(item.fact));
        for(AutoCategories.Preset preset:AutoCategories.Preset.values()) {
            Set<Integer> membership=new HashSet<>();presets.put(preset,membership);
            AutoCategories.suggest(preset,facts).forEach((group,members)-> {
                for(AutoCategories.Item item:members) { add(group,item.id); if(!group.startsWith("Other")) membership.add(item.id); }
            });
        }
        Map<String,Set<Integer>> byActivity=new HashMap<>();
        for(ActivitySetups.Setup setup:setups) {
            setupText.put(setup.id,normalize(setup.activity+" "+setup.label));
            Set<Integer> ids=new HashSet<>(setup.itemIds);
            for(String[] rule:PURCHASE_VARIANTS) {
                int reference=Integer.parseInt(rule[0]),target=Integer.parseInt(rule[1]);
                Item item=items.get(target);
                if(setup.itemIds.contains(reference) && item!=null && item.name.equalsIgnoreCase(rule[2]) && ids.add(target))
                    purchaseNotes.computeIfAbsent(setup.id,k->new HashMap<>()).put(target,rule[3]);
            }
            setupItems.put(setup.id,ids);
            byActivity.computeIfAbsent(normalize(setup.activity),k->new HashSet<>()).addAll(ids);
        }
        byActivity.forEach((activity,ids)-> {
            Map<String,Set<Integer>> groups=new HashMap<>();
            for(int id:ids) for(String group:itemGroups.getOrDefault(id,Collections.emptyList()))
                groups.computeIfAbsent(activity+" "+group,k->new HashSet<>()).add(id);
            activityCategories.put(activity,groups);
        });
        setupText.values().forEach(this::indexWords);
        categories.keySet().forEach(this::indexWords);
        activityCategories.values().forEach(groups->groups.keySet().forEach(this::indexWords));
    }
    private void indexWords(String text) { Collections.addAll(vocabulary,text.split(" +")); }
    private void add(String text,int id)
    { categories.computeIfAbsent(normalize(text),k->new HashSet<>()).add(id); }
    Map<String,Set<Integer>> categoryDocuments() { return Collections.unmodifiableMap(categories); }
    Set<Integer> presetIds(AutoCategories.Preset preset) { return Collections.unmodifiableSet(presets.get(preset)); }
    static String normalize(String query)
    {
        String s=" "+SearchText.normalize(query)+" ";
        String[][] aliases={{"toa","tombs of amascut"},{"cox","chambers of xeric"},{"tob","theatre of blood"},
            {"kbd","king black dragon"},{"kq","kalphite queen"},
            {"dks","dagannoth kings"},{"corp","corporeal beast"},{"mage","magic"},{"range","ranged"},{"armor","armour"}};
        for(String[] alias:aliases) s=s.replace(" "+alias[0]+" "," "+alias[1]+" ");
        return s.trim();
    }
    static int slot(String token)
    {
        switch(token) {
            case "head": case "helm": case "helmet": case "hat": case "hood": case "headgear": case "helms": case "helmets": case "hats": return 0;
            case "cape": case "back": case "capes": return 1;
            case "neck": case "amulet": case "necklace": case "amulets": case "necklaces": case "pendant": return 2;
            case "weapon": case "weapons": return 3;
            case "body": case "chest": case "torso": case "top": case "tops": case "platebody": case "robetop": return 4;
            case "shield": case "shields": case "offhand": case "defender": return 5;
            case "legs": case "leg": case "bottom": case "bottoms": case "platelegs": case "plateskirt": case "chaps": case "tassets": case "skirt": return 7;
            case "hands": case "hand": case "gloves": case "glove": case "gauntlets": case "bracers": return 9;
            case "feet": case "foot": case "boots": case "boot": case "shoes": return 10;
            case "ring": case "rings": return 12;
            case "ammo": case "ammunition": case "arrows": case "bolts": return 13;
            default:return -1;
        }
    }
    private static boolean matches(String text,String query,boolean fuzzy)
    {
        boolean exact=true;
        for(String word:query.split(" +")) if(!text.contains(word)) { exact=false; break; }
        return exact || fuzzy && SearchText.normalizedScore(text,query)!=Integer.MAX_VALUE;
    }
    private static boolean mentionsActivity(String query,String activity,boolean fuzzy)
    {
        for(String word:normalize(activity).split(" +")) {
            if(word.length()<3 || word.equals("the") || word.equals("and")) continue;
            for(String term:query.split(" +"))
                if(term.length()>=3 && matches(word,term,fuzzy)) return true;
        }
        return false;
    }
    private boolean exactCategoryMatch(String terms)
    {
        if(setupText.values().stream().anyMatch(t->matches(t,terms,false))
            || categories.keySet().stream().anyMatch(t->matches(t,terms,false))) return true;
        for(Map.Entry<String,Map<String,Set<Integer>>> activity:activityCategories.entrySet())
            if(mentionsActivity(terms,activity.getKey(),false)
                && activity.getValue().keySet().stream().anyMatch(t->matches(t,terms,false))) return true;
        return false;
    }
    private String correctWholeWords(String terms)
    { return SearchText.correctWholeWords(vocabulary,terms); }

    /** Null means leave native search (and other search plugins) entirely alone. */
    Result find(String raw,String context)
    { return find(raw,context,""); }
    Result find(String raw,String context,String inventoryContext)
    { return find(raw,context,inventoryContext,99); }
    Result find(String raw,String context,String inventoryContext,int hitpoints)
    {
        if(!BankSearchIndex.plainQuery(raw) || raw.length()>100) return null;
        SupplySearch.Query supply=SupplySearch.parse(raw);
        if(supply!=null) return SupplySearch.find(supply,items.values(),hitpoints);
        String query=normalize(ActivityMenu.query(raw));
        ActivitySetups.Setup chosen=setups.stream().filter(s->s.id.equals(context)).findFirst().orElse(null);
        // Explicit guide selection disambiguates activities that are also item
        // names (for example Gout tuber or a boss pet). Ordinary item searches
        // still pass through when no matching guide has been selected.
        boolean selectedActivity=chosen!=null && mentionsActivity(query,chosen.activity,false);
        if(query.length()<3 || exactNames.contains(normalize(raw)) && !categories.containsKey(query) && !selectedActivity) return null;
        SearchQuery qualifiers=SearchQuery.parse(raw);
        query=normalize(ActivityMenu.query(qualifiers.text));
        boolean exactActivityQuery=false;
        for(ActivitySetups.Setup setup:setups) if(normalize(setup.activity).equals(query)) { exactActivityQuery=true;break; }
        int wantedSlot=-1;
        List<String> words=new ArrayList<>();
        for(String word:query.split(" +")) {
            int candidate=exactActivityQuery?-1:slot(word);
            if(candidate>=0) { if(wantedSlot>=0 && wantedSlot!=candidate) return null; wantedSlot=candidate; }
            else words.add(word);
        }
        String terms=String.join(" ",words);
        // Prefer exact words/prefixes globally. A valid "food" query must not
        // acquire Woodcutting gear merely because food is one edit from wood.
        boolean fuzzy=!terms.isEmpty() && !exactCategoryMatch(terms);
        if(fuzzy) {
            // A complete-word correction outranks a loose prefix match:
            // "minign tools" means mining, not tools for a minigame.
            String corrected=correctWholeWords(terms);
            if(!corrected.equals(terms) && exactCategoryMatch(corrected)) { terms=corrected; fuzzy=false; }
        }
        Set<Integer> found=new HashSet<>();
        List<ActivitySetups.Setup> matched=new ArrayList<>();
        boolean useContext=chosen!=null && mentionsActivity(terms,chosen.activity,fuzzy);
        boolean recognized=terms.isEmpty() && wantedSlot>=0;
        if(recognized) found.addAll(items.keySet());
        if(!terms.isEmpty()) {
            String exactActivity="";
            for(ActivitySetups.Setup setup:setups) if(normalize(setup.activity).equals(terms)) { exactActivity=terms;break; }
            for(ActivitySetups.Setup setup:setups) if(matches(setupText.get(setup.id),terms,fuzzy)) {
                // An exact activity such as Abyss must not acquire Abyssal Sire.
                // Parent activities still include their slash-delimited variants.
                if(!exactActivity.isEmpty() && !normalize(setup.activity).equals(exactActivity) && !family(setup.activity).equals(exactActivity)) continue;
                recognized=true;
                // A selected guide only narrows that activity; other activities
                // and ordinary categories remain searchable.
                if(useContext && family(chosen.activity).equals(family(setup.activity)) && chosen!=setup) continue;
                if(mentionsActivity(terms,setup.activity,fuzzy)) matched.add(setup);
                found.addAll(setupItems.get(setup.id));
            }
            for(Map.Entry<String,Set<Integer>> category:categories.entrySet()) if(matches(category.getKey(),terms,fuzzy)) {
                recognized=true; found.addAll(category.getValue());
            }
            for(Map.Entry<String,Map<String,Set<Integer>>> activity:activityCategories.entrySet())
                if((exactActivity.isEmpty() || normalize(activity.getKey()).equals(exactActivity) || family(activity.getKey()).equals(exactActivity)) && mentionsActivity(terms,activity.getKey(),fuzzy))
                    for(Map.Entry<String,Set<Integer>> group:activity.getValue().entrySet()) if(matches(group.getKey(),terms,fuzzy)) {
                        recognized=true; found.addAll(group.getValue());
                    }
        }
        if(!recognized) return null;
        if(useContext) found.retainAll(setupItems.get(chosen.id));
        // Preserve ordinary name matches alongside semantic additions. Purchase
        // variants above are explicit, source-backed links, not family guesses.
        String ordinary=SearchText.normalize(raw);
        for(Item item:items.values()) if(item.search.contains(ordinary)) found.add(item.id);
        final int filterSlot=wantedSlot;
        List<Item> result=found.stream().map(items::get).filter(Objects::nonNull)
            .filter(i->filterSlot<0 || fitsSlot(i,filterSlot) || i.search.contains(ordinary))
            .sorted(Comparator.comparing((Item i)->i.name,String.CASE_INSENSITIVE_ORDER).thenComparingInt(i->i.id)).collect(Collectors.toList());
        Map<Integer,Rank> ranks=new HashMap<>();
        if(!ge || result.size()<=LIMIT || !matched.isEmpty() || !qualifiers.tiers.isEmpty()) for(Item item:result) ranks.put(item.id,rank(item,matched,wantedSlot));
        if(!qualifiers.tiers.isEmpty()) {
            result.removeIf(item->!qualifiers.accepts(ranks.get(item.id)));
            Set<Integer> retained=result.stream().map(item->item.id).collect(Collectors.toSet());
            ranks.keySet().retainAll(retained);
        }
        SetupLoadout loadout=!ge && wantedSlot<0 && qualifiers.tiers.isEmpty()
            ? SetupLoadout.build(matched,items,found,inventoryContext):null;
        if(loadout!=null) {
            if(loadout.wildernessBudget) {
                result.removeIf(item->!WildernessLoadout.allowed(item));
                Set<Integer> retained=result.stream().map(i->i.id).collect(Collectors.toSet());
                ranks.keySet().retainAll(retained);
            }
            Set<Integer> included=result.stream().map(i->i.id).collect(Collectors.toSet());
            for(int id:loadout.itemIds()) if(items.containsKey(id) && included.add(id)) {
                result.add(items.get(id));
                ranks.put(id,new Rank(0,"Owned alternative completing this setup. Not ranked by this activity's source table."));
            }
        }
        return new Result(result,ranks,!matched.isEmpty(),loadout,matched);
    }
    Map<Integer,Rank> guideRanks(String query,String context)
    { return guideRanks(query,context,99); }
    Map<Integer,Rank> guideRanks(String query,String context,int hitpoints)
    {
        Result result=find(query,context,"",hitpoints);
        return result==null?Collections.emptyMap():result.ranks;
    }
    private static String family(String activity) { return normalize(ActivityMenu.canonical(activity).split("/",2)[0]); }
    private static String[] functionalSlot(Item item)
    { String[] row=FUNCTIONAL_SLOTS.get(item.id); return row!=null && row[1].equalsIgnoreCase(item.name)?row:null; }
    private static boolean fitsSlot(Item item,int slot)
    { String[] row=functionalSlot(item); return item.slot==slot || row!=null && Integer.parseInt(row[2])==slot; }
    private Rank rank(Item item,List<ActivitySetups.Setup> matched,int wantedSlot)
    {
        Set<String> notes=new LinkedHashSet<>();
        String[] variant=VARIANT_NOTES.get(item.id);
        if(variant!=null && variant[1].equalsIgnoreCase(item.name)) notes.add(variant[2]);
        for(ActivitySetups.Setup setup:matched) {
            String note=purchaseNotes.getOrDefault(setup.id,Collections.emptyMap()).get(item.id);
            if(note!=null) notes.add(note);
            String requirement=SetupItemRequirements.reviewReason(setup.id,item.fact);
            if(!requirement.isEmpty()) notes.add(setup.activity+" / "+setup.label+": "+requirement);
        }
        String[] functional=functionalSlot(item);
        if(functional!=null) notes.add(functional[3]);
        String state=ItemVariantState.annotate("Item state",item.fact);
        if(!state.equals("Item state")) notes.add(state);
        String extra=notes.isEmpty()?"":"\n"+String.join("\n",notes);
        boolean inventoryUse=matched.stream().anyMatch(s->SetupLoadout.inventoryTable(s)
            && (s.itemIds.contains(item.id) || InventoryPotionDoses.listed(s.itemIds,item.fact))
            && !ItemVariantState.needsInventoryReview(item.fact,s));
        if(ItemVariantState.needsActivityReview(item.fact) && !inventoryUse)
            return new Rank(0,ItemVariantState.annotate(ItemVariantState.reviewGroup(item.fact),item.fact)+". Purchase state is not a ready-to-use loadout."+extra);
        if(inventoryUse && !ItemVariantState.inventoryUseNote(item.fact).isEmpty())
            extra+="\n"+ItemVariantState.inventoryUseNote(item.fact);
        Set<Integer> tiers=new HashSet<>(); Set<String> roles=new HashSet<>(); List<String> sources=new ArrayList<>();
        for(ActivitySetups.Setup setup:matched) {
            List<Field> fields=RANKS.getOrDefault(setup.id,Collections.emptyMap()).get(item.id);
            if(fields==null) continue;
            for(Field field:fields) {
                int sourceSlot=field.slot.equals("special") || field.slot.equals("2h") ? 3 : slot(field.slot);
                // Wiki's ammo/spell row can contain ingredients or spell links.
                // Those remain searchable, but are not ranked equipment.
                if(item.slot<0 || !fitsSlot(item,sourceSlot) || wantedSlot>=0 && sourceSlot!=wantedSlot) continue;
                boolean reduced=ItemVariantState.needsRankReview(item.fact,setup.activity,setup.label)
                    || !SetupItemRequirements.reviewReason(setup.id,item.fact).isEmpty();
                int value=reduced ? 0 : field.tier;
                tiers.add(value); roles.add(field.slot.equals("special") ? "special attack"
                    :field.slot.equals("ammo")?"ammunition":field.slot.equals("shield")?"shield":"equipment");
                if(sources.size()<3) sources.add(setup.activity+" / "+setup.label+" / "+field.slot+": "+
                    (reduced ? "reduced function; charge-dependent guide rank withheld" : value==0 ? "provisional or ordered choices; review guide" : "Wiki column "+value)+
                    (field.note.isEmpty()?"":". "+field.note));
            }
        }
        int tier=tiers.size()==1 && roles.size()==1 ? tiers.iterator().next() : 0;
        String reason=tiers.isEmpty() ? "Category or example match; no ranked recommendation for this search." :
            tier==0 ? "Ranking differs by setup/role, or needs review. Refine the search or use Legend / Saved views / Guide choices." :
            "Wiki tier "+tier+" for the matching setup(s), not a universal ranking. Requirements and set bonuses still apply.";
        return new Rank(tier,reason+extra+(sources.isEmpty()?"":"\n"+String.join("\n",sources)),roles.size()==1?roles.iterator().next():"");
    }
}

package com.windowmarkers;

import java.awt.*;
import java.awt.event.*;
