        });
        detail.setEditable(false);detail.setLineWrap(true);detail.setWrapStyleWord(true);detail.setRows(7);
        detail.setFont(UIManager.getFont("Label.font"));detail.setBorder(BorderFactory.createEmptyBorder(8,8,8,8));
        JScrollPane itemScroll=new JScrollPane(list),detailScroll=new JScrollPane(detail);
        itemScroll.setMinimumSize(new Dimension(160,100));detailScroll.setMinimumSize(new Dimension(160,80));
        JSplitPane split=new JSplitPane(JSplitPane.VERTICAL_SPLIT,itemScroll,detailScroll);split.setResizeWeight(0.65);split.setBorder(null);
        add(split,BorderLayout.CENTER);
        list.addListSelectionListener(e->{ if(!e.getValueIsAdjusting()) {
            BankItemSearch.Choice choice=list.getSelectedValue();
            detail.setText(choice==null?"Select an item to read its specific uses and evidence.":choice.name+" (#"+choice.id+")\n\n"+reasons.get(choice.id).explanation);
            detail.setCaretPosition(0);
        }});
        search.getDocument().addDocumentListener(new DocumentListener() {
            public void insertUpdate(DocumentEvent e) { filter(); }
            public void removeUpdate(DocumentEvent e) { filter(); }
            public void changedUpdate(DocumentEvent e) { filter(); }
        });
        for(BankItemSearch.Choice choice:choices) if(choice.image instanceof AsyncBufferedImage)
            ((AsyncBufferedImage)choice.image).onLoaded(()->SwingUtilities.invokeLater(()->{ if(!closed) list.repaint(); }));
        filter();
    }
    private String shortReason(BankItemSearch.Choice choice)
    {
        String[] lines=reasons.get(choice.id).explanation.split("\n");
        return lines.length>1 && lines[0].equalsIgnoreCase(choice.name)?lines[1]:lines[0];
    }
    private void filter()
    {
        String query=SearchText.normalize(search.getText());rows.clear();
        for(BankItemSearch.Choice choice:choices) if(reasons.containsKey(choice.id)
            && SearchText.normalize(choice.name+" "+reasons.get(choice.id).explanation).contains(query)) rows.addElement(choice);
        if(!rows.isEmpty()) list.setSelectedIndex(0);
    }
    void close() { closed=true; }
}

package com.windowmarkers;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.*;

/** Factual identities, not an ordering of interchangeable gear. Sources accompany bundled data. */
final class ItemTaxonomy
{
    private static final Map<String,String> WEAPONS=new HashMap<>();
    private static final Map<String,String> SETS=new HashMap<>();
    static
    {
        for (String[] row : readRows("weapon-roles.tsv",2)) { WEAPONS.put(row[0],row[1]); }
        set("Ahrim — magic set (staff required)","ahrim's hood","ahrim's robetop","ahrim's robeskirt","ahrim's staff");
        set("Dharok — melee set (greataxe required)","dharok's helm","dharok's platebody","dharok's platelegs","dharok's greataxe");
        set("Guthan — melee set (warspear required)","guthan's helm","guthan's platebody","guthan's chainskirt","guthan's warspear");
        set("Karil — ranged set (crossbow required)","karil's coif","karil's leathertop","karil's leatherskirt","karil's crossbow");
        set("Torag — melee set (hammers required)","torag's helm","torag's platebody","torag's platelegs","torag's hammers");
        set("Verac — melee set (flail required)","verac's helm","verac's brassard","verac's plateskirt","verac's flail");
        set("Blood Moon — set + dual macuahuitl","blood moon helm","blood moon chestplate","blood moon tassets","dual macuahuitl");
        set("Blue Moon — magic/melee set + spear","blue moon helm","blue moon chestplate","blue moon tassets","blue moon spear");
        set("Eclipse Moon — ranged set + atlatl","eclipse moon helm","eclipse moon chestplate","eclipse moon tassets","eclipse atlatl");
        set("Void — helm, top, robe and gloves","void melee helm","void ranger helm","void mage helm","void knight top","void knight robe","void knight gloves","elite void top","elite void robe");
        set("Inquisitor — crush armour and mace synergy","inquisitor's great helm","inquisitor's hauberk","inquisitor's plateskirt","inquisitor's mace");
        set("Crystal — bow armour synergy","crystal helm","crystal body","crystal legs","crystal bow","bow of faerdhinen");
        set("Justiciar — armour set (no required weapon)","justiciar faceguard","justiciar chestguard","justiciar legguards");
        set("Obsidian — melee armour/weapon synergy","obsidian helmet","obsidian platebody","obsidian platelegs","toktz-xil-ak","toktz-xil-ek","tzhaar-ket-om","tzhaar-ket-em","berserker necklace");
    }
    private static void set(String label,String... names) { for (String n : names) { SETS.put(n,label); } }
    static List<String[]> readRows(String file,int columns)
    {
        List<String[]> result=new ArrayList<>();
        InputStream stream=ItemTaxonomy.class.getResourceAsStream(file);
        if (stream==null) { throw new IllegalStateException("Missing taxonomy resource: "+file); }
        try (BufferedReader reader=new BufferedReader(new InputStreamReader(stream,StandardCharsets.UTF_8)))
        {
            String line;
            while ((line=reader.readLine())!=null)
            {
                if (line.isEmpty() || line.startsWith("#")) { continue; }
                String[] row=line.split("\t",-1);
                if (row.length!=columns) { throw new IllegalStateException("Invalid taxonomy row in "+file); }
                result.add(row);
            }
        }
        catch (IOException e) { throw new IllegalStateException("Cannot read taxonomy: "+file,e); }
        return result;
    }
    static String baseName(String name)
    {
        String n=name.toLowerCase(Locale.ROOT).replace('\u2019','\'').trim();
        // Keep functional (i), (f), poisoned and (a) variants distinct.
        n=n.replaceFirst("\\s*\\([1-4]\\)$","");
        n=n.replaceFirst("\\s+(100|75|50|25|0)$","");
        n=n.replaceFirst("\\s*\\((?:uncharged|empty|inactive|broken|or|l)\\)$","");
        if (n.startsWith("holy sanguinesti staff") || n.startsWith("holy scythe of vitur") || n.startsWith("holy ghrazi rapier")) { n=n.substring(5); }
        if (n.startsWith("sanguine scythe of vitur")) { n=n.substring(9); }
        if (n.startsWith("twisted ancestral ")) { n=n.substring(8); }
        if (n.startsWith("bow of faerdhinen") || n.startsWith("blade of saeldor"))
        { n=n.replaceFirst("\\s*\\(c\\)(?:\\s*\\([a-z]+\\))?$",""); }
        return n.trim();
    }
    static boolean needsRepair(String name) { return name.endsWith(" 0") || name.contains("(broken)"); }
    static boolean needsCharge(String name) { return name.contains("(uncharged)") || name.contains("(empty)") || name.contains("(inactive)"); }
    static String equipmentSet(String n) { return SETS.get(baseName(n)); }
    static Set<String> groups()
    { Set<String> result=new TreeSet<>(SETS.values()); result.addAll(WEAPONS.values()); return result; }
    static String weaponRole(String n)
    {
        String role=WEAPONS.get(n);
        return role!=null ? role : WEAPONS.get(baseName(n));
    }
    static boolean matchesAny(String name,String... expected)
    { for (String n : expected) { if (matches(name,n)) { return true; } } return false; }
    static boolean matches(AutoCategories.Item item,String expected)
    { return matches(ItemVariantState.familyName(item),expected); }
    static boolean matchesAny(AutoCategories.Item item,String... expected)
    { return matchesAny(ItemVariantState.familyName(item),expected); }
    static boolean matches(String name,String expected)
    {
        String n=baseName(name), e=baseName(expected);
        if (n.equals(e)) { return true; }
        switch (e)
        {
            case "god capes": case "imbued god cape": return n.matches("imbued (saradomin|guthix|zamorak) cape");
            case "blessed body": return n.matches("(saradomin|guthix|zamorak|armadyl|bandos|ancient) d'hide body");
            case "blessed chaps": return n.matches("(saradomin|guthix|zamorak|armadyl|bandos|ancient) chaps");
            case "god blessing": return matchesAny(n,"holy blessing","unholy blessing","peaceful blessing","honourable blessing","war blessing","ancient blessing");
            case "ardougne cloak": return n.matches("ardougne cloak [1-4]");
            case "ancient sceptre": return n.matches("(?:blood|ice|smoke|shadow) ancient sceptre");
            case "mystic hat": case "mystic robe top": case "mystic robe bottom":
                return n.matches(java.util.regex.Pattern.quote(e)+" \\((?:light|dark|dusk)\\)");
            default: return false;
        }
    }
}

package com.windowmarkers;

import java.util.HashMap;
import java.util.Locale;
import java.util.Map;

/** Exact identity state is separate from category membership and activity suitability. */
final class ItemVariantState
{
    private enum State { AVAILABLE, REPAIR, CHARGE, EMPTY, REDUCED, CHECK, PREPARE, CONTENTS, RESTRICTED }
    private static final Map<Integer,ItemVariantState> STATES=new HashMap<>();
    private static final Map<Integer,String> UNVERIFIED_IDENTITIES=new HashMap<>();
    private static final Map<Integer,String> UNAVAILABLE_IDENTITIES=new HashMap<>();
    static
    {
        for (String[] row:ItemTaxonomy.readRows("identity-review-required.tsv",2))
        { UNVERIFIED_IDENTITIES.put(Integer.parseInt(row[0]),row[1]); }
        for (String[] row:ItemTaxonomy.readRows("item-availability.tsv",4))
        {
            int id=Integer.parseInt(row[0]);
            if (UNAVAILABLE_IDENTITIES.put(id,row[1].toLowerCase(Locale.ROOT))!=null)
            { throw new IllegalStateException("Duplicate availability ID: "+id); }
        }
        for (String[] row : ItemTaxonomy.readRows("item-variant-states.tsv",5))
        {
            int id=Integer.parseInt(row[0]);
            if (!row[3].equals("true") && !row[3].equals("false"))
            { throw new IllegalStateException("Invalid variant review policy"); }
            if (STATES.put(id,new ItemVariantState(row[1],State.valueOf(row[2]),Boolean.parseBoolean(row[3]),row[4]))!=null)
            { throw new IllegalStateException("Duplicate variant ID: "+id); }
        }
    }
    private final String family;
    private final State state;
    private final boolean activityReview;
    private final String note;

    private ItemVariantState(String family,State state,boolean activityReview,String note)
    { this.family=family; this.state=state; this.activityReview=activityReview; this.note=note; }

    static String familyName(AutoCategories.Item item)
    {
        ItemVariantState known=STATES.get(item.id);
        return known==null ? item.name : known.family;
    }

    static boolean needsActivityReview(AutoCategories.Item item)
    {
        if (identityNeedsReview(item)) { return true; }
        if (WikiCatalogue.hasFacet(item,"restricted")) { return true; }
        ItemVariantState known=STATES.get(item.id);
        return known==null ? ItemTaxonomy.needsRepair(item.name) || ItemTaxonomy.needsCharge(item.name) : known.activityReview;
    }

    static boolean needsActivityReview(AutoCategories.Item item,String role)
    {
        // The inactive Arclight keeps Darklight's special attack. This exception
        // does not grant it the charged weapon's demon-damage role or ranking.
        if (item.id==30305 && role.startsWith("Special attacks")) { return false; }
        return needsActivityReview(item);
    }

    static boolean needsInventoryReview(AutoCategories.Item item,ActivitySetups.Setup setup)
    {
        // These exact utility identities keep their charges/contents outside
        // the item ID. Show ownership without claiming their contents are ready.
        if(setup.itemIds.contains(item.id) && inventoryOwnershipOnly(item)
            && !identityNeedsReview(item) && !WikiCatalogue.hasFacet(item,"restricted")) return false;
        // A reviewed inventory can deliberately use a restricted supply. A
        // self-damage warning is not evidence that an owned potion is unavailable.
        // Keep identity, state and unrelated location restrictions separate.
        if(!identityNeedsReview(item) && (setup.itemIds.contains(item.id) || InventoryPotionDoses.listed(setup.itemIds,item))
            && (item.name.startsWith("blighted ") && WikiCatalogue.hasFacet(item,"restricted")
                || WikiCatalogue.entries(item).stream().anyMatch(e->e.group.equals("Self-damaging items — deliberate use"))
                    && WikiCatalogue.entries(item).stream().filter(e->e.facet.equals("restricted"))
                        .allMatch(e->e.group.equals("Self-damaging items — deliberate use")))
            && !STATES.containsKey(item.id)) return false;
        return needsActivityReview(item);
    }

    static boolean inventoryOwnershipOnly(AutoCategories.Item item)
    {
        ItemVariantState state=STATES.get(item.id);
        return state!=null && state.family.equals(item.name)
            && (item.id==25781 || item.id==13116 || item.id==19634 || item.id==21389)
            && (state.state==State.CHECK || state.state==State.CONTENTS);
    }

    static String inventoryUseNote(AutoCategories.Item item)
    {
        if(inventoryOwnershipOnly(item))
            return "Owned guide item; its ID does not establish remaining charges, stored contents or toggle state. Check before use.";
        if(WikiCatalogue.entries(item).stream().anyMatch(e->e.group.equals("Self-damaging items — deliberate use")))
            return "Deliberate self-damaging supply listed by this guide. Check remaining Hitpoints and use requirements.";
        if(item.name.startsWith("blighted "))
            return "Restricted-use blighted supply listed by this activity's inventory guide.";
        return "";
    }

    static boolean canRepresentOwnedEquivalent(AutoCategories.Item held,AutoCategories.Item candidate)
    {
        if(needsActivityReview(held)) return false;
        ItemVariantState owned=STATES.get(held.id),wanted=STATES.get(candidate.id);
        // Equal combat stats do not make the ordinary trident a 20,000-charge
        // enhanced model. Preserve that separate purchase option.
        if(wanted!=null && wanted.family.startsWith("trident of the ")
            && candidate.name.contains("(e)") && !held.name.contains("(e)")) return false;
        // Retained base stats do not establish the charged version's teleports,
        // recoil or gathering benefits. Exact ownership is handled separately.
        return owned==null || owned.state!=State.REDUCED
            || wanted!=null && wanted.state==State.REDUCED;
    }

    static boolean needsRankReview(AutoCategories.Item item,String activity,String setup)
    {
        ItemVariantState known=STATES.get(item.id);
        if(known==null || known.state!=State.REDUCED) return false;
        // These tools remain usable at dragon tier. Do not copy a charged
        // tool's guide rank when its processing or gathering effect is gone.
        if(known.note.startsWith("dragon")) {
            if(known.family.equals("infernal axe") && activity.equals("Wintertodt")) return false;
            if(known.family.endsWith("pickaxe") && activity.startsWith("Chambers of Xeric")
                && setup.startsWith("Guardians")) return false;
            return true;
        }
        // A passive bonus is not proof that a guide's additional charge-based
        // benefit is available. Keep these items searchable with state notes.
        if(known.family.startsWith("celestial ")) return !activity.equals("Tempoross");
        if(known.family.startsWith("ring of suffering")) return activity.equals("Zulrah") || activity.equals("Kalphite Queen");
        if(known.family.startsWith("amulet of glory")) return activity.equals("Mining");
        return known.family.equals("horn of plenty");
    }

    static String reviewGroup(AutoCategories.Item item)
    {
        if (item.name.equals(UNAVAILABLE_IDENTITIES.get(item.id))) { return "Unavailable item identity — review"; }
        if (identityNeedsReview(item)) { return "Unverified item identity — review"; }
        if (WikiCatalogue.hasFacet(item,"restricted")) { return "Activity restrictions — review"; }
        ItemVariantState known=STATES.get(item.id);
        if (known!=null && known.state==State.CHECK)
        { return known.note.contains("charge") ? "Check charges — review" : "Check item use — review"; }
        if (known!=null && known.state==State.REDUCED) { return "Reduced function — review"; }
        if (known!=null && known.state==State.PREPARE) { return "Preparation needed — review"; }
        if (known!=null && known.state==State.CONTENTS) { return "Check contents — review"; }
        if (known!=null && known.state==State.EMPTY) { return "Empty — review"; }
        if (known!=null && known.state==State.RESTRICTED) { return "Activity restrictions — review"; }
        return "Needs repair/charge — review";
    }

    static String annotate(String group,AutoCategories.Item item)
    {
        if (group==null) { return null; }
        ItemVariantState known=STATES.get(item.id);
        // Keep the item's factual category, but do not mix depleted and usable states.
        if (known!=null && !known.note.isEmpty()) { return group+" ("+known.note+")"; }
        return group;
    }

    static boolean identityNeedsReview(AutoCategories.Item item)
    {
        // Same-name interface models and unavailable quest/test copies must not
        // inherit the real inventory item's effects or activity recommendations.
        return item.name.equals(UNVERIFIED_IDENTITIES.get(item.id))
            || item.name.equals(UNAVAILABLE_IDENTITIES.get(item.id));
    }
}

package com.windowmarkers;

import java.awt.*;
import java.awt.geom.Area;
import java.util.*;
import java.util.List;

/** Union outlines preserve holes and L-shaped groups without drawing internal seams. */
final class JoinedItemBorders
{
    private final Map<List<Rectangle>,Shape> shapes=new LinkedHashMap<List<Rectangle>,Shape>(16,0.75f,true) {
        @Override protected boolean removeEldestEntry(Map.Entry<List<Rectangle>,Shape> entry) { return size()>32; }
    };
    void clear() { shapes.clear(); }
    Shape outline(List<Rectangle> regions) {
        Shape shape=shapes.get(regions);
        if(shape!=null) return shape;
        List<Rectangle> key=new ArrayList<>();Area area=new Area();
        for(Rectangle region:regions) if(region!=null && !region.isEmpty()) {
            Rectangle copy=new Rectangle(region);key.add(copy);area.add(new Area(copy));
        }
        shapes.put(key,area);return area;
    }
    void draw(Graphics2D g,List<Rectangle> regions,Color colour) {
        g.setColor(colour);g.draw(outline(regions));
    }
    static Map<Color,List<Rectangle>> groups(List<ItemAnchors.Cell> cells,int[] highlighted,
        Map<Integer,ItemCatalogueIndex.Rank> ranks,WindowMarkersConfig config)
    {
        Set<Integer> owned=new HashSet<>();for(int id:highlighted) owned.add(id);
        Map<Color,List<Rectangle>> result=new LinkedHashMap<>();
        for(ItemAnchors.Cell cell:cells) {
            ItemCatalogueIndex.Rank rank=ranks.get(cell.id);
            if(rank!=null && BankCleanup.isReview(rank)) continue;
            Color colour=rank!=null && config.geTierColours() && rank.tier>=1 && rank.tier<=3
                ?TierPresentation.colour(config,rank.tier):owned.contains(cell.id)?Color.YELLOW:null;
            if(colour!=null) result.computeIfAbsent(colour,key->new ArrayList<>()).add(cell.grid);
        }
        return result;
    }
}

package com.windowmarkers;

import java.util.LinkedHashMap;
import java.util.Map;

final class LayoutCatalog
{
    String active="default";
    Map<String,String> names=new LinkedHashMap<>();
    LayoutCatalog() { names.put("default","Default"); }
    void normalize()
    {
        if (names==null) { names=new LinkedHashMap<>(); }
        names.entrySet().removeIf(e -> e.getKey()==null || !e.getKey().matches("default|[a-f0-9-]{36}") || e.getValue()==null);
        names.putIfAbsent("default","Default");
        if (!names.containsKey(active)) { active="default"; }
    }
    String storageKey(String base) { return "default".equals(active) ? base : base+"_layout_"+active; }
}

package com.windowmarkers;

import java.awt.Rectangle;
import java.util.Arrays;
import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Map;

/** Shares linked geometry between background, border and hover passes of one frame. */
final class LinkedMarkerRegions
{
    private final Map<Marker, Entry> entries = new IdentityHashMap<>();

    void clear() { entries.clear(); }

    // The caller clears after taking each fresh item-bounds snapshot and on context changes.
    // Returned rectangles are read-only to callers; placement/label passes must copy before editing.
    List<Rectangle> get(Marker marker, List<ItemAnchors.Cell> cells)
    {
        Entry entry = entries.get(marker);
        // Mouse/Swing edits can arrive between render passes. Check membership by value as well.
        if (entry == null || entry.cells != cells || !Arrays.equals(entry.ids, marker.linkedItemIds))
        {
            int[] ids = marker.linkedItemIds == null ? new int[0] : marker.linkedItemIds.clone();
            entry = new Entry(cells, ids, Collections.unmodifiableList(ItemAnchors.regions(ids, cells)));
            entries.put(marker, entry);
        }
        return entry.regions;
    }

    private static final class Entry
    {
        final List<ItemAnchors.Cell> cells;
        final int[] ids;
        final List<Rectangle> regions;
        Entry(List<ItemAnchors.Cell> cells, int[] ids, List<Rectangle> regions)
        { this.cells = cells; this.ids = ids; this.regions = regions; }
    }
}

package com.windowmarkers;

import java.util.*;

/** Only verified like-for-like tool tiers. Never treats all expensive gear as superior. */
final class LowerTierFilter
{
    private static final String[] METALS={"bronze","iron","steel","black","mithril","adamant","rune","dragon"};
    private static final int[] LEVELS={1,1,6,11,21,31,41,61};

    static Map<Integer,String> exclusions(List<AutoCategories.Item> bank,int mining,int woodcutting,int fishing)
    {
        Map<Integer,String> result=new LinkedHashMap<>();
        tools(bank,result,"pickaxe",mining);
        tools(bank,result,"axe",woodcutting);
        // Harpoon alternatives have distinct wieldability/processing uses; preserve them.
        return result;
    }
    private static void tools(List<AutoCategories.Item> bank,Map<Integer,String> result,String type,int skill)
    {
        AutoCategories.Item better=null; int best=-1;
        for (AutoCategories.Item i : bank)
        {
            int tier=tier(i.name,type);
            if (tier>best && LEVELS[tier]<=skill && usable(i.name) && !ItemVariantState.needsActivityReview(i)) { best=tier; better=i; }
        }
        if (better==null) { return; }
        for (AutoCategories.Item i : bank)
        {
            int tier=tier(i.name,type);
            if (tier<0 || tier>=best || !usable(i.name) || ItemVariantState.needsActivityReview(i)) { continue; }
            // Its exceptionally low weight remains useful for Abyss runecrafting.
            if (i.name.equals("black pickaxe")) { continue; }
            // A tool can also be required by a clue/quest. Preserve that verified separate use.
            if (WikiCatalogue.hasFacet(i,"clue") || WikiCatalogue.hasFacet(i,"quest")) { continue; }
            result.put(i.id,i.name+" → "+better.name+" (usable "+type+" tier; special-use items retained)");
        }
    }
    private static boolean usable(String name)
    { return !ItemTaxonomy.needsRepair(name) && !ItemTaxonomy.needsCharge(name); }
    private static int tier(String name,String type)
    {
        // Exact names intentionally preserve ornamented, gilded, crystal, infernal, felling and quest tools.
        for (int i=0;i<METALS.length;i++) { if (name.equals(METALS[i]+" "+type)) { return i; } }
        return -1;
    }
}

