import java.awt.Point;
import java.awt.Rectangle;

final class Marker
{
    int x, y, width, height;
    String label;
    String category, preset;
    String guideQuery, guideContext, inventoryContext;
    String rankKey() { return (guideQuery==null?"":guideQuery)+"\n"+(guideContext==null?"":guideContext); }
    void clearGuide() { guideQuery=null; guideContext=null; inventoryContext=null; }
    Integer borderArgb;
    Integer backgroundArgb;
    WindowMarkersConfig.BorderStyle style;
    Boolean scrollWithItems;
    Integer labelArgb;
    Integer labelSize;
    String labelFont;
    enum LabelPlacement
    {
        INSIDE("Inside"), ABOVE("Above"), BELOW("Below");
        private final String label;
        LabelPlacement(String label) { this.label=label; }
        @Override public String toString() { return label; }
    }
    LabelPlacement labelPlacement;
    Boolean labelOnce;
    int[] linkedItemIds;
    boolean linked() { return linkedItemIds != null && linkedItemIds.length > 0; }

    int fontSize() { return labelSize == null ? 16 : Math.max(8,Math.min(48,labelSize)); }

    Rectangle onScreen(Rectangle bank, Rectangle items, int scrollY)
    {
        if (Boolean.TRUE.equals(scrollWithItems))
        {
            return items == null ? null : new Rectangle(items.x+x,items.y+y-scrollY,width,height);
        }
        return onScreen(bank);
    }

    void anchorLegacy(Rectangle bank, Rectangle items)
    {
        if (scrollWithItems != null) { return; }
        Rectangle old=onScreen(bank);
        scrollWithItems=items.contains(old.getLocation());
        if (scrollWithItems) { x=old.x-items.x; y=old.y-items.y; }
    }

    String labelText() { return label == null ? "" : label.replaceAll("[\\p{Cntrl}]", " ").substring(0, Math.min(60, label.length())); }

    Marker(int x, int y, int width, int height)
    {
        this.x = x; this.y = y; this.width = width; this.height = height;
    }

    boolean valid()
    {
        return x >= 0 && y >= 0 && width >= 16 && height >= 16
            && x <= 10000 && y <= 10000 && width <= 10000 && height <= 10000;
    }

    Rectangle onScreen(Rectangle bank)
    {
        return new Rectangle(bank.x + x, bank.y + y, width, height);
    }

    static Marker drag(Point start, Point end, Rectangle bank)
    {
        int ex = Math.max(bank.x, Math.min(bank.x + bank.width, end.x));
        int ey = Math.max(bank.y, Math.min(bank.y + bank.height, end.y));
        return new Marker(Math.min(start.x, ex) - bank.x, Math.min(start.y, ey) - bank.y,
            Math.abs(start.x - ex), Math.abs(start.y - ey));
    }
}

package com.windowmarkers;

import java.awt.*;
import java.awt.event.KeyEvent;
import javax.swing.*;

/** Scroll only the form; keep confirmation controls outside its viewport. */
final class MarkerDialogs
{
    static Color chooseColor(Component parent,String title,Color initial)
    {
        JColorChooser chooser=new JColorChooser(initial);
        return confirm(parent,chooser,title,700,540) ? chooser.getColor() : null;
    }
    static boolean confirm(Component parent,JComponent content,String title,int width,int height)
    { return confirm(parent,content,title,width,height,"OK",()->true); }
    static boolean confirm(Component parent,JComponent content,String title,int width,int height,String action,java.util.function.BooleanSupplier valid)
    { return open(parent,content,title,width,height,action,valid,true); }
    static void show(Component parent,JComponent content,String title,int width,int height)
    { open(parent,content,title,width,height,"Close",()->true,false); }
    private static boolean open(Component parent,JComponent content,String title,int width,int height,String action,java.util.function.BooleanSupplier valid,boolean cancellable)
    {
        Window owner=parent==null ? null : SwingUtilities.getWindowAncestor(parent);
        JDialog dialog=new JDialog(owner,title,Dialog.ModalityType.APPLICATION_MODAL);
        boolean[] accepted={false};
        JButton ok=new JButton(action),cancel=new JButton("Cancel");
        ok.addActionListener(e -> { if(valid.getAsBoolean()) { accepted[0]=true; dialog.dispose(); } });
        cancel.addActionListener(e -> dialog.dispose());
        JPanel buttons=new JPanel(new FlowLayout(FlowLayout.RIGHT,8,0));
        buttons.add(ok); if(cancellable) buttons.add(cancel);
        JScrollPane scroll=new JScrollPane(content,JScrollPane.VERTICAL_SCROLLBAR_AS_NEEDED,JScrollPane.HORIZONTAL_SCROLLBAR_AS_NEEDED);
        scroll.getVerticalScrollBar().setUnitIncrement(20);
        scroll.setMinimumSize(new Dimension(0,0));
        JPanel root=new JPanel(new BorderLayout(0,10));
        root.setBorder(BorderFactory.createEmptyBorder(12,12,12,12));
        root.add(scroll,BorderLayout.CENTER); root.add(buttons,BorderLayout.SOUTH);
        dialog.setContentPane(root);
        dialog.setDefaultCloseOperation(WindowConstants.DISPOSE_ON_CLOSE);
        dialog.setResizable(true);
        dialog.getRootPane().setDefaultButton(ok);
        dialog.getRootPane().registerKeyboardAction(e -> dialog.dispose(),KeyStroke.getKeyStroke(KeyEvent.VK_ESCAPE,0),JComponent.WHEN_IN_FOCUSED_WINDOW);
        GraphicsConfiguration configuration=owner==null ? dialog.getGraphicsConfiguration() : owner.getGraphicsConfiguration();
        Rectangle screen=configuration.getBounds();
        Insets insets=Toolkit.getDefaultToolkit().getScreenInsets(configuration);
        Rectangle usable=new Rectangle(screen.x+insets.left,screen.y+insets.top,
            screen.width-insets.left-insets.right,screen.height-insets.top-insets.bottom);
        Rectangle bounds=initialBounds(usable,width,height);
        dialog.setMinimumSize(new Dimension(Math.min(320,bounds.width),Math.min(200,bounds.height)));
        dialog.setBounds(bounds);
        try { dialog.setVisible(true); return accepted[0]; }
        finally { dialog.dispose(); }
    }
    static Rectangle initialBounds(Rectangle screen,int width,int height)
    {
        int w=Math.min(width,Math.max(1,screen.width-24)),h=Math.min(height,Math.max(1,screen.height-24));
        return new Rectangle(screen.x+(screen.width-w)/2,screen.y+(screen.height-h)/2,w,h);
    }
}

package com.windowmarkers;

import java.awt.*;
import javax.swing.*;
import javax.swing.plaf.basic.BasicHTML;
import javax.swing.text.View;

/** A width-constrained column: natural control heights and wrapping text. */
final class MarkerForm extends JPanel implements Scrollable
{
    MarkerForm() { super(null); }

    private int height(Component child, int width)
    {
        if (child instanceof JTextArea)
        {
            child.setSize(width, Short.MAX_VALUE);
        }
        if (child instanceof JLabel)
        {
            View html=(View)((JLabel)child).getClientProperty(BasicHTML.propertyKey);
            if (html!=null)
            {
                html.setSize(width,0);
                return (int)Math.ceil(html.getPreferredSpan(View.Y_AXIS));
            }
        }
        return child.getPreferredSize().height;
    }

    @Override public Dimension getPreferredSize()
    {
        Insets in=getInsets();
        int width=getWidth()>0 ? getWidth() : 420;
        int y=in.top;
        for(Component child:getComponents()) if(child.isVisible())
        { y+=height(child,Math.max(1,width-in.left-in.right))+4; }
        return new Dimension(width,y+in.bottom);
    }

    @Override public void doLayout()
    {
        Insets in=getInsets(); int y=in.top, width=Math.max(1,getWidth()-in.left-in.right);
        for(Component child:getComponents()) if(child.isVisible())
        {
            int h=height(child,width); child.setBounds(in.left,y,width,h); y+=h+4;
        }
    }
    @Override public Dimension getMinimumSize() { return new Dimension(0,0); }
    @Override public Dimension getPreferredScrollableViewportSize() { return getPreferredSize(); }
    @Override public boolean getScrollableTracksViewportWidth() { return true; }
    @Override public boolean getScrollableTracksViewportHeight() { return false; }
    @Override public int getScrollableUnitIncrement(Rectangle r,int axis,int direction) { return 20; }
    @Override public int getScrollableBlockIncrement(Rectangle r,int axis,int direction) { return Math.max(20,r.height-20); }
}

package com.windowmarkers;

import java.util.ArrayDeque;
import java.util.Deque;

final class MarkerHistory
{
    private String current;
    private final Deque<String> undo=new ArrayDeque<>(), redo=new ArrayDeque<>();
    void reset(String value) { current=value; undo.clear(); redo.clear(); }
    void record(String value)
    {
        if (value.equals(current)) { return; }
        if (current != null) { undo.addLast(current); if (undo.size()>50) { undo.removeFirst(); } }
        current=value; redo.clear();
    }
    String undo()
    {
        if (undo.isEmpty()) { return null; }
        redo.addLast(current); current=undo.removeLast(); return current;
    }
    String redo()
    {
        if (redo.isEmpty()) { return null; }
        undo.addLast(current); current=redo.removeLast(); return current;
    }
    boolean matches(String value) { return value.equals(current); }
}

package com.windowmarkers;

import java.awt.Rectangle;
import java.util.*;

/** Avoid repeating free-space searches while the bank and its labels are stationary. */
final class MarkerLabelCache
{
    private List<Rectangle> previousItems=Collections.emptyList();
    private final List<Request> previous=new ArrayList<>();
    private int cursor;

    void begin(List<Rectangle> items)
    {
        if(!previousItems.equals(items)) {
            previousItems=copy(items); previous.clear();
        }
        cursor=0;
    }

    Rectangle place(Rectangle region,Rectangle clip,int width,int height,Marker.LabelPlacement preference,List<Rectangle> occupied)
    {
        Request request=new Request(region,clip,width,height,preference);
        if(cursor<previous.size() && previous.get(cursor).same(request)) {
            Rectangle result=previous.get(cursor++).result;
            if(result!=null) occupied.add(new Rectangle(result));
            return result;
        }
        // A changed/removed earlier label changes the free space for every later label.
        while(previous.size()>cursor) previous.remove(previous.size()-1);
        request.result=MarkerPresentation.place(region,clip,width,height,preference,occupied);
        previous.add(request);cursor++;return request.result;
    }

    private static List<Rectangle> copy(List<Rectangle> source)
    { List<Rectangle> result=new ArrayList<>();for(Rectangle r:source) result.add(new Rectangle(r));return result; }

    private static final class Request
    {
        final Rectangle region,clip;
        final int width,height;
        final Marker.LabelPlacement preference;
        Rectangle result;
        Request(Rectangle region,Rectangle clip,int width,int height,Marker.LabelPlacement preference)
        { this.region=new Rectangle(region);this.clip=new Rectangle(clip);this.width=width;this.height=height;this.preference=preference; }
        boolean same(Request other)
        { return region.equals(other.region)&&clip.equals(other.clip)&&width==other.width&&height==other.height&&preference==other.preference; }
    }
}

