                headings.add(new Heading(title+(section.notEnoughGear()?" - not enough gear in bank":""),51,y+12));y+=18;
            }
            y=placeSection(container,manager,columns,pitch,y,section,byId,placed,headings,copies,notes,shownInventories.add(section.inventoryExample),runes);
            runes=Collections.emptyList();
        }
        Map<String,List<Widget>> extras=new TreeMap<>();
        for(Widget cell:cells) if(!placed.contains(cell)) {
            int id=manager.canonicalize(cell.getItemId()),bucket=bucket(id,manager,plan.activity);
            var definition=manager.getItemComposition(id);
            Set<String> roles=definition==null?Collections.emptySet():RaidRecommendations.layoutGroups(plan.activity,
                new AutoCategories.Item(id,definition.getName(),bucket<11,definition.getInventoryActions(),0,0,0));
            if(roles.isEmpty()) extras.computeIfAbsent(String.format(Locale.ROOT,"%02d:%s",bucket,BUCKET_NAMES[Math.min(19,bucket)]),k->new ArrayList<>()).add(cell);
            else for(String role:roles) extras.computeIfAbsent("11:"+role,k->new ArrayList<>()).add(cell);
        }
        for(var entry:extras.entrySet()) {
            List<Widget> group=entry.getValue();
            group.sort(Comparator.comparingInt((Widget cell)-> {
                var rank=ranks.get(manager.canonicalize(cell.getItemId()));return rank==null || rank.tier<=0?Integer.MAX_VALUE:rank.tier;
            }).thenComparingInt(Widget::getItemId));
            String heading=entry.getKey().substring(3);
            headings.add(new Heading(heading,51,y+12));y+=18;
            String roomNote=RaidRecommendations.roomNote(plan.activity,heading);
            for(int i=0;i<group.size();i++) {
                Widget cell=group.get(i);
                if(!placed.add(cell)) {
                    if(copies==null) continue;
                    cell=copies.add(container,cell,cell.getItemId(),manager);
                }
                place(cell,51+(i%columns)*pitch,y+(i/columns)*36);
                if(!roomNote.isEmpty()) notes.add(new InventoryNote(roomNote,51+(i%columns)*pitch,y+(i/columns)*36));
            }
            y+=((group.size()+columns-1)/columns)*36+8;
        }
        return new int[]{oldEnd,y};
    }
    private static int placeSection(Widget container,ItemManager manager,int columns,int pitch,int padding,SetupLoadout plan,
        Map<Integer,Widget> byId,Set<Widget> placed,List<Heading> headings,SetupInventoryWidgets copies,List<InventoryNote> notes,boolean showInventory,List<Widget> runes)
    {
        Map<Integer,Widget> chosen=new HashMap<>();
        for(var entry:plan.equipment.entrySet()) for(int id:entry.getValue()) if(byId.containsKey(id)) { chosen.put(entry.getKey(),byId.get(id));break; }
        // A missing weapon's budget example may need different ammunition than
        // the prayer-slot filler chosen while there was no owned weapon.
        if(plan.equipmentExample.containsKey(13)) {
            chosen.remove(13);
            Widget ammo=byId.get(plan.equipmentExample.get(13));if(ammo!=null) chosen.put(13,ammo);
        }
        // Void's benefit requires the whole outfit. Do not mix a partial Void
        // selection into an otherwise ordinary equipment diagram.
        boolean fullVoid=true;
        for(int slot:new int[]{0,4,7,9}) if(!isVoid(chosen.get(slot),manager)) fullVoid=false;
        if(!fullVoid) for(int slot:new int[]{0,4,7,9}) if(isVoid(chosen.get(slot),manager)) {
            chosen.remove(slot);
            for(int id:plan.equipment.getOrDefault(slot,Collections.emptyList())) if(byId.containsKey(id) && !isVoid(byId.get(id),manager)) { chosen.put(slot,byId.get(id));break; }
        }
        Widget weapon=chosen.get(3);
        boolean twoHanded=false;
        Integer exampleWeapon=plan.equipmentExample.get(3);
        if(weapon!=null || exampleWeapon!=null) {
            var stats=manager.getItemStats(weapon==null?exampleWeapon:manager.canonicalize(weapon.getItemId()));
            if(stats!=null && stats.getEquipment()!=null && stats.getEquipment().isTwoHanded()) { chosen.remove(5);twoHanded=true; }
        }
        boolean showEquipment=!plan.equipmentName.isEmpty();
        int gearY=padding+18,gearEnd=showEquipment?gearY+5*36:gearY;
        int runeColumns=Math.min(columns,3),runeY=gearEnd+18;
        if(!runes.isEmpty()) gearEnd=runeY+((runes.size()+runeColumns-1)/runeColumns)*36;
        int inventoryY=showEquipment && columns<8 || !showEquipment && !runes.isEmpty()?gearEnd+18:gearY;
        int inventoryX=51+(showEquipment && columns>=8?4*pitch:0);
        if(showEquipment) headings.add(new Heading("Equipment",51,padding+12));
        headings.add(new Heading(plan.inventoryExample.isEmpty()?"No Wiki inventory example":showInventory?"Recommended inventory":"Shared inventory above",inventoryX,inventoryY-6));
        for(int[] position:EQUIPMENT) {
            Widget cell=chosen.get(position[0]);
            int col=position[1]%columns,row=position[2]+position[1]/columns;
            int x=51+col*pitch,y=gearY+row*36;
            if(cell!=null) {
                String note=plan.equipmentNotes.getOrDefault(manager.canonicalize(cell.getItemId()),"");
                if(!placed.add(cell)) {
                    if(copies==null) continue;
                    cell=copies.add(container,cell,cell.getItemId(),manager);
                }
                place(cell,x,y);
                if(!note.isEmpty()) notes.add(new InventoryNote(note,x,y));
            } else if(showEquipment) {
                boolean offhand=position[0]==5 && twoHanded;
                Integer example=offhand?null:plan.equipmentExample.get(position[0]);
                String label=offhand?"2H":slotLabel(position[0]);
                if(example!=null && copies!=null) {
                    place(copies.add(container,null,example,manager),x,y);
                    notes.add(new InventoryNote("Budget gear suggestion: no matching usable item selected from your bank. Check equip requirements; this is not owned stock or a new guide rank.",x,y));
                } else {
                    headings.add(new Heading(label,x,y,true));
                    notes.add(new InventoryNote(offhand?"Off-hand unavailable with the selected two-handed weapon.":"No suitable ready owned item for "+label.toLowerCase(Locale.ROOT)+". Check ownership, charges and setup requirements.",x,y));
                }
            }
        }
        if(!runes.isEmpty()) {
            headings.add(new Heading("Suggested runes",51,runeY-6));
            for(int i=0;i<runes.size();i++) {
                Widget rune=runes.get(i);
                if(!placed.add(rune)) { if(copies==null) continue;rune=copies.add(container,rune,rune.getItemId(),manager); }
                int x=51+i%runeColumns*pitch,y=runeY+i/runeColumns*36;
                place(rune,x,y);
                notes.add(new InventoryNote("Runes listed for this activity. Choose those needed for your spellbook, spell and rune pouch; this is not a required combined rune loadout.",x,y));
            }
        }
        int inventoryColumns=Math.min(4,columns),inventoryEnd=inventoryY;
        for(var entry:plan.inventoryExample.entrySet()) {
            if(!showInventory) break;
            Integer id=plan.inventory.get(entry.getKey());
            Widget source=id==null?null:byId.get(id),cell=source;
            if(source==null || !placed.add(source)) {
                if(copies==null) continue;
                cell=copies.add(container,source,entry.getValue().ids.get(0),manager);
            }
            int position=entry.getKey(),x=inventoryX+(position%inventoryColumns)*pitch;
            int y=inventoryY+(position/inventoryColumns)*36;
            place(cell,x,y);inventoryEnd=Math.max(inventoryEnd,y+36);
            String note=entry.getValue().note;
            if(id!=null && !entry.getValue().ids.contains(id))
                note=InventoryPotionDoses.known(id)?InventoryPotionDoses.note(id):SetupEquipmentChoice.inventoryAlternativeNote(entry.getValue().ids);
            if(source==null) {
                if(!entry.getValue().guideOnly) note="Guide example: no ready bank item for this slot. Check ownership, charges and requirements."+(note.isEmpty()?"":" "+note);
            }
            else if(!note.isEmpty()) note="Showing an owned alternative; live prices are not compared. "+note;
            if(source!=null) {
                var definition=manager.getItemComposition(id);
                if(definition!=null) {
                    String state=ItemVariantState.annotate("Item state",new AutoCategories.Item(id,definition.getName(),false,
                        definition.getInventoryActions(),0,0,0));
                    if(!state.equals("Item state")) note+=(note.isEmpty()?"":" ")+state;
                    String use=ItemVariantState.inventoryUseNote(new AutoCategories.Item(id,definition.getName(),false,
                        definition.getInventoryActions(),0,0,0));
                    if(!use.isEmpty()) note+=(note.isEmpty()?"":" ")+use;
                }
            }
            if(!note.isEmpty()) notes.add(new InventoryNote(note,x,y));
        }
        return Math.max(gearEnd,inventoryEnd)+8;
    }
    private static String slotLabel(int slot) {
        switch(slot) {
            case 0:return "Head";case 1:return "Cape";case 2:return "Neck";case 3:return "Main";
            case 4:return "Body";case 5:return "Off";case 7:return "Legs";case 9:return "Hands";
            case 10:return "Feet";case 12:return "Ring";default:return "Ammo";
        }
    }
    private static boolean isVoid(Widget widget,ItemManager manager) {
        if(widget==null) return false;
        var definition=manager.getItemComposition(manager.canonicalize(widget.getItemId()));
        return definition!=null && definition.getName()!=null && definition.getName().toLowerCase(Locale.ROOT).contains("void");
    }
    private static void place(Widget cell,int x,int y) { cell.setOriginalX(x);cell.setOriginalY(y);cell.revalidate(); }

    static boolean activityPreset(AutoCategories.Preset preset)
    {
        return preset==AutoCategories.Preset.SKILLING || preset==AutoCategories.Preset.SKILLING_OUTFITS
            || preset==AutoCategories.Preset.COMBAT_GROUPS || preset==AutoCategories.Preset.CHAMBERS_OF_XERIC
            || preset==AutoCategories.Preset.THEATRE_OF_BLOOD || preset==AutoCategories.Preset.TOMBS_OF_AMASCUT
            || preset==AutoCategories.Preset.WIKI_ACTIVITY_SETUP;
    }

    static int bucket(int id,ItemManager manager)
    { return bucket(id,manager,""); }
    private static int bucket(int id,ItemManager manager,String activity)
    {
        var definition=manager.getItemComposition(id);
        if(definition==null) return 19;
        var stats=manager.getItemStats(id);
        String name=definition.getName();
        AutoCategories.Item item=new AutoCategories.Item(id,name,stats!=null && stats.isEquipable(),definition.getInventoryActions(),0,0,0);
        boolean reviewedSupply=!activity.isEmpty() && ActivitySetups.forActivity(activity).stream().anyMatch(s->
            SetupLoadout.inventoryTable(s) && (s.itemIds.contains(id) || InventoryPotionDoses.listed(s.itemIds,item))
                && !ItemVariantState.needsInventoryReview(item,s) && SetupItemRequirements.reviewReason(s.id,item).isEmpty());
        if(ItemVariantState.needsActivityReview(item) && !reviewedSupply) return 19;
        if("Tools".equals(ItemTaxonomy.weaponRole(ItemVariantState.familyName(item)))
            || WikiCatalogue.entries(item).stream().anyMatch(e -> e.group.equals("Shared tools") || e.group.endsWith("— tools"))) return 11;
        if(stats!=null && stats.getEquipment()!=null) {
            int slot=stats.getEquipment().getSlot();
            for(int i=0;i<SLOTS.length;i++) if(SLOTS[i]==slot) return i;
        }
        if(item.action("Eat")) return 12;
        if(item.action("Drink")) return 13;
        if(item.name.endsWith(" rune")) return 14;
        return 15;
    }

    static int[] apply(Widget container,ItemManager manager,int columns,int pitch,int padding)
    {
        Widget[] children=container.getDynamicChildren();
        if(children==null || manager==null) return null;
        List<Widget> cells=new ArrayList<>();
        for(Widget child:children) if(child!=null && !child.isSelfHidden() && child.getItemId()>=0
            && child.getItemId()!=6512 && child.getOriginalWidth()==36 && child.getOriginalHeight()==32) cells.add(child);
        if(cells.isEmpty()) return null;
        cells.sort(Comparator.comparingInt(Widget::getOriginalY).thenComparingInt(Widget::getOriginalX));
        Map<Integer,List<Widget>> groups=new TreeMap<>();
        int oldEnd=0;
        Map<Integer,Integer> buckets=new HashMap<>();
        for(Widget cell:cells) {
            oldEnd=Math.max(oldEnd,cell.getOriginalY()+36);
            int id=manager.canonicalize(cell.getItemId());
            groups.computeIfAbsent(buckets.computeIfAbsent(id,k -> bucket(k,manager)),k -> new ArrayList<>()).add(cell);
        }
        int y=padding;
        for(List<Widget> group:groups.values()) {
            for(int i=0;i<group.size();i++) {
                Widget cell=group.get(i);
                cell.setOriginalX(51+(i%columns)*pitch);
                cell.setOriginalY(y+(i/columns)*36);
                cell.revalidate();
            }
            y+=((group.size()+columns-1)/columns)*36;
        }
        return new int[]{oldEnd,y};
    }
}

package com.windowmarkers;

import java.util.*;

/** Role-specific state restrictions; these do not remove an item's other uses. */
final class SetupItemRequirements
{
    private static final Map<String,Map<Integer,String[]>> REQUIREMENTS=new HashMap<>();
    static
    {
        for (String[] row:ItemTaxonomy.readRows("setup-item-requirements.tsv",5))
            REQUIREMENTS.computeIfAbsent(row[0],key->new HashMap<>()).put(Integer.parseInt(row[1]),row);
    }

    static String reviewReason(String setupId,AutoCategories.Item item)
    {
        String[] row=REQUIREMENTS.getOrDefault(setupId,Collections.emptyMap()).get(item.id);
        return row!=null && row[2].equalsIgnoreCase(item.name) ? row[3] : "";
    }
}

package com.windowmarkers;

import java.util.*;

/** An activity contains separate source loadouts; inventories are never unioned. */
final class SetupLoadout
{
    static final class Field {
        final String name, note; final List<Integer> ids=new ArrayList<>();
        final boolean guideOnly;
        final Map<Integer,String> itemNotes=new HashMap<>();
        Field(String[] row) { this(row,false); }
        Field(String[] row,boolean guideOnly) { name=row[1]; note=row[3];this.guideOnly=guideOnly; for(String id:row[2].split(",")) if(!id.isEmpty()) ids.add(Integer.parseInt(id)); }
        int slot() { return name.matches("2h[0-9]*")?3:ItemCatalogueIndex.slot(name.replaceAll("[0-9]+$","")); }
        int order() { String number=name.replaceFirst("^2h","weapon").replaceAll("[^0-9]",""); return number.isEmpty()?0:Integer.parseInt(number); }
        boolean inventoryChoice() { return !guideOnly && (note.isEmpty() || note.startsWith("The Wiki chooses ") || note.startsWith("The Vale Totems magiclog variable ")); }
    }
    static final class Table {
        final String kind,context,style; final List<Field> fields=new ArrayList<>();
        Table(String[] row) { kind=row[1];context=row[2];style=row[3]; }
    }
    private static final Map<String,Table> TABLES=new LinkedHashMap<>();
    private static final Map<String,String> INVENTORY_PAIRS=new HashMap<>();
    private static final Map<String,String> SWITCH_NOTES=new HashMap<>();
    static {
        for(String[] row:ItemTaxonomy.readRows("setup-layout-tables.tsv",4)) TABLES.put(row[0],new Table(row));
        for(String[] row:ItemTaxonomy.readRows("setup-layout-fields.tsv",4)) {
            Table table=TABLES.get(row[0]); if(table!=null) table.fields.add(new Field(row));
        }
        Map<String,List<String[]>> choices=new LinkedHashMap<>();
        for(String[] row:ItemTaxonomy.readRows("setup-layout-options.tsv",5))
            choices.computeIfAbsent(row[0]+"/"+row[1],key->new ArrayList<>()).add(row);
        for(Map.Entry<String,Table> entry:TABLES.entrySet()) for(Field field:entry.getValue().fields) {
            List<String[]> rows=choices.get(entry.getKey()+"/"+field.name);
            if(rows==null) continue;
            field.ids.clear();
            for(String[] row:rows) { int id=Integer.parseInt(row[2]);field.ids.add(id);field.itemNotes.put(id,row[4]); }
        }
        for(String[] row:ItemTaxonomy.readRows("setup-inventory-previews.tsv",6)) {
            Table table=TABLES.get(row[0]);
            if(table!=null && table.kind.equals("inventory")) table.fields.add(new Field(new String[]{row[0],row[1],row[2],row[4]},true));
        }
        for(String[] row:ItemTaxonomy.readRows("setup-inventory-pairs.tsv",2)) INVENTORY_PAIRS.put(row[0],row[1]);
        for(String[] row:ItemTaxonomy.readRows("setup-switch-notes.tsv",2)) SWITCH_NOTES.put(row[0],row[1]);
    }
    final String equipmentName,inventoryName;
    final String activity;
    final Map<Integer,List<Integer>> equipment;
    final Map<Integer,Integer> inventory;
    final Map<Integer,Field> inventoryExample;
    final Map<Integer,String> equipmentNotes=new HashMap<>();
    String equipmentNote="";
    String sectionName="";
    boolean wildernessBudget;
    String equipmentSource="";
    final Map<Integer,Integer> equipmentExample=new LinkedHashMap<>();
    Table equipmentTable() { return TABLES.get(equipmentSource); }
    boolean notEnoughGear() {
        if(!wildernessBudget) return false;
        for(SetupLoadout part:sections()) for(int slot:new int[]{0,3,4,7})
            if(part.equipmentTable()!=null && part.equipmentTable().fields.stream().anyMatch(f->f.slot()==slot)
                && part.equipment.getOrDefault(slot,Collections.emptyList()).isEmpty()) return true;
        return false;
    }
    boolean hasBudgetExamples() {
        return wildernessBudget && sections().stream().anyMatch(s->!s.equipmentExample.isEmpty());
    }
    private List<SetupLoadout> sections=Collections.emptyList();
    List<SetupLoadout> sections() { return sections.isEmpty()?Collections.singletonList(this):sections; }
    int sectionCount() { return sections.isEmpty()?1:sections.size(); }
    Set<Integer> itemIds() {
        Set<Integer> result=new LinkedHashSet<>();
        for(SetupLoadout section:sections()) { section.equipment.values().forEach(result::addAll);result.addAll(section.inventory.values()); }
        return result;
    }
    private SetupLoadout(String activity,String equipmentName,String inventoryName,Map<Integer,List<Integer>> equipment,Map<Integer,Integer> inventory,Map<Integer,Field> inventoryExample) {
        this.activity=activity;
        this.equipmentName=equipmentName;this.inventoryName=inventoryName;
        this.equipment=equipment;this.inventory=inventory;this.inventoryExample=inventoryExample;
    }
    static boolean inventoryTable(ActivitySetups.Setup setup) { Table table=TABLES.get(setup.id);return table!=null && table.kind.equals("inventory"); }
    /** A custom view is an explicit item selection; removed items must not return as example icons. */
    SetupLoadout retainItems(Set<Integer> allowed)
    {
        Map<Integer,List<Integer>> gear=new LinkedHashMap<>();
        equipment.forEach((slot,ids)-> { List<Integer> kept=new ArrayList<>();for(int id:ids) if(allowed.contains(id)) kept.add(id);if(!kept.isEmpty()) gear.put(slot,kept); });
        Map<Integer,Integer> bag=new LinkedHashMap<>();inventory.forEach((slot,id)-> { if(allowed.contains(id)) bag.put(slot,id); });
        Map<Integer,Field> example=new LinkedHashMap<>();inventoryExample.forEach((slot,field)-> { if(bag.containsKey(slot)) example.put(slot,field); });
        SetupLoadout result=new SetupLoadout(activity,equipmentName,inventoryName,gear,bag,example);
        equipmentNotes.forEach((id,note)-> { if(allowed.contains(id)) result.equipmentNotes.put(id,note); });
        result.equipmentNote=equipmentNote;
        result.sectionName=sectionName;
        result.wildernessBudget=wildernessBudget;
        result.equipmentSource=equipmentSource;
        // Saved custom selections must not regain removed items as suggestions.
        if(!sections.isEmpty()) {
            List<SetupLoadout> kept=new ArrayList<>();
            for(SetupLoadout section:sections) kept.add(section.retainItems(allowed));
            result.sections=Collections.unmodifiableList(kept);
        }
        return result;
    }
    private static boolean ready(ItemCatalogueIndex.Item item) { return item!=null && !ItemVariantState.needsActivityReview(item.fact); }
    private static boolean inventoryReady(ActivitySetups.Setup setup,ItemCatalogueIndex.Item item) {
        return item!=null && !ItemVariantState.needsInventoryReview(item.fact,setup)
            && SetupItemRequirements.reviewReason(setup.id,item.fact).isEmpty();
    }
    private static boolean equipmentReady(ActivitySetups.Setup setup,ItemCatalogueIndex.Item item) {
        return ready(item) && SetupItemRequirements.reviewReason(setup.id,item.fact).isEmpty()
            && !ItemVariantState.needsRankReview(item.fact,setup.activity,setup.label);
    }
    static SetupLoadout build(List<ActivitySetups.Setup> matched,Map<Integer,ItemCatalogueIndex.Item> owned,Set<Integer> visible,String inventoryContext)
    {
        if(!WildernessLoadout.applies(matched)) return buildSections(matched,owned,visible,inventoryContext);
        Map<Integer,ItemCatalogueIndex.Item> budget=new LinkedHashMap<>();
        owned.forEach((id,item)-> { if(WildernessLoadout.allowed(item)) budget.put(id,item); });
        Set<Integer> shown=new HashSet<>(visible);shown.retainAll(budget.keySet());
        // An explicit inventory choice remains authoritative. The ordinary view
        // prefers a source's low-risk inventory when one is supplied.
        if(inventoryContext.isEmpty()) for(ActivitySetups.Setup setup:matched)
            if(inventoryTable(setup) && setup.label.toLowerCase(Locale.ROOT).contains("low-risk")) { inventoryContext=setup.id;break; }
        SetupLoadout plan=buildSections(WildernessLoadout.defaults(matched),budget,shown,inventoryContext);
        if(plan!=null) WildernessLoadout.finish(plan);
        return plan;
    }
    private static SetupLoadout buildSections(List<ActivitySetups.Setup> matched,Map<Integer,ItemCatalogueIndex.Item> owned,Set<Integer> visible,String inventoryContext)
    {
        // Explicit source selections and saved inventory choices remain stable.
        if(matched.size()<2) return buildOne(matched,owned,visible,inventoryContext);
        Set<String> activities=new HashSet<>();matched.forEach(s->activities.add(s.activity));
        Set<String> families=new HashSet<>();activities.forEach(a->families.add(ActivityMenu.canonical(a).split("/",2)[0]));
        if(families.size()!=1) return buildOne(matched,owned,visible,inventoryContext);
        String activityName=families.iterator().next();
        Map<String,List<ActivitySetups.Setup>> groups=new LinkedHashMap<>();
        boolean recommended=matched.stream().anyMatch(s->TABLES.containsKey(s.id) && TABLES.get(s.id).kind.equals("recommended equipment") && layoutTable(TABLES.get(s.id)));
        for(ActivitySetups.Setup setup:matched) {
            Table table=TABLES.get(setup.id);
            if(table==null || !table.kind.contains("equipment") || !layoutTable(table) || recommended && !table.kind.equals("recommended equipment")) continue;
            String phase=table.context.toLowerCase(Locale.ROOT).contains("phase")?table.context.replaceFirst("^Equipment / ",""):"";
            String style=SetupCompletion.style(table.style);
            String name=phase.isEmpty()?table.style:phase+" / "+(style.isEmpty()?table.style:style.substring(0,1).toUpperCase(Locale.ROOT)+style.substring(1));
            if(activities.size()>1 && !setup.activity.equals(activityName)) name=(setup.activity.startsWith(activityName+"/")?setup.activity.substring(activityName.length()+1):setup.activity.split("/",2)[0])+" / "+name;
            groups.computeIfAbsent(name,k->new ArrayList<>()).add(setup);
        }
        if(groups.size()<2) return buildOne(matched,owned,visible,inventoryContext);
        List<SetupLoadout> parts=new ArrayList<>();
        groups.forEach((name,setups)-> {
            SetupLoadout part=buildOne(setups,owned,visible,inventoryContext);
            if(part!=null) { part.sectionName=name;parts.add(part); }
        });
        if(parts.isEmpty()) return buildOne(matched,owned,visible,inventoryContext);
        SetupLoadout first=parts.get(0);
        SetupLoadout result=new SetupLoadout(activityName,first.equipmentName,first.inventoryName,first.equipment,first.inventory,first.inventoryExample);
        result.equipmentNotes.putAll(first.equipmentNotes);result.equipmentNote=first.equipmentNote;
        result.sections=Collections.unmodifiableList(parts);
        return result;
    }
    private static int slotCount(Table table) {
        Set<Integer> slots=new HashSet<>();for(Field field:table.fields) if(field.slot()>=0) slots.add(field.slot());return slots.size();
    }
    private static boolean layoutTable(Table table) {
        return slotCount(table)>=3 || slotCount(table)>0 && (table.context+" "+table.style).toLowerCase(Locale.ROOT).contains("phase");
    }
    private static SetupLoadout buildOne(List<ActivitySetups.Setup> matched,Map<Integer,ItemCatalogueIndex.Item> owned,Set<Integer> visible,String inventoryContext)
    {
        ActivitySetups.Setup gear=null; int best=-1;
        for(ActivitySetups.Setup setup:matched) {
            Table table=TABLES.get(setup.id); if(table==null || !table.kind.contains("equipment")) continue;
            Set<Integer> slots=new HashSet<>(),available=new HashSet<>();
            for(Field field:table.fields) if(field.slot()>=0) {
                slots.add(field.slot());
                if(field.ids.stream().anyMatch(id->visible.contains(id) && equipmentReady(setup,owned.get(id)) && owned.get(id).slot==field.slot())) available.add(field.slot());
            }
            // Phase-only switches are completed from the parent activity.
            // Ordinary room/utility lists remain in their own alternatives group.
            if(!layoutTable(table)) continue;
            int score=available.size()*100+(table.kind.equals("recommended equipment")?20:0)+slots.size();
            if(score>best) { gear=setup;best=score; }
        }
        ActivitySetups.Setup anchor=gear;
        if(anchor==null) for(ActivitySetups.Setup setup:matched) if(inventoryTable(setup)) { anchor=setup;break; }
        if(anchor==null) return null;
        Table table=TABLES.get(anchor.id);
        Map<Integer,List<Integer>> equipment=new LinkedHashMap<>();
        List<Field> fields=gear==null?new ArrayList<>():new ArrayList<>(table.fields); fields.sort(Comparator.comparingInt(Field::order));
        // Resolve the main weapon first, then select compatible ammunition and
        // dependent equipment using that exact guide choice.
        fields.sort(Comparator.comparingInt((Field f)->f.slot()==3?0:1).thenComparingInt(Field::order));
        Map<Integer,String> equipmentNotes=new HashMap<>();
        Collection<ItemCatalogueIndex.Item> requirements=owned.values();
        for(int pass=0;pass<4;pass++) {
            Map<Integer,List<Integer>> selected=chooseEquipment(fields,gear,owned,visible,requirements,equipmentNotes);
            if(gear!=null) completeEquipment(selected,gear,table,owned,requirements,equipmentNotes);
            if(selected.equals(equipment)) break;
            equipment=selected;
            List<ItemCatalogueIndex.Item> wearing=new ArrayList<>();
            for(List<Integer> options:equipment.values()) if(!options.isEmpty()) wearing.add(owned.get(options.get(0)));
            requirements=wearing;
        }
        ActivitySetups.Setup inventory=null;best=-1;int bestPreference=-1;
        for(ActivitySetups.Setup setup:ActivitySetups.forActivity(anchor.activity)) {
            if(!inventoryTable(setup)) continue;
            Table candidate=TABLES.get(setup.id);
            int score=0;Set<List<Integer>> distinct=new HashSet<>();
            for(Field field:candidate.fields) if(field.inventoryChoice() && distinct.add(field.ids)) {
                // Owning several colours/charge states of one switch must not
                // make an unrelated example appear more complete.
                int available=0;
                for(int id:inventoryAlternatives(setup,field,owned)) if(inventoryReady(setup,owned.get(id)))
                    available=Math.max(available,owned.get(id).slot>=0?20:1);
                score+=available;
            }
            boolean paired=gear!=null && setup.id.equals(INVENTORY_PAIRS.get(gear.id));
            boolean sameStyle=gear!=null && !table.style.isEmpty() && candidate.style.equalsIgnoreCase(table.style);
            boolean sameContext=sameStyle && !table.context.isEmpty() && candidate.context.equalsIgnoreCase(table.context);
            // Different methods can reuse labels such as "Best in slot".
            // Prefer the source pairing/context before comparing owned items.
            int preference=setup.id.equals(inventoryContext)?5:paired?4:sameContext?3:sameStyle?2:matched.contains(setup)?1:0;
            if(preference>bestPreference || preference==bestPreference && score>best)
            { inventory=setup;best=score;bestPreference=preference; }
        }
        Map<Integer,Integer> inventoryItems=new TreeMap<>();
        Map<Integer,Field> inventoryExample=new TreeMap<>();
        if(inventory!=null) for(Field field:TABLES.get(inventory.id).fields) {
            int position=field.order()-1;
            if(!(field.name.matches("[0-9]+") || field.name.startsWith("inventory")) || position<0 || position>=28 || field.ids.isEmpty()) continue;
            inventoryExample.put(position,field);
            if(!field.inventoryChoice()) continue;
            for(int id:inventoryAlternatives(inventory,field,owned))
                if(inventoryReady(inventory,owned.get(id)) && (!InventoryPotionDoses.known(id)
                    || InventoryPotionDoses.listed(field.ids,owned.get(id).fact))) { inventoryItems.put(position,id);break; }
        }
        SetupLoadout result=new SetupLoadout(anchor.activity,gear==null?"":gear.activity+" / "+gear.label,inventory==null?"No inventory example":inventory.label,equipment,inventoryItems,inventoryExample);
        result.equipmentSource=gear==null?"":gear.id;
        result.equipmentNotes.putAll(equipmentNotes);
        result.equipmentNote=gear==null?"":SWITCH_NOTES.getOrDefault(gear.id,"");
        return result;
    }
    private static List<Integer> inventoryAlternatives(ActivitySetups.Setup inventory,Field wanted,Map<Integer,ItemCatalogueIndex.Item> owned)
    {
        List<Integer> result=InventoryGearAlternatives.equivalents(SetupEquipmentChoice.inventoryAlternatives(wanted.ids),owned);
        if(wanted.ids.stream().noneMatch(InventoryGearAlternatives::rangedAccessory)) return result;
        // Only borrow this activity's reviewed ranged accessory choices. A
        // defensive/mechanic shield or a different weapon method is not a swap.
        for(ActivitySetups.Setup guide:ActivitySetups.forActivity(inventory.activity)) {
            Table table=TABLES.get(guide.id);
            if(table==null || !table.kind.equals("recommended equipment") || !SetupCompletion.style(table.style).equals("ranged")) continue;
            Set<Integer> slots=new HashSet<>();
            for(Field field:table.fields) if(field.ids.stream().anyMatch(id->wanted.ids.stream().anyMatch(w->InventoryGearAlternatives.sameCombatItem(w,id)))) slots.add(field.slot());
            slots.removeAll(SetupCompletion.protectedSlots(inventory.activity));
            List<Field> fields=new ArrayList<>(table.fields);fields.sort(Comparator.comparingInt(Field::order));
            for(Field field:fields) if(slots.contains(field.slot()))
                for(int id:InventoryGearAlternatives.equivalents(field.ids,owned)) {
                    ItemCatalogueIndex.Item item=owned.get(id);
                    String note=field.itemNotes.getOrDefault(id,field.note);
                    if(item!=null && item.slot==field.slot() && equipmentReady(guide,item)
                        && SetupEquipmentChoice.allowed(item,note,null,owned.values()) && !result.contains(id)) result.add(id);
                }
        }
        return result;
    }
    /** Fill omissions without promoting a different activity's rankings to this boss's BIS. */
    private static void completeEquipment(Map<Integer,List<Integer>> equipment,ActivitySetups.Setup gear,Table table,
        Map<Integer,ItemCatalogueIndex.Item> owned,Collection<ItemCatalogueIndex.Item> requirements,Map<Integer,String> notes)
    {
        String style=SetupCompletion.style(table.style);
        if(style.isEmpty() && equipment.containsKey(3)) {
            ItemCatalogueIndex.Item weapon=owned.get(equipment.get(3).get(0));
            String role=ItemTaxonomy.weaponRole(ItemVariantState.familyName(weapon.fact));
            style=role==null?"":SetupCompletion.style(role);
        }
        if(style.isEmpty()) return; // skilling methods retain their actual equipment requirements
        Set<Integer> protectedSlots=SetupCompletion.protectedSlots(gear.activity);
        // A listed weapon defines the method. Do not quietly turn an unavailable
        // scorching-bow method into a melee method, or replace a required weapon.
        if(table.fields.stream().anyMatch(f->f.slot()==3)) {
            protectedSlots=new HashSet<>(protectedSlots);protectedSlots.add(3);
        }
        List<ActivitySetups.Setup> donors=new ArrayList<>();
        for(ActivitySetups.Setup candidate:ActivitySetups.forActivity(gear.activity)) {
            Table source=TABLES.get(candidate.id);
            if(source!=null && source.kind.equals("recommended equipment") && SetupCompletion.style(source.style).equals(style)) donors.add(candidate);
        }
        String fallback=style.equals("magic")?"364045:3":style.equals("ranged")?"364045:2":"364045:1";
        ActivitySetups.Setup general=ActivitySetups.byId(fallback);if(general!=null) donors.add(general);
        for(ActivitySetups.Setup donor:donors) {
            List<Field> fields=new ArrayList<>(TABLES.get(donor.id).fields);
            fields.sort(Comparator.comparingInt((Field f)->f.slot()==3?0:1).thenComparingInt(Field::order));
            Set<Integer> missing=new HashSet<>(Arrays.asList(0,1,2,3,4,5,7,9,10,12,13));missing.removeAll(equipment.keySet());
            missing.removeAll(protectedSlots);
            if(!donor.activity.equals(gear.activity)) missing.remove(3);
            ItemCatalogueIndex.Item weapon=equipment.containsKey(3)?owned.get(equipment.get(3).get(0)):null;
            for(Field field:fields) if(missing.contains(field.slot())) for(int id:field.ids) {
                ItemCatalogueIndex.Item item=owned.get(id);String note=field.itemNotes.getOrDefault(id,field.note);
                if(!equipmentReady(donor,item) || item.slot!=field.slot() || !SetupEquipmentChoice.allowed(item,note,weapon,requirements)) continue;
                List<Integer> options=equipment.computeIfAbsent(field.slot(),k->new ArrayList<>());
                if(!options.contains(id)) {
                    options.add(id);notes.put(id,"Owned "+style+" alternative for a missing guide slot; not a new boss-specific ranking. "+note);
                }
                if(field.slot()==3 && weapon==null) weapon=item;
            }
        }
        SetupCompletion.fill(equipment,owned,style,notes,protectedSlots);
    }
    private static Map<Integer,List<Integer>> chooseEquipment(List<Field> fields,ActivitySetups.Setup gear,
        Map<Integer,ItemCatalogueIndex.Item> owned,Set<Integer> visible,Collection<ItemCatalogueIndex.Item> requirements,
        Map<Integer,String> equipmentNotes)
    {
        Map<Integer,List<Integer>> equipment=new LinkedHashMap<>();equipmentNotes.clear();
        ItemCatalogueIndex.Item weapon=null;
        for(Field field:fields) {
            int slot=field.slot();if(slot<0) continue;
            for(int id:field.ids) {
                ItemCatalogueIndex.Item item=owned.get(id);
                if(!visible.contains(id) || !equipmentReady(gear,item) || item.slot!=slot) continue;
                String note=field.itemNotes.getOrDefault(id,field.note);
                if(!SetupEquipmentChoice.allowed(item,note,weapon,requirements)) continue;
                List<Integer> options=equipment.computeIfAbsent(slot,k->new ArrayList<>());
                if(!options.contains(id)) { options.add(id);equipmentNotes.put(id,note); }
                if(slot==3 && weapon==null) weapon=item;
            }
        }
        return equipment;
    }

}

package com.windowmarkers;

import java.util.*;

/** Source-backed supply filters. Names alone never establish healing or ammunition compatibility. */
final class SupplySearch
{
    private static final Map<Integer,Food> FOODS=new HashMap<>();
    private static final Map<String,Set<Integer>> GROUPS=new LinkedHashMap<>();
    private static final Map<String,String> ALIASES=new HashMap<>();
    static {
        for(String[] row:ItemTaxonomy.readRows("food-search-facts.tsv",12)) FOODS.put(Integer.parseInt(row[0]),new Food(row));
        for(String[] row:ItemTaxonomy.readRows("supply-search-groups.tsv",3))
            GROUPS.computeIfAbsent(SearchText.normalize(row[2]),k->new HashSet<>()).add(Integer.parseInt(row[0].substring(2)));
        alias("blowpipe","toxic blowpipe","blazing blowpipe","bp");
        alias("twisted bow","tbow");alias("rune crossbow","rcb");alias("armadyl crossbow","acb");
        alias("zaryte crossbow","zcb");alias("dragon hunter crossbow","dhcb");
        alias("karil crossbow","karils crossbow","karils");
        alias("hunters crossbow","hunter crossbow");alias("hunters sunlight crossbow","sunlight crossbow","hunter sunlight crossbow");
        alias("comp ogre bow","composite ogre bow");alias("cannon","dwarf multicannon","multicannon");
        alias("eclipse atlatl","atlatl");alias("ballista","heavy ballista","light ballista");
        for(String bow:Arrays.asList("oak","willow","maple","yew","magic")) alias(bow+" bow",bow+" shortbow",bow+" longbow");
        alias("magic bow","magic shortbow i","magic shortbow","magic longbow");
        alias("prayer restore","prayer restoration","restore prayer");alias("stat restore","stat restoration","restore stats");
        alias("run energy","energy","run restoration");alias("aggression","aggro","goading");
        alias("poison cure","antipoison");alias("venom cure","antivenom","anti venom");
        alias("antifire","dragonfire","dragonfire protection");alias("special attack","spec","special restore");
    }
    private static void alias(String canonical,String... aliases) { for(String alias:aliases) ALIASES.put(alias,canonical); }
    static boolean foodQuery(String raw) {
        String text=" "+SearchText.normalize(raw)+" ";
        return text.contains(" food ") || text.contains(" foods ");
    }
    static final class Query {
        final Set<String> flags=new HashSet<>();
        final Set<Integer> ids=new HashSet<>();
        boolean food,raw; int minimum=-1;
        String explanation="";
    }
    static Query parse(String raw) {
        String text=SearchText.normalize(raw);
        if(foodQuery(raw)) {
            Query q=new Query();q.food=true;
            for(String word:text.split(" +")) {
                if(word.matches("[0-9]{1,3}")) {
                    if(q.minimum>=0) return null;
                    q.minimum=Integer.parseInt(word);continue;
                }
                switch(word) {
                    case "food":case "foods":case "cooked":case "ready":case "to":case "eat":case "eating":case "healing":case "hp":case "bite":case "bites":case "only":case "cooking":case "inputs":case "area":break;
                    case "raw":case "uncooked":q.raw=true;break;
                    case "fast":case "combo":case "instant":case "delayed":case "multi":case "unrestricted":q.flags.add(word);break;
                    case "overheal":case "overhealing":q.flags.add("overheal");break;
                    case "wilderness":case "blighted":case "restricted":q.flags.add("restricted");break;
                    default:return null;
                }
            }
            if(q.raw) q.ids.addAll(GROUPS.getOrDefault("raw food cooking inputs",Collections.emptySet()));
            return q;
        }
        String kind=text.matches(".*\\b(?:potion|potions)\\b.*")?"potions":text.matches(".*\\b(?:ammo|ammunition)\\b.*")?"ammo":"";
        if(kind.isEmpty()) return null;
        String terms=text.replaceAll("\\b(?:potion|potions|ammo|ammunition|for)\\b"," ").replaceAll(" +"," ").trim();
        terms=ALIASES.getOrDefault(terms,terms);
        if(kind.equals("potions") && Arrays.asList("attack","strength","defence","defense","magic","ranged","agility","fishing","hunter").contains(terms))
            terms=(terms.equals("defense")?"defence":terms)+" boost";
        Query q=new Query();String key=kind+" "+terms;
        // A weapon that uses charges must not fuzzily acquire ammo from a similarly named bow.
        if(kind.equals("ammo") && Arrays.asList("bowfa","bow of faerdhinen","crystal bow","craws bow","webweaver bow").contains(terms)) {
            q.explanation="This weapon uses charges, not interchangeable ammunition. Check its charging requirements.";return q;
        }
        if(kind.equals("potions") && terms.equals("prayer")) {
            q.ids.addAll(GROUPS.getOrDefault("potions prayer restore",Collections.emptySet()));
            q.ids.addAll(GROUPS.getOrDefault("potions prayer regeneration",Collections.emptySet()));
        } else if(GROUPS.containsKey(key)) q.ids.addAll(GROUPS.get(key));
        else return null;
        q.explanation=kind.equals("ammo")?"Compatible ammunition for "+terms+". Weapon, Slayer and area requirements still apply.":"Potion effect: "+terms+". Strength, duration and side effects vary; this is not an activity recommendation.";
        return q;
    }
    static ItemCatalogueIndex.Result find(Query query,Collection<ItemCatalogueIndex.Item> items,int hitpoints) {
        List<ItemCatalogueIndex.Item> selected=new ArrayList<>();Map<Integer,ItemCatalogueIndex.Rank> notes=new HashMap<>();
        int hp=Math.max(1,Math.min(99,hitpoints));
        for(ItemCatalogueIndex.Item item:items) {
            String note=query.explanation;
            if(query.food && !query.raw) {
                Food food=FOODS.get(item.id);
                if(food==null || !food.name.equalsIgnoreCase(item.name) || !food.accepts(query,hp)) continue;
                note=food.explanation(hp);
            } else {
                if(!query.ids.contains(item.id)) continue;
                if(item.name.toLowerCase(Locale.ROOT).startsWith("blighted ")) note+=" Blighted: area restrictions apply.";
                if(query.raw) {
                    // Uncooked ingredients have no ready-to-eat healing value.
                    if(query.minimum>=0 || !query.flags.isEmpty()) continue;
                    note="Raw cooking input; prepare it before eating.";
                }
            }
            selected.add(item);notes.put(item.id,new ItemCatalogueIndex.Rank(0,note));
        }
        selected.sort(Comparator.comparing((ItemCatalogueIndex.Item item)->item.name,String.CASE_INSENSITIVE_ORDER).thenComparingInt(item->item.id));
        return new ItemCatalogueIndex.Result(selected,notes,false);
    }
    private static final class Food {
        final String name,formula;final int instant,delayed;final boolean multi,fast,combo,overheal,restricted;
        Food(String[] row) {
            name=row[1];instant=Integer.parseInt(row[2]);delayed=Integer.parseInt(row[3]);formula=row[4];
            multi=row[5].equals("1");fast=row[6].equals("1");combo=row[7].equals("1");overheal=row[8].equals("1");restricted=row[9].equals("1");
        }
        int immediate(int hp) {
            switch(formula) {
                case "anglerfish":return hp/10+2*(hp/25)+5*(hp/93)+2;
                case "strawberry":return 1+hp*6/100;
                case "watermelon":return 1+hp/20;
                case "sweetcorn":return 1+hp/10;
                default:return instant;
            }
        }
        boolean accepts(Query q,int hp) {
            if(q.flags.contains("fast")&&!fast || q.flags.contains("combo")&&!combo || q.flags.contains("multi")&&!multi
                || q.flags.contains("overheal")&&!overheal || q.flags.contains("delayed")&&delayed==0
                || q.flags.contains("instant")&&delayed>0 || q.flags.contains("restricted")&&!restricted
                || q.flags.contains("unrestricted")&&restricted) return false;
            if(q.minimum<0)return true;
            if(formula.equals("unknown") || formula.equals("random")) return false;
            return immediate(hp)+delayed>=q.minimum;
        }
        String explanation(int hp) {
            String heal=formula.equals("unknown")?"Healing varies; check the item's requirements":formula.equals("random")?"Unreliable healing; excluded from healing thresholds":
                immediate(hp)+" HP immediately"+(delayed>0?" + "+delayed+" delayed HP (pending hunter-food healing can be replaced)":"")+" per bite";
            if(!Arrays.asList("fixed","range","random","unknown").contains(formula))heal+=" at your base "+hp+" Hitpoints";
            if(formula.equals("range"))heal+=" (minimum; the actual amount varies)";
            return heal+"."+(multi?" Multiple bites per item; thresholds use one bite.":"")+(combo?" Combo-eating food.":"")
                +(fast?" Non-standard attack/eating delay.":"")+(overheal?" Can overheal; PvP restrictions apply.":"")
                +(restricted?" Blighted: Wilderness/PvP-world restrictions apply.":"");
        }
    }
}

package com.windowmarkers;

import java.awt.*;

/** The same guide tiers, colours and labels in the bank and GE. */
final class TierPresentation
{
    static String ordinal(int tier) { return tier==1?"1st":tier==2?"2nd":tier==3?"3rd":""; }
    static String key(WindowMarkersConfig config) {
        StringBuilder text=new StringBuilder("<html>Guide tiers: ");
        for(int i=1;i<=3;i++) {
            if(i>1) text.append(" · ");
            text.append("<font color='#").append(String.format("%06x",colour(config,i).getRGB()&0xffffff)).append("'>").append(ordinal(i)).append("</font>");
        }
        return text.append("</html>").toString();
    }
    static Color colour(WindowMarkersConfig config,int tier) {
        return tier==1?config.geFirstColour():tier==2?config.geSecondColour():config.geThirdColour();
    }
    static ItemCatalogueIndex.Rank merge(ItemCatalogueIndex.Rank a,ItemCatalogueIndex.Rank b) {
        if(a.tier==b.tier && a.role.equals(b.role)) return a;
        return new ItemCatalogueIndex.Rank(0,"Different selected guide roles or requirements; select a single setup to see its tier.");
    }
    static void draw(Graphics2D g,Rectangle grid,int tier,WindowMarkersConfig config) {
        if(tier<1 || tier>3) return;
        Color colour=colour(config,tier);
        g.setStroke(new BasicStroke(2)); BorderRenderer.plain(g,grid,colour);
        drawLabel(g,grid,tier,config);
    }
    static void drawLabel(Graphics2D g,Rectangle grid,int tier,WindowMarkersConfig config) {
        if(tier<1 || tier>3) return;
        Color colour=colour(config,tier);
        g.setFont(new Font("Arial",Font.BOLD,9));
        String text=ordinal(tier); FontMetrics fm=g.getFontMetrics();
        int width=fm.stringWidth(text)+4,height=fm.getHeight();
        int x=grid.x+grid.width-width,y=grid.y+grid.height-height;
        g.setColor(new Color(15,15,15,220));g.fillRoundRect(x,y,width,height,3,3);
        g.setColor(colour);g.drawRoundRect(x,y,width-1,height-1,3,3);
        g.setColor(Color.WHITE);g.drawString(text,x+2,y+fm.getAscent());
    }
}

package com.windowmarkers;

import java.util.*;

/** Bundled, audited Wiki item identities and useful roles. Does not imply activity eligibility. */
final class WikiCatalogue
{
    static final class Entry
    {
        final String facet, group;
        Entry(String facet,String group) { this.facet=facet; this.group=group; }
    }
    private static final Map<String,List<Entry>> INDEX=new HashMap<>();
    private static final Map<String,List<Entry>> CATEGORY_SUPPLEMENT=new HashMap<>();
    private static final Map<String,List<Entry>> ROLE_EXCLUSIONS=new HashMap<>();
    private static final Set<Integer> AMBIGUOUS_NAMES=new HashSet<>();
    private static final Set<Integer> EXCLUDED_IDENTITIES=new HashSet<>();
    static
    {
        for (String[] row : ItemTaxonomy.readRows("item-catalogue.tsv",3))
        { INDEX.computeIfAbsent(row[0],k -> new ArrayList<>()).add(new Entry(row[1],row[2])); }
        for (String[] row:ItemTaxonomy.readRows("ambiguous-item-names.tsv",1))
        { AMBIGUOUS_NAMES.add(Integer.parseInt(row[0])); }
        for (String[] row:ItemTaxonomy.readRows("catalogue-identity-exclusions.tsv",1))
        { EXCLUDED_IDENTITIES.add(Integer.parseInt(row[0])); }
        // Exact-ID Wiki category evidence supplements organizational roles only.
        // Raid recommendations and ranked alternatives use their own reviewed resources.
        for (String resource : new String[]{"wiki-category-supplement.tsv","combat-equivalence-categories.tsv","wiki-recipe-roles.tsv","wiki-role-updates.tsv","supply-search-groups.tsv"})
        for (String[] row : ItemTaxonomy.readRows(resource,3))
        {
            if (!row[0].matches("I:[0-9]+")) { throw new IllegalStateException("Wiki category requires an exact item ID"); }
            List<Entry> entries=CATEGORY_SUPPLEMENT.computeIfAbsent(row[0],k -> new ArrayList<>());
            if (entries.stream().noneMatch(e -> e.facet.equals(row[1]) && e.group.equals(row[2])))
            { entries.add(new Entry(row[1],row[2])); }
        }
        for (String[] row : ItemTaxonomy.readRows("catalogue-role-exclusions.tsv",3))
        {
            if (!row[0].matches("I:[0-9]+")) { throw new IllegalStateException("Role correction requires an exact item ID"); }
            ROLE_EXCLUSIONS.computeIfAbsent(row[0],k -> new ArrayList<>()).add(new Entry(row[1],row[2]));
        }
    }
    static List<Entry> entries(AutoCategories.Item item)
    {
        if (EXCLUDED_IDENTITIES.contains(item.id)) { return Collections.emptyList(); }
        List<Entry> result=INDEX.get("I:"+item.id);
        boolean nameSafe=!AMBIGUOUS_NAMES.contains(item.id);
        if (result==null && nameSafe) { result=INDEX.get("N:"+item.name); }
        if (result==null && nameSafe) { result=INDEX.get("N:"+ItemTaxonomy.baseName(item.name)); }
        if (result==null && nameSafe && item.name.matches(".*\\s*\\([1-8]\\)$"))
        {
            List<Entry> charged=INDEX.get("N:"+item.name.replaceFirst("\\s*\\([1-8]\\)$",""));
            if (charged!=null && charged.stream().anyMatch(e -> e.facet.equals("travel"))) { result=charged; }
        }
        List<Entry> supplement=CATEGORY_SUPPLEMENT.get("I:"+item.id);
        List<Entry> exclusions=ROLE_EXCLUSIONS.get("I:"+item.id);
        if (supplement==null && exclusions==null) { return result==null ? Collections.emptyList() : result; }
        // Preserve reviewed name aliases when adding an exact-ID category record.
        List<Entry> combined=result==null ? new ArrayList<>() : new ArrayList<>(result);
        if (supplement!=null) for (Entry entry:supplement)
        {
            if (combined.stream().noneMatch(e -> e.facet.equals(entry.facet) && e.group.equals(entry.group)))
            { combined.add(entry); }
        }
        // Correct only the reviewed identity and role, including a name fallback
        // from a different item with the same display name. Shared indexes stay intact.
        if (exclusions!=null)
        { combined.removeIf(e -> exclusions.stream().anyMatch(x -> x.facet.equals(e.facet) && x.group.equals(e.group))); }
        return combined;
    }
    static boolean hasFacet(AutoCategories.Item item,String facet)
    { return entries(item).stream().anyMatch(e -> e.facet.equals(facet)); }

    static Set<String> groups()
    {
        Set<String> groups=new TreeSet<>();
        for(Map<String,List<Entry>> index:Arrays.asList(INDEX,CATEGORY_SUPPLEMENT))
            for(List<Entry> entries:index.values()) for(Entry entry:entries) groups.add(entry.group);
        return groups;
    }

    static String category(AutoCategories.Item item,AutoCategories.Preset preset)
    {
        if (preset==AutoCategories.Preset.FOOD_AND_POTIONS && !hasFacet(item,"supply") && !hasFacet(item,"restricted") && !item.action("Eat") && !item.action("Drink")) { return null; }
        Entry best=null;
        for (Entry entry : entries(item))
        {
            if (!accepts(preset,entry) || CatalogueArchive.hidden(entry.group)) { continue; }
            if (best==null || priority(entry)<priority(best) || (priority(entry)==priority(best) && entry.group.compareTo(best.group)<0)) { best=entry; }
        }
        return best==null ? null : best.group;
    }
    private static int priority(Entry e)
    {
        switch (e.facet)
        {
            case "outfit": return 0;
            case "restricted": return 1;
            case "boost": return 2;
            case "skilling": return e.group.contains("materials") || e.group.contains("ingredients") || e.group.contains("products")
                || e.group.endsWith("recipe inputs") || e.group.endsWith("guild access") || e.group.endsWith("pouch protection") || e.group.endsWith("warm clothing") ? 9 : 3;
            case "travel": return 4;
            case "combat": return e.group.startsWith("Prayer") ? 7 : 5;
            case "supply": return 6;
            case "utility": return 8;
            case "quest": return 10;
            case "clue": return 11;
            default: return 12;
        }
    }
    private static boolean accepts(AutoCategories.Preset p,Entry e)
    {
        switch (p)
        {
            case ALL_CATEGORIES: case BROAD_TYPES: return true;
            case SKILLING: return e.facet.equals("outfit") || e.facet.equals("skilling") || (e.facet.equals("boost") && !e.group.startsWith("Combat"));
            case SKILLING_OUTFITS: return e.facet.equals("outfit");
            case COMBAT_GROUPS: return e.facet.equals("combat") || (e.facet.equals("boost") && e.group.startsWith("Combat"));
            case FOOD_AND_POTIONS: return e.facet.equals("supply") || e.facet.equals("boost") || e.facet.equals("restricted");
            case TRAVEL_AND_UTILITY: return e.facet.equals("travel") || e.facet.equals("utility");
            case QUESTS_AND_CLUES: return e.facet.equals("quest") || e.facet.equals("clue");
            case COSMETICS: return e.facet.equals("cosmetic");
            default: return false;
        }
    }
    static String source(AutoCategories.Preset preset)
    {
        switch (preset)
        {
            case SKILLING: case SKILLING_OUTFITS: return "https://oldschool.runescape.wiki/w/Skilling_equipment";
            case FOOD_AND_POTIONS: return "https://oldschool.runescape.wiki/w/Potions";
            case TRAVEL_AND_UTILITY: return "https://oldschool.runescape.wiki/w/Container_items";
            case QUESTS_AND_CLUES: return "https://oldschool.runescape.wiki/w/Quest_items";
            case COSMETICS: return "https://oldschool.runescape.wiki/w/Clothes";
            case ALL_CATEGORIES: case BROAD_TYPES: case COMBAT_GROUPS: return "https://oldschool.runescape.wiki/w/Equipment";
            default: return RaidRecommendations.source(preset);
        }
    }
}

package com.windowmarkers;

import java.util.*;

/** Budget defaults for bank planning, not a price or death-protection calculation. */
final class WildernessLoadout
{
    private static final Set<String> ACTIVITIES=new HashSet<>(Arrays.asList("Callisto","Artio","Venenatis","Spindel",
        "Vet'ion","Calvar'ion","Scorpia","Chaos Fanatic","Chaos Elemental","Revenants","Krystilia",
        "King Black Dragon","Green dragon","Chaos Temple (church)","Abyss","Chest (Rogues' Castle)"));
    private static final Map<Integer,String[]> BUDGET=new HashMap<>();
    private static final Set<Integer> EQUIPMENT=new HashSet<>();
    static {
        for(String[] row:ItemTaxonomy.readRows("wilderness-budget-items.tsv",4)) BUDGET.put(Integer.parseInt(row[0]),row);
        for(String[] row:ItemTaxonomy.readRows("ge-item-slots.tsv",3))
            if(Integer.parseInt(row[1])>=0) EQUIPMENT.add(Integer.parseInt(row[0]));
    }
    private WildernessLoadout() { }
    static boolean applies(List<ActivitySetups.Setup> matched) {
        return matched.size()>1 && ACTIVITIES.contains(matched.get(0).activity)
            && matched.stream().allMatch(s->s.activity.equals(matched.get(0).activity));
    }
    static boolean allowed(ItemCatalogueIndex.Item item) {
        if(item.slot<0 && !EQUIPMENT.contains(item.id)) return true;
        String[] row=BUDGET.get(item.id);
        return row!=null && row[1].equalsIgnoreCase(item.name) && Integer.parseInt(row[2])==item.slot;
    }
    static boolean allowedPreview(int id) { return !EQUIPMENT.contains(id) || BUDGET.containsKey(id); }
    static boolean wildernessWeapon(int id) { return BUDGET.containsKey(id) && BUDGET.get(id)[3].equals("wilderness weapon"); }
    static List<ActivitySetups.Setup> defaults(List<ActivitySetups.Setup> matched) {
        List<ActivitySetups.Setup> result=new ArrayList<>();
        for(ActivitySetups.Setup setup:matched) {
            String label=setup.label.toLowerCase(Locale.ROOT);
            if(!label.contains("high-risk") && !label.contains("bis smuggle") && !label.contains("gravestone")) result.add(setup);
        }
        return result;
    }
    // Display-only preferences inside the existing budget policy and the exact
    // source's equipment fields. They never enter owned selection or filtering.
    private static final List<Integer> EXAMPLES=Arrays.asList(3749,10499,1704,2503,2497,2491,6328,12788,892,
        4089,2412,4091,4093,7460,4097,28585,11907,1434,3105,3842,12612);
    private static ItemCatalogueIndex.Item exampleItem(int id) {
        String[] row=BUDGET.get(id);if(row==null) return null;
        int slot=Integer.parseInt(row[2]);
        return new ItemCatalogueIndex.Item(new AutoCategories.Item(id,row[1],true,new String[]{"Wear"},0,0,0,slot),row[1],slot);
    }
    private static void recommendMissing(SetupLoadout part) {
        SetupLoadout.Table table=part.equipmentTable();if(table==null) return;
        List<SetupLoadout.Field> fields=new ArrayList<>(table.fields);
        fields.sort(Comparator.comparingInt((SetupLoadout.Field f)->f.slot()==3?0:1).thenComparingInt(SetupLoadout.Field::order));
        Map<Integer,List<Integer>> candidates=new LinkedHashMap<>();Map<Integer,String> notes=new HashMap<>();
        for(var field:fields) if(field.slot()>=0) for(int id:field.ids) {
            var item=exampleItem(id);
            if(item==null || item.slot!=field.slot() || wildernessWeapon(id) || ItemVariantState.needsActivityReview(item.fact)
                || !SetupItemRequirements.reviewReason(part.equipmentSource,item.fact).isEmpty()) continue;
            candidates.computeIfAbsent(item.slot,k->new ArrayList<>()).add(id);
            notes.put(id,field.itemNotes.getOrDefault(id,field.note));
        }
        ItemCatalogueIndex.Item weapon=part.equipment.containsKey(3)?exampleItem(part.equipment.get(3).get(0)):null;
        for(var entry:candidates.entrySet()) {
            List<Integer> existing=part.equipment.getOrDefault(entry.getKey(),Collections.emptyList());
            if(!existing.isEmpty() && (entry.getKey()!=13 || weapon==null
                || SetupEquipmentChoice.allowed(exampleItem(existing.get(0)),"",weapon,Collections.emptyList()))) continue;
            entry.getValue().sort(Comparator.comparingInt(id->EXAMPLES.contains(id)?EXAMPLES.indexOf(id):Integer.MAX_VALUE));
            for(int id:entry.getValue()) {
                var item=exampleItem(id);
                if(!SetupEquipmentChoice.allowed(item,notes.get(id),weapon,Collections.emptyList())) continue;
                part.equipmentExample.put(entry.getKey(),id);
                if(entry.getKey()==3) weapon=item;
                break;
            }
        }
    }
    static void finish(SetupLoadout plan) {
        plan.wildernessBudget=true;
        for(SetupLoadout part:plan.sections()) {
            part.wildernessBudget=true;
            recommendMissing(part);
            // Keep source positions, supplies and meaningful empty slots. A
            // costly equipment switch must not survive as a grey recommendation.
            for(var iterator=part.inventoryExample.entrySet().iterator();iterator.hasNext();) {
                var entry=iterator.next();var field=entry.getValue();
                List<Integer> kept=new ArrayList<>();for(int id:field.ids) if(allowedPreview(id)) kept.add(id);
                if(kept.isEmpty()) { iterator.remove();part.inventory.remove(entry.getKey()); }
                else if(!kept.equals(field.ids)) {
                    SetupLoadout.Field copy=new SetupLoadout.Field(new String[]{"",field.name,"",field.note},field.guideOnly);
                    copy.ids.addAll(kept);copy.itemNotes.putAll(field.itemNotes);entry.setValue(copy);
                }
            }
            part.equipment.forEach((slot,ids)-> {
                for(int id:ids) part.equipmentNotes.put(id,(wildernessWeapon(id)
                    ?"Owned Wilderness weapon; charges and ether add risk. "
                    :"Owned budget choice for Wilderness travel/content. ")
                    +"Check items kept on death; no protection is assumed. "+part.equipmentNotes.getOrDefault(id,""));
            });
        }
    }
}

